const REPORT_MAX_RANGE_DAYS=1827;
function reportRangeValidation(from,to,maxDays=REPORT_MAX_RANGE_DAYS){
  const parse=value=>{
    const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if(!match)return null;
    const time=Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3]));
    return new Date(time).toISOString().slice(0,10)===value?time:null;
  };
  const start=parse(from),end=parse(to);
  if(start===null||end===null||end<start)return {ok:false,reason:'Choose a valid report range.'};
  const days=Math.round((end-start)/864e5)+1;
  if(days>maxDays)return {ok:false,reason:`Choose a range of ${maxDays.toLocaleString('en-SG')} days or fewer.`};
  return {ok:true,days};
}
function lifecycleAnswerProjection(payload){
  const source=payload&&typeof payload==='object'?payload:{};
  const metrics=source.metrics&&typeof source.metrics==='object'?source.metrics:{};
  const coverage=source.coverage&&typeof source.coverage==='object'?source.coverage:{};
  const eligibleTransactions=Number(coverage.eligible_transactions||0);
  const identifiedTransactions=Number(coverage.identified_transactions||0);
  const identifiedTransactionPct=coverage.identified_transaction_pct==null
    ?null:Number(coverage.identified_transaction_pct);
  return {
    status:String(source.status||'unavailable'),
    usable:source.status==='ok'&&eligibleTransactions>0&&identifiedTransactions>0,
    metrics,
    eligibleTransactions,
    identifiedTransactions,
    identifiedTransactionPct
  };
}
function expenseAmountProjection(expense,baseCurrency='SGD'){
  const sourceCurrency=String(expense?.currency||'').trim().toUpperCase();
  const normalizedBase=String(baseCurrency||'SGD').trim().toUpperCase();
  const amountCents=Number(expense?.amount_cents);
  const rateValue=expense?.fx_rate_to_base;
  const rate=rateValue===null||rateValue===undefined?NaN:Number(rateValue);
  const validCurrency=/^[A-Z]{3}$/.test(sourceCurrency)&&/^[A-Z]{3}$/.test(normalizedBase);
  const valid=validCurrency&&Number.isSafeInteger(amountCents)&&Number.isFinite(rate)&&rate>0;
  if(!valid)return {valid:false,originalLabel:null,baseLabel:null,baseCents:null,showBase:false};
  const baseCents=Math.round(amountCents*rate);
  if(!Number.isSafeInteger(baseCents))return {valid:false,originalLabel:null,baseLabel:null,baseCents:null,showBase:false};
  const format=(currency,cents)=>`${currency} ${(cents/100).toFixed(2)}`;
  return {
    valid:true,
    originalLabel:format(sourceCurrency,amountCents),
    baseLabel:format(normalizedBase,baseCents),
    baseCents,
    showBase:sourceCurrency!==normalizedBase||Math.abs(rate-1)>1e-12
  };
}
function staffPerformanceAggregation(rows,staffRows){
  const names=Object.fromEntries((Array.isArray(staffRows)?staffRows:[])
    .map(staff=>[staff.id,staff.full_name||'Team member']));
  const byStaff={};
  Object.keys(names).forEach(id=>{byStaff[id]={ledgerRecords:0,revenueRecords:0,revenue:0,commission:0}});
  (Array.isArray(rows)?rows:[]).forEach(row=>{
    const key=row.staff_id||'__unattributed';
    if(!byStaff[key])byStaff[key]={ledgerRecords:0,revenueRecords:0,revenue:0,commission:0};
    const amount=Number(row.amount_cents||0),commission=Number(row.commission_cents||0);
    byStaff[key].ledgerRecords+=1;
    byStaff[key].commission+=commission;
    if(row.counts_as_revenue===true){
      byStaff[key].revenueRecords+=1;
      byStaff[key].revenue+=amount;
    }
  });
  const keys=Object.keys(byStaff).sort((a,b)=>{
    if(a==='__unattributed')return 1;
    if(b==='__unattributed')return -1;
    return (names[a]||'').localeCompare(names[b]||'');
  });
  const totals=keys.reduce((total,key)=>({
    ledgerRecords:total.ledgerRecords+byStaff[key].ledgerRecords,
    revenueRecords:total.revenueRecords+byStaff[key].revenueRecords,
    revenue:total.revenue+byStaff[key].revenue,
    commission:total.commission+byStaff[key].commission
  }),{ledgerRecords:0,revenueRecords:0,revenue:0,commission:0});
  return {names,byStaff,keys,totals};
}
function waitlistTodaySummary(rows,dayStartMs){
  const all=Array.isArray(rows)?rows:[];
  const queue=all.filter(row=>row.status==='waiting'||row.status==='contacted');
  const today=all.filter(row=>new Date(row.created_at).getTime()>=dayStartMs);
  return {
    queue,
    added:today.length,
    bookedToday:today.filter(row=>row.status==='booked').length
  };
}
async function fetchAllRows(makeQuery,pageSize=DATA_API_PAGE_SIZE){
  const rows=[];
  let from=0,total=null;
  for(;;){
    const {data,error,count}=await makeQuery().range(from,from+pageSize-1);
    if(error) throw error;
    if(Number.isInteger(count)) total=count;
    rows.push(...(data||[]));
    if(!data||!data.length||(total!==null&&rows.length>=total)||(total===null&&data.length<pageSize)) return rows;
    from=rows.length;
  }
}
async function fetchAllRowsResult(makeQuery,pageSize=DATA_API_PAGE_SIZE){
  try{return {data:await fetchAllRows(makeQuery,pageSize),error:null}}
  catch(error){return {data:null,error}}
}
/* A valid visit is the original immutable visit row only while no compensating reversal
   references it. Reversal rows never become visits themselves. Keeping this one helper for
   Customer 360 and bring-back audiences prevents a fully reversed visit remaining the
   customer's newest visit merely because the original row is intentionally retained. */
function validVisitSales(rows){
  const all=Array.isArray(rows)?rows:[];
  const reversedOriginalIds=new Set(all.filter(row=>row?.reversal_of).map(row=>row.reversal_of));
  return all.filter(row=>row?.counts_as_visit&&row.reversal_of==null&&!reversedOriginalIds.has(row.id));
}
async function fetchRowsByIds(table,columns,ids,idColumn='id',chunkSize=500){
  const unique=[...new Set((ids||[]).filter(Boolean))],rows=[];
  for(let offset=0;offset<unique.length;offset+=chunkSize){
    const {data,error}=await sb.from(table).select(columns).in(idColumn,unique.slice(offset,offset+chunkSize));
    if(error)throw error;
    rows.push(...(data||[]));
  }
  return rows;
}
