/* ---------- V452: ONE dismiss discipline for every popover in the app ----------------------
   Before this each popover invented its own, and no two agreed:
     .profile .menu     JS flag + a ONE-SHOT document click listener re-armed on every render;
                        Escape only when focus happened to be inside the panel.
     .notif-menu        same one-shot listener; no Escape at all.
     .business-workspace-switch   a bare <details>. No outside click, no Escape, nothing.
     mobile search sheet          closed on its own backdrop only.
     .grow-row-menu-v351          bare <details>, three per row set, all openable at once.
   And NOTHING closed on navigation. That is the owner-reported bug: the workspace switcher's
   links live INSIDE #profwrap, so the outside-click listener can never fire for them, they carry
   no onclick, and route() never touched the flags — so the account menu survived a workspace
   switch and the route change that followed it, and reappeared open on the next page.

   The registry is SELECTOR-DRIVEN and re-queried on every event, deliberately: this app rewrites
   #profwrap/#bellwrap outerHTML on each toggle and re-renders whole pages, so any registry that
   held element references would hold corpses.

   NOT REGISTERED, on purpose: the ~20 disclosure <details> (appointment-more, staff-mobile-more,
   loyalty-optional-v235, till-who-v373, studio-advanced, card sections …). Those are expandable
   sections, not popovers — they are MEANT to stay open while you work elsewhere on the page. */
/* The ONE list of what counts as a popover. Both the interactive controller below and the
   core-safe reset used by route() read these, so "which elements dismiss" has a single source
   of truth even though the two paths differ in whether they repaint. */
const POPOVER_SWITCH_SEL_V452='details.business-workspace-switch';
const POPOVER_ROWMENU_SEL_V452='details.grow-row-menu-v351';
const POPOVER_DETAILS_SEL_V452=POPOVER_SWITCH_SEL_V452+','+POPOVER_ROWMENU_SEL_V452;
const POPOVER_SHEET_ID_V452='mobileSearchSheet';
/* Called from route(). It deliberately does NOT reach renderProfile/renderBell, for two reasons:
   the shell is about to be rebuilt so repainting the outgoing header is wasted work, and — the
   load-bearing one — scripts/quality/split-app-bundle.mjs severs route's edges to the SURFACE
   ENTRY POINTS only. A route -> renderProfile edge is not severed, so it drags the entire
   business surface into the always-loaded core chunk (measured: core 472KB -> 2824KB, business
   2368KB -> 21KB). Keep this function free of business-surface names. */
function resetPopoverStateV452(){
  profileOpen=false;
  bellOpen=false;
  const doc=globalThis.document;
  if(!doc)return;
  for(const node of doc.querySelectorAll(POPOVER_DETAILS_SEL_V452))node.open=false;
  doc.getElementById(POPOVER_SHEET_ID_V452)?.removeAttribute('open');
}
let popoverPageV452='';
let popoverDismissWiredV452=false;
const popoverKindsV452=()=>[
  {name:'profile',
   roots:()=>[$('profwrap')].filter(Boolean),
   isOpen:()=>profileOpen,
   close:(root,quiet)=>{if(!profileOpen)return false;profileOpen=false;if(!quiet)renderProfile(popoverPageV452);return true},
   triggerId:'profWho'},
  {name:'notifications',
   roots:()=>[$('bellwrap')].filter(Boolean),
   isOpen:()=>bellOpen,
   close:(root,quiet)=>{if(!bellOpen)return false;bellOpen=false;if(!quiet)renderBell(popoverPageV452);return true},
   triggerId:'bellBtn'},
  {name:'workspace-switch',
   roots:()=>[...document.querySelectorAll(POPOVER_SWITCH_SEL_V452)],
   isOpen:root=>!!root.open,
   close:root=>{if(!root.open)return false;root.open=false;return true},
   closeOnInnerActivate:true},
  {name:'mobile-search',
   /* The sheet IS its own full-viewport backdrop, so "click outside the root" can never fire for
      it; its existing backdrop handler stays. What it gains here is Escape from anywhere and
      closing on navigation. */
   roots:()=>[$(POPOVER_SHEET_ID_V452)].filter(Boolean),
   isOpen:root=>root.hasAttribute('open'),
   close:root=>{if(!root.hasAttribute('open'))return false;root.removeAttribute('open');return true},
   triggerId:'mobileSearchOpen'},
  {name:'grow-row-menu',
   roots:()=>[...document.querySelectorAll(POPOVER_ROWMENU_SEL_V452)],
   isOpen:root=>!!root.open,
   close:root=>{if(!root.open)return false;root.open=false;return true},
   closeOnInnerActivate:true},
];
/* quiet=true skips the re-render: on navigation the shell is about to be rebuilt anyway, so
   repainting the outgoing header first is wasted work. */
function closeAllPopoversV452(exceptName,quiet){
  let closed=0;
  for(const kind of popoverKindsV452()){
    if(exceptName&&kind.name===exceptName)continue;
    for(const root of kind.roots()){
      try{if(kind.close(root,quiet))closed++}catch(error){console.error(error)}
    }
  }
  return closed;
}
function wirePopoverDismissV452(page){
  if(page!==undefined)popoverPageV452=page;
  if(popoverDismissWiredV452)return;
  popoverDismissWiredV452=true;
  /* Bubble phase, and nothing here calls stopPropagation: an item's own handler must run
     untouched. The grow row menus' buttons in particular do NOT stopPropagation, so a capture-
     phase closer or a synchronous one could pull the ground out from under them. */
  document.addEventListener('click',event=>{
    for(const kind of popoverKindsV452()){
      /* The trigger is not always inside the popover it opens: the mobile search sheet's button
         sits in the app bar while the sheet is a separate full-screen node, so without this the
         very click that opened it would immediately close it again. (The profile and bell
         triggers happen to stopPropagation, so they never reached here — a difference this
         controller should not depend on.) */
      if(kind.triggerId&&event.target.closest?.('#'+kind.triggerId))continue;
      for(const root of kind.roots()){
        if(!kind.isOpen(root))continue;
        if(!root.contains(event.target)){kind.close(root);continue}
        /* A menu whose items act or navigate must close when one is chosen. Deferred one tick so
           the item's handler runs first, against a DOM that is still the one it was rendered
           into. */
        if(kind.closeOnInnerActivate
          &&event.target.closest?.('a[href],button,[role="button"]')
          &&!event.target.closest?.('summary'))setTimeout(()=>kind.close(root),0);
      }
    }
  });
  document.addEventListener('keydown',event=>{
    if(event.key!=='Escape')return;
    for(const kind of popoverKindsV452()){
      for(const root of kind.roots()){
        if(!kind.isOpen(root))continue;
        event.preventDefault();
        /* Escape must not strand the keyboard: focus goes back to whatever opened the thing. */
        const trigger=kind.triggerId?$(kind.triggerId):root.querySelector('summary');
        kind.close(root);
        (kind.triggerId?$(kind.triggerId):trigger)?.focus?.();
        return;
      }
    }
  });
}

/* Opening/closing the profile menu must NOT touch #main or #navwrap — it used to call
   renderShell(page), which also re-invokes the current page's render function (full
   Supabase refetch, chart re-animation, any custom date range reset). This widget now
   re-renders only itself. */
function wireProfile(page){
  wirePopoverDismissV452(page);
  /* V452: opening one popover closes every other, through the shared controller, instead of
     this widget knowing the bell exists. */
  $('profWho').onclick=(e)=>{e.stopPropagation();profileOpen=!profileOpen;if(profileOpen)closeAllPopoversV452('profile');renderProfile(page);};
  /* V219. Owner: "i need a drop down in the header to select which branch they want to view now".
     V210 moved this selector OUT of the profile menu and into the top bar, but left its
     hydration inside `if(profileOpen)`. The mount div was rendered on every page and filled on
     none of them, so the header carried an invisible empty box. It is populated whenever the
     shell is wired, which is what the top-bar position always meant. */
  hydrateProfileBranchSelectorV158(page);
  if(profileOpen){
    /* V452: Escape (and the focus return to the account chip) is the shared controller's job now.
       It used to be bound to the panel, so it only fired when focus was already inside it. */
    const profileNameForm=$('profileNameFormV158');
    if(profileNameForm)profileNameForm.onsubmit=async(e)=>{
      e.preventDefault();
      const input=$('profileDisplayNameV158'),status=$('profileNameStatusV158');
      const name=String(input?.value||'').trim();
      if(name.length<2){if(status)status.textContent='Enter your name.';return;}
      const button=profileNameForm.querySelector('button[type="submit"]');
      CUI.setButtonBusy(button,{busy:true,label:'Saving…'});
      try{
        const {data,error}=await sb.auth.updateUser({data:{full_name:name,name}});
        if(error)throw error;
        if(data?.user)S.user=data.user;
        else S.user={...S.user,user_metadata:{...(S.user?.user_metadata||{}),full_name:name,name}};
        await sb.from('staff').update({full_name:name}).eq('business_id',S.biz.id).eq('user_id',S.user.id);
        if(status)status.textContent='Name saved.';
        renderProfile(page);
      }catch(error){
        console.error(error);
        if(status)status.textContent='Name could not be saved.';
      }finally{
        CUI.setButtonBusy(button,{busy:false});
      }
    };
    $('pmSignout').onclick=async(e)=>{e.preventDefault();killChannels();await sb.auth.signOut({scope:'local'});resetClientSessionState();nav('#/')};
    const pmSetup=$('pmSetup');if(pmSetup)pmSetup.onclick=()=>{profileOpen=false};
    const pmS=$('pmSettings');if(pmS) pmS.onclick=()=>{profileOpen=false};
    /* V368: the business QR, in a dialog, from the account menu. */
    const pmQrV368=$('pmBusinessQrV368');
    if(pmQrV368)pmQrV368.onclick=event=>{
      event.preventDefault();profileOpen=false;
      openBusinessQrModalV368();
    };
    const pmT=$('pmTeam');if(pmT) pmT.onclick=()=>{profileOpen=false};
    const pmP=$('pmPlatform');if(pmP) pmP.onclick=()=>{profileOpen=false};
    const pmW=$('pmWallet');if(pmW) pmW.onclick=()=>{profileOpen=false};
    /* v188: the profile menu links to the data-request page instead of opening a self-service
       deletion dialog; closing an account goes through Peekaa. */
    const pmD=$('pmDeleteAccount');if(pmD)pmD.onclick=()=>{profileOpen=false};
    /* V452: click-away is the shared controller's, installed once at boot rather than re-armed
       on every render of this menu. */
  }
}
function renderProfile(page){
  const wrap=$('profwrap');
  if(!wrap) return;
  wrap.outerHTML=profileHtml();
  wireProfile(page);
}

/* ---------- realtime notifications (bell, left of the profile chip) ----------
   One realtime channel per signed-in session, built once against the current S.biz and
   reused across every route change (route() -> renderShell() -> initNotifications() runs
   on every navigation, but ensureRealtimeChannel() is a no-op once a channel for this
   business already exists — tearing it down and rebuilding on every route change would be
   wasteful and could miss events landing in the gap). killChannels() is the only thing that
   removes it, called on sign-out (mirrors killCharts()). */
function timeAgo(iso){
  if(!iso) return '';
  const s=Math.max(0,(Date.now()-new Date(iso).getTime())/1000);
  if(s<60) return 'just now';
  if(s<3600) return Math.floor(s/60)+'m ago';
  if(s<86400) return Math.floor(s/3600)+'h ago';
  return Math.floor(s/86400)+'d ago';
}
/* Every notification kind we currently emit routes to the same place — booking requests,
   waitlist and change-request activity are all triaged from the Bookings page. Kept as an
   explicit map (not a blanket default) so a future new kind is a deliberate decision, not
   an accident. */
/* V171: '#/home' and '#/customers' were never real routes (the router keys are 'dashboard'
   and 'clients'), so these two notification kinds silently dumped the owner on the Dashboard.
   Payment-due now opens Settings (billing lives in Modules & plan); feedback opens Customers.
   V468 removed the Visit feedback QUEUE from that page (owner photo 18), but Customers is still
   the right landing place: the ratings themselves survive on each customer's own 360 profile, so
   the trip is now "find the customer, open them, read it there" rather than a shared inbox. */
const NOTIF_ROUTE={booking_new:'#/bookings',booking_waitlisted:'#/bookings',change_request:'#/bookings',
  booking_expired:'#/bookings',waitlist_ready:'#/bookings',subscription_payment_due:'#/settings',
  feedback_new:'#/clients'};
async function loadNotifications(){
  const {data,error}=await sb.rpc('get_notifications',{p_business:S.biz.id,p_limit:30});
  if(error){notifError=error.message||'Could not load notifications';return}
  notifError=null;notifLoaded=true;notifState={unread:data.unread||0,items:data.items||[]};
}
function bellHtml(){
  const n=notifState.unread||0;
  return `<div class="bellwrap" id="bellwrap">
      <button type="button" class="bellbtn" id="bellBtn" title="Notifications" ${n?workspaceTemplateAttributeV97('aria-label','notificationsUnread',{count:n}):'aria-label="Notifications"'} aria-haspopup="true" aria-expanded="${bellOpen}">${CUI.icon('bell',{size:20})}${n>0?`<span class="dot" aria-hidden="true">${n>99?'99+':n}</span>`:''}</button>
      ${bellOpen?notifMenuHtml():''}
    </div>`;
}
function notifMenuHtml(){
  const items=notifState.items||[];
  const isOwner=S.myRole==='owner';
  return `<div class="notif-menu" id="notifmenu">
    <div class="row" style="padding:4px 8px 8px"><b class="small">Notifications</b><span class="spacer"></span>
      ${notifState.unread>0?`<button class="btn ghost sm" id="markAll" style="padding:4px 10px;font-size:11.5px">Mark all read</button>`:''}</div>
    ${notifError?`<div class="err" style="margin:0 6px 8px">${esc(notifError)}</div>`:''}
    ${!notifLoaded?`<div class="notif-empty">Loading…</div>`
      :items.length?items.map(it=>`<button type="button" class="notif-item ${it.read_at?'':'unread'}" data-nid="${esc(it.id)}" data-ref="${esc(it.kind)}" data-refid="${esc(it.ref_id||'')}">
          <div class="t">${esc(it.title||'')}</div>
          ${it.body?`<div class="b">${esc(it.body)}</div>`:''}
          <div class="ago">${timeAgo(it.created_at)}</div></button>`).join('')
      :`<div class="notif-empty">No notifications yet.</div>`}
    <hr style="border:none;border-top:1px solid var(--hair);margin:6px 0">
    ${isOwner?`<div class="switchrow"><span>Pop-up alerts</span>
        <button type="button" class="tglsw ${S.biz.notify_new_bookings?'on':''}" id="notifToggle" aria-label="Toggle pop-up alerts" aria-pressed="${!!S.biz.notify_new_bookings}"></button></div>`
      :`<div class="switchrow"><span>Pop-up alerts (this session)</span>
        <button type="button" class="tglsw ${muteAlerts?'':'on'}" id="notifToggle" aria-label="Toggle pop-up alerts for this session" aria-pressed="${!muteAlerts}"></button></div>`}
    </div>`;
}
function wireBell(page){
  wirePopoverDismissV452(page);
  $('bellBtn').onclick=(e)=>{e.stopPropagation();bellOpen=!bellOpen;if(bellOpen)closeAllPopoversV452('notifications');renderBell(page);};
  if(!bellOpen) return;
  const markAll=$('markAll');
  if(markAll) markAll.onclick=async(e)=>{
    e.stopPropagation();markAll.disabled=true;
    const {error}=await sb.rpc('mark_all_notifications_read',{p_business:S.biz.id});
    if(error){fail(error);markAll.disabled=false;return}
    notifState.items=(notifState.items||[]).map(it=>({...it,read_at:it.read_at||new Date().toISOString()}));
    notifState.unread=0;
    renderBell(page);
  };
  document.querySelectorAll('.notif-item').forEach(el=>el.onclick=async()=>{
    const id=el.dataset.nid,kind=el.dataset.ref;
    const {error}=await sb.rpc('mark_notification_read',{p_id:id});
    if(!error){
      const item=(notifState.items||[]).find(i=>i.id===id);
      if(item&&!item.read_at){item.read_at=new Date().toISOString();notifState.unread=Math.max(0,notifState.unread-1);}
    }
    bellOpen=false;
    /* V206 (owner: "clicking in the specific notification should brings me to the specific page
       to approve or reject or call customer"). notifications already carried ref_table/ref_id —
       the exact record — and the panel was throwing it away and landing you on the list to hunt
       for the row you had just been told about. */
    pendingNotificationFocusV206=el.dataset.refid||'';
    nav(NOTIF_ROUTE[kind]||'#/bookings');
  });
  const tgl=$('notifToggle');
  if(tgl) tgl.onclick=async(e)=>{
    e.stopPropagation();
    if(S.myRole==='owner'){
      const to=!S.biz.notify_new_bookings;
      tgl.style.pointerEvents='none';
      const {error}=await sb.rpc('set_booking_settings',{p_business:S.biz.id,
        p_hold_minutes:S.biz.booking_hold_minutes,p_overflow:S.biz.booking_overflow,
        p_notify:to,p_auto_confirm:S.biz.booking_auto_confirm});
      if(error){fail(error);tgl.style.pointerEvents='';return}
      S.biz.notify_new_bookings=to;
    }else{
      muteAlerts=!muteAlerts;
    }
    renderBell(page);
  };
  /* V452: click-away and Escape come from the shared controller. */
}
function renderBell(page){
  const wrap=$('bellwrap');
  if(!wrap) return;
  wrap.outerHTML=bellHtml();
  wireBell(page);
}
/* V461 "Peekaa" — the bell peeks and wiggles the instant a fresh notification lands, so an
   owner mid-service catches it from across the counter rather than noticing the badge cold
   later. Applied to a live DOM node (never baked into bellHtml()), so it only ever plays on a
   genuine realtime arrival — a route change or any other renderBell() call stays silent. */
function wiggleBell(){
  const btn=$('bellBtn');
  if(!btn) return;
  btn.classList.remove('peekaa-wiggle');
  void btn.offsetWidth; // restart the animation even if one is already mid-flight
  btn.classList.add('peekaa-wiggle');
  btn.addEventListener('animationend',()=>btn.classList.remove('peekaa-wiggle'),{once:true});
}
/* Re-runs the currently-open page's own render fn (no hash change) so new booking activity
   shows up without the owner having to manually refresh — the #1 complaint this feature set
   is meant to fix. Only wired for the pages where booking/waitlist activity is visible. */
/* V370. One customer booking produces TWO realtime events on this channel — the booking_requests
   INSERT and the notifications INSERT the DB trigger writes alongside it — and each handler called
   autoRefreshIfRelevant(), so a single booking re-rendered the whole open page twice within
   milliseconds (Bookings ≈ 6 reads each time) and re-counted the pending badge twice on top.
   Both are now trailing-debounced: every event still triggers a refresh, and a burst of events
   still triggers exactly one. The delay is short enough to stay imperceptible and long enough to
   coalesce the trigger-written pair. Nothing about WHAT gets refreshed changes — the V171 page
   allowlist and the V288 mid-typing guard below are untouched and still evaluated at the moment
   the refresh actually runs, not when it was scheduled. */
const REALTIME_REFRESH_DEBOUNCE_MS_V370=350;
let autoRefreshTimerV370=0,pendingBookingCountTimerV370=0;
function autoRefreshIfRelevant(){
  if(autoRefreshTimerV370)clearTimeout(autoRefreshTimerV370);
  autoRefreshTimerV370=setTimeout(()=>{autoRefreshTimerV370=0;autoRefreshIfRelevantNowV370()},
    REALTIME_REFRESH_DEBOUNCE_MS_V370);
}
function autoRefreshIfRelevantNowV370(){
  const key=(currentPage&&currentPage[0])||'';
  /* V171: the old 'customers' entry was dead — the router's key for that screen is 'clients',
     so it never matched. It is deliberately NOT fixed to 'clients': these events are booking/
     appointment inserts, and re-rendering the Customers page on them would wipe an open
     Add/Edit-customer form mid-typing. Customers refreshes on navigation instead. */
  const P={bookings:bookingsPage,appointments:appointmentsPage,waitlist:waitlistPage};
  if(!P[key])return;
  /* V288 (audit A2, HIGH 3). Re-rendering the page under a cursor destroys whatever is being
     typed — the same reason V171 refused to wire this to the Customers page. A booking insert
     is never urgent enough to eat a half-written booking rule, so when the focus is in an
     editable control on the open page, the refresh is skipped; the next navigation, tab change
     or manual action renders the new row. */
  const focused=globalThis.document?.activeElement;
  const editing=!!focused&&(focused.isContentEditable
    ||['INPUT','SELECT','TEXTAREA'].includes(focused.tagName));
  if(editing&&M()?.contains(focused))return;
  P[key](currentPage[1]);
}
function ensureRealtimeChannel(){
  if(rtChannel&&rtChannelBizId===S.biz.id) return; // already live for this business — reuse it
  if(rtChannel){ try{sb.removeChannel(rtChannel);}catch(e){} rtChannel=null; }
  rtChannel=sb.channel('rt-'+S.biz.id)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'business_id=eq.'+S.biz.id},payload=>{
      notifState.unread=(notifState.unread||0)+1;
      notifState.items=[payload.new,...(notifState.items||[])].slice(0,30);
      renderBell(currentPage);
      wiggleBell();
      autoRefreshIfRelevant();
      if(S.biz.notify_new_bookings&&!muteAlerts) toast('🔔 '+(payload.new?.title||'New notification'));
    })
    /* V329 (owner: a booking made with a specific team member selected should pop up in the
       business app asking to confirm or check availability, and a persistent reminder should
       stay visible while anything is unconfirmed). The INSERT handler already refreshed the
       open page; it now also refreshes the persistent badge (independent of which page is
       open) and, when pop-up alerts are on for this business and this session isn't muted,
       opens the request as a real dialog with the requested team member named — not just a
       toast, which disappears before an owner mid-service can read it. */
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'booking_requests',filter:'business_id=eq.'+S.biz.id},payload=>{
      autoRefreshIfRelevant();
      refreshPendingBookingRequestCountV329();
      if(S.biz.notify_new_bookings&&!muteAlerts&&STAFF_BOOKING_DECISION_STATUSES.has(payload.new?.status)&&canWriteModule('bookings')){
        openBookingRequestPopupV329ById(payload.new.id);
      }
    })
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'booking_requests',filter:'business_id=eq.'+S.biz.id},()=>{
      autoRefreshIfRelevant();refreshPendingBookingRequestCountV329();
    })
    .on('postgres_changes',{event:'DELETE',schema:'public',table:'booking_requests',filter:'business_id=eq.'+S.biz.id},()=>{
      autoRefreshIfRelevant();refreshPendingBookingRequestCountV329();
    })
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'appointments',filter:'business_id=eq.'+S.biz.id},()=>autoRefreshIfRelevant())
    .subscribe();
  rtChannelBizId=S.biz.id;
}
function killChannels(){
  if(rtChannel){ try{sb.removeChannel(rtChannel);}catch(e){} }
  rtChannel=null;rtChannelBizId=null;
  /* V370: a debounced refresh scheduled by the last event this channel delivered must not fire
     into a signed-out session and re-query a workspace this browser no longer has. */
  if(autoRefreshTimerV370){clearTimeout(autoRefreshTimerV370);autoRefreshTimerV370=0}
  if(pendingBookingCountTimerV370){clearTimeout(pendingBookingCountTimerV370);pendingBookingCountTimerV370=0}
}

/* ---------- V329: booking-request pop-up, persistent reminder badge ----------
   Owner (2026-08-15): a booking made with a specific team member selected should pop up in
   the business app asking to confirm or check availability; a persistent reminder should stay
   visible while anything is unconfirmed, at top right. Confirm/decline both go through the
   same existing single decision path (staff_decide_booking_request_v73) the Bookings page
   already used — this never becomes a second RPC, only a second place to reach it from, so
   confirm/decline logic cannot drift between the two surfaces. */
let pendingBookingRequestCountV329=0;
/* V375 (owner, photo 19: the "1" circled with an arrow to the Appointments rail item, "show
   here"). The rail row carries the SAME pendingBookingRequestCountV329 the topbar button reads,
   so the two can never disagree, and it follows the waitlist badge's slot pattern exactly. */
function appointmentsNavBadgeHtml(){
  const n=Number(pendingBookingRequestCountV329)||0;
  return n>0?`<span class="nav-badge" data-appointments-badge>${n}</span>`:'';
}
function bookingRequestsBadgeWrapHtml(){
  const n=pendingBookingRequestCountV329;
  /* No separate aria-label: the visible text ("N awaiting confirmation") already is the
     button's accessible name, so there is no second, unreviewed dynamic string to translate. */
  return `<span id="bookingRequestsBadgeWrapV329">${n>0?`<button type="button" class="btn ghost sm booking-requests-badge-v329" id="bookingRequestsBadgeV329">${CUI.icon('bookings',{size:16})} ${n} awaiting confirmation</button>`:''}</span>`;
}
function wireBookingRequestsBadgeV329(){
  const button=$('bookingRequestsBadgeV329');
  if(button)button.onclick=()=>nav('#/bookings');
}
function refreshPendingBookingRequestCountV329(){
  /* V370: same coalescing as autoRefreshIfRelevant, and for the same reason — the three
     booking_requests handlers can fire together. Returns the scheduling promise so existing
     callers that `await` it (renderShell does not) still resolve. */
  if(pendingBookingCountTimerV370)clearTimeout(pendingBookingCountTimerV370);
  return new Promise(resolve=>{
    pendingBookingCountTimerV370=setTimeout(()=>{
      pendingBookingCountTimerV370=0;
      Promise.resolve(refreshPendingBookingRequestCountNowV370()).then(resolve,resolve);
    },REALTIME_REFRESH_DEBOUNCE_MS_V370);
  });
}
async function refreshPendingBookingRequestCountNowV370(){
  if(!S.biz?.id||!canReadModule('bookings'))return;
  const {count,error}=await sb.from('booking_requests').select('id',{count:'exact',head:true})
    .eq('business_id',S.biz.id).in('status',[...STAFF_BOOKING_DECISION_STATUSES]);
  if(error)return; // a stale/missing badge is not worth surfacing an error for
  pendingBookingRequestCountV329=count||0;
  const wrap=$('bookingRequestsBadgeWrapV329');
  if(wrap){wrap.outerHTML=bookingRequestsBadgeWrapHtml();wireBookingRequestsBadgeV329();}
  document.querySelectorAll('[data-appointments-badge-slot]').forEach(slot=>{
    slot.innerHTML=appointmentsNavBadgeHtml();
  });
}
/* The single decision path, callable from any page — the popup can fire while the owner is on
   Dashboard, Customers, anywhere. window.decideBookingRequestV73 (bookingsPage) is bound to
   that page's own isCurrent() guard and silently no-ops off-page; this one is page-independent. */
/* contactDetails (optional): {customerName,phone,serviceName,staffName,startsAt}, already
   resolved by the caller — this function is page-independent (see the comment above) and cannot
   assume any page's local staff-name lookup is in scope, so it never resolves this itself. Used
   purely to offer the owner's WhatsApp template after a successful confirm. */
async function decideBookingRequestGlobalV329(id,decision,contactDetails){
  const authorized=decision==='confirm'?canWriteModule('bookings'):decision==='decline'?canWriteModule('bookings'):false;
  if(!authorized){toast('Booking write access is required');return}
  const {data,error}=await sb.rpc('staff_decide_booking_request_v73',{p_business:S.biz.id,p_request:id,p_decision:decision,p_branch:null});
  if(error){const failText=`${decision==='confirm'?'Confirm':'Decline'} failed. ${error.message||'Try again.'}`;toast(failText);return}
  toast(bookingDecisionNotice(data,decision).text);
  autoRefreshIfRelevant();
  refreshPendingBookingRequestCountV329();
  if(decision==='confirm'&&contactDetails)offerBookingConfirmationContactV330(contactDetails);
}
async function openBookingRequestPopupV329ById(id){
  if($('bookingRequestPopupV329'))return; // one at a time — a second INSERT while one is open just refreshes the badge
  const {data,error}=await sb.from('booking_requests').select('*, services(name), staff(full_name), branches(name,address)')
    .eq('id',id).eq('business_id',S.biz.id).maybeSingle();
  if(error||!data||!STAFF_BOOKING_DECISION_STATUSES.has(data.status))return;
  openBookingRequestPopupV329(data);
}
/* ============ V363 — THE STAMP-CARD EXCLUSIVITY WARNING, AT THE DOOR =========================
   Owner (2026-08-16, photo 1): a popup on clicking into Stamp card whenever Point system and/or
   Tier membership is active, saying setting up the stamp card will switch them off, yes/no.
   Deliberately a plain confirm and nothing more: choosing "Yes, set up Stamp card" only OPENS the
   page. Nothing is written here — the actual switch (and its own confirmation, which states the
   same consequence at the moment it becomes true) still lives on that page's Turn-on control. */
function openStampsExclusivityPopupV363(losingNames,onProceed,openingName='the Stamp card'){
  if($('stampsExclusivityPopupV363'))return;
  const names=(losingNames||[]).filter(Boolean);
  const list=names.length>1?`${names.slice(0,-1).join(', ')} and ${names[names.length-1]}`:(names[0]||'your other programmes');
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="stampsExclusivityPopupV363" role="dialog" aria-modal="true" aria-labelledby="stampsExclusivityTitleV363" tabindex="-1"><div class="modal-card" style="max-width:460px">
    <h2 id="stampsExclusivityTitleV363">Set up ${esc(openingName)}?</h2>
    <p class="muted" style="margin-top:8px">${esc(openingName.charAt(0).toUpperCase()+openingName.slice(1))} runs on its own. Turning it on will switch ${esc(list)} off for your customers.</p>
    <p class="muted small" style="margin-top:8px">Nothing changes yet — everything ${names.length>1?'they have':'it has'} collected stays saved, and you can come back at any time.</p>
    <div class="row" style="margin-top:16px;gap:8px;flex-wrap:wrap">
      <button class="btn" id="stampsExclusivityYesV363" type="button">Yes, continue</button>
      <button class="btn ghost" id="stampsExclusivityNoV363" type="button">No, go back</button>
    </div>
  </div></div>`);
  let deactivate;
  const close=options=>{if(deactivate)deactivate(options);else $('stampsExclusivityPopupV363')?.remove();};
  deactivate=CUI.activateDialog($('stampsExclusivityPopupV363'),{onClose:close,initialFocus:'#stampsExclusivityNoV363'});
  $('stampsExclusivityNoV363').onclick=()=>close();
  /* V375 (owner, photo 8: "when i press this, page did not proceed to stamp card"). CUI's dialog
     teardown unwinds the history entry it pushed by calling history.back(), which is ASYNCHRONOUS.
     The plain close() therefore queued a pop, openStampsV363 then set the hash synchronously, and
     the queued pop landed afterwards and took the owner straight back to the programmes list —
     the navigation happened and was immediately undone. Proceeding hands the entry over instead
     (handOffHistory), so nothing pops and Back still returns here from the stamp card page.
     "No, go back" keeps unwinding, because there the entry genuinely is ours to remove. */
  $('stampsExclusivityYesV363').onclick=()=>{close({handOffHistory:true});if(typeof onProceed==='function')onProceed();};
}
function openStampSwitchConversionPopupV384(){
  return new Promise(resolve=>{
    if($('stampSwitchConversionPopupV384'))return resolve({cancelled:true});
    const defaultRate=100;
    document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="stampSwitchConversionPopupV384" role="dialog" aria-modal="true" aria-labelledby="stampSwitchConversionTitleV384" tabindex="-1"><div class="modal-card" style="max-width:500px">
      <h2 id="stampSwitchConversionTitleV384">Switch customers to Stamp card?</h2>
      <p class="muted" style="margin-top:8px">The Stamp card is a separate live programme. Customers will see stamps only; points and tier membership will switch off.</p>
      <p class="muted small" style="margin-top:8px">Existing points stay saved. Convert them only if you want the old point balance to become stamps on this card.</p>
      <label class="field" style="margin-top:14px"><span>Conversion suggestion</span>
        <div class="row" style="gap:8px;align-items:center"><input id="stampSwitchRateV384" inputmode="numeric" type="number" min="1" step="1" value="${defaultRate}" style="max-width:130px"><span class="muted small">points = 1 stamp</span></div>
      </label>
      <p class="muted small" id="stampSwitchPreviewV384" role="status" aria-live="polite" style="min-height:20px;margin-top:8px">Checking existing points...</p>
      <div class="row" style="margin-top:16px;gap:8px;flex-wrap:wrap">
        <button class="btn" id="stampSwitchConvertV384" type="button">Convert and switch</button>
        <button class="btn ghost" id="stampSwitchFreshV384" type="button">Start fresh</button>
        <button class="btn ghost" id="stampSwitchCancelV384" type="button">Cancel</button>
      </div>
    </div></div>`);
    const modal=$('stampSwitchConversionPopupV384');
    const rateInput=$('stampSwitchRateV384');
    const preview=$('stampSwitchPreviewV384');
    let deactivate=null,closed=false,previewTimer=null;
    const rate=()=>Math.max(1,Math.round(Number(rateInput?.value)||defaultRate));
    const close=value=>{
      if(closed)return;closed=true;
      if(previewTimer)clearTimeout(previewTimer);
      if(deactivate)deactivate({restoreFocus:false});else modal.remove();
      resolve(value);
    };
    const updatePreview=async()=>{
      if(!modal.isConnected)return;
      preview.textContent='Checking existing points...';
      try{
        const {data,error}=await sb.rpc('business_preview_stamp_conversion_v384',{
          p_business:S.biz.id,p_points_per_stamp:rate()
        });
        if(!modal.isConnected)return;
        if(error)throw error;
        const stamps=Math.max(0,Number(data?.stamps_to_issue)||0);
        const customers=Math.max(0,Number(data?.customers)||0);
        const points=Math.max(0,Number(data?.points_convertible)||0);
        const leftover=Math.max(0,Number(data?.leftover_points)||0);
        preview.textContent=stamps>0
          ?`${points.toLocaleString('en-SG')} points can become ${stamps.toLocaleString('en-SG')} stamps for ${customers} customer${customers===1?'':'s'}. ${leftover.toLocaleString('en-SG')} points stay saved.`
          :'No existing points are ready to convert at this rate.';
      }catch(error){
        if(modal.isConnected)preview.textContent='Preview unavailable. You can still start fresh, or try a different rate.';
      }
    };
    rateInput.oninput=()=>{
      if(previewTimer)clearTimeout(previewTimer);
      previewTimer=setTimeout(updatePreview,280);
    };
    $('stampSwitchCancelV384').onclick=()=>close({cancelled:true});
    $('stampSwitchFreshV384').onclick=()=>close({convert:false,rate:rate()});
    $('stampSwitchConvertV384').onclick=()=>close({convert:true,rate:rate()});
    deactivate=CUI.activateDialog(modal,{onClose:()=>close({cancelled:true}),initialFocus:'#stampSwitchConvertV384'});
    updatePreview();
  });
}
async function writeProgrammeSwitchesWithStampConversionV384(set,{paused=false,key=null}={}){
  if(set?.stamps===true&&paused!==true){
    const decision=await openStampSwitchConversionPopupV384();
    if(decision?.cancelled)return {ok:false,cancelled:true,skipped:true,error:null};
    const switchKey=key||crypto.randomUUID();
    const {data,error}=await sb.rpc('business_switch_to_stamps_v384',{
      p_business:S.biz.id,
      p_convert_existing_points:decision.convert===true,
      p_points_per_stamp:decision.convert===true?decision.rate:null,
      p_idempotency_key:switchKey
    });
    if(error)return {ok:false,skipped:false,error};
    rememberProgrammeSpineV314(data?.programmes);
    return {ok:true,skipped:false,error:null,data};
  }
  /* nestly_v435 (simulation A8): the REVERSE direction gets its review too. Switching to points
     while stamps is running used to say nothing about the customers' existing stamp value, and
     a round trip left tiers silently off (the Diamond-vanishes surprise). Both facts are said
     out loud now — before the write, and after it. Spine state is read BEFORE the write, because
     the write's reply overwrites the cache. */
  const stampsRunningBeforeV435=(S.programmes||[]).some(row=>row?.kind==='stamps'&&row.active);
  const tiersOnBeforeV435=(S.programmes||[]).some(row=>row?.kind==='tiers'&&row.active);
  if(set?.points===true&&paused!==true&&stampsRunningBeforeV435){
    if(!await confirmActionV386('Switch customers to Points? Stamp collecting stops, but customers keep their stamps and any gifts they already earned — those can still be claimed at the counter. If you switch back later, their card continues.'))
      return {ok:false,cancelled:true,skipped:true,error:null};
  }
  const resultV435=await writeProgrammeSwitchesV314(S.biz.id,set,{paused,key});
  if(resultV435.ok&&!resultV435.skipped&&set?.points===true&&paused!==true
     &&tiersOnBeforeV435&&set?.tiers!==true){
    toast('Points are running. Tiers switched OFF with this change — turn them back on from the Tiers page if you still want them.');
  }
  return resultV435;
}
function openBookingRequestPopupV329(row){
  if($('bookingRequestPopupV329'))return;
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="bookingRequestPopupV329" role="dialog" aria-modal="true" aria-labelledby="bookingRequestPopupTitleV329" tabindex="-1"><div class="modal-card" style="max-width:480px">
    <div class="row"><div><h2 id="bookingRequestPopupTitleV329">New booking request</h2><p class="muted small" style="margin-top:4px">${esc(row.name||'A customer')} wants to book.</p></div><span class="spacer"></span><button class="btn ghost sm" id="bookingRequestPopupCloseV329" type="button">Close</button></div>
    <div class="imp-note" style="margin-top:12px">
      <div><b>Service</b> ${esc(row.services?.name||'General visit')}</div>
      <div><b>Preferred time</b> ${esc(sgt(row.preferred_at)||'—')}</div>
      <div><b>Team member</b> ${esc(row.staff?.full_name||'Anyone available')}</div>
      ${row.branches?.name?`<div><b>Branch</b> ${esc(row.branches.name)}</div>`:''}
      ${row.party_size?`<div><b>Party</b> ${row.party_size}</div>`:''}
      ${row.notes?`<div><b>Notes</b> ${esc(row.notes)}</div>`:''}
    </div>
    <div class="row" style="margin-top:16px;gap:8px;flex-wrap:wrap">
      <button class="btn" id="bookingRequestPopupConfirmV329" type="button">Confirm booking</button>
      <button class="btn ghost" id="bookingRequestPopupAvailV329" type="button">Check availability</button>
      <button class="btn ghost danger" id="bookingRequestPopupDeclineV329" type="button">Decline</button>
    </div>
  </div></div>`);
  let deactivate;
  /* V468: close() now FORWARDS its options. It swallowed them, so dialogHandOffNavV468's
     {handOffHistory:true} would have been dropped and the hand-off below silently reverted to the
     broken back()-races-nav() shape it exists to prevent. */
  const close=options=>{if(deactivate)deactivate(options);else $('bookingRequestPopupV329')?.remove();};
  deactivate=CUI.activateDialog($('bookingRequestPopupV329'),{onClose:close,initialFocus:'#bookingRequestPopupConfirmV329'});
  $('bookingRequestPopupCloseV329').onclick=close;
  $('bookingRequestPopupConfirmV329').onclick=()=>{close();decideBookingRequestGlobalV329(row.id,'confirm',{
    customerName:row.name,phone:row.phone,serviceName:row.services?.name,staffName:row.staff?.full_name,
    startsAt:row.preferred_at,location:row.branches?.address
  });};
  $('bookingRequestPopupDeclineV329').onclick=()=>{close();decideBookingRequestGlobalV329(row.id,'decline');};
  /* V468 (owner ringed "Check availability": "bring me to the appointment module (calendar
     view)"). It already built the right destination — the request's date, its team member and a
     highlight — and then threw it away: close() unwinds the dialog's history entry with an
     ASYNCHRONOUS history.back(), so the queued pop landed after nav() had set the hash and put the
     page straight back. Nothing moved. The same defect, and the same established fix, as the three
     dashboard tiles earlier in this batch. */
  $('bookingRequestPopupAvailV329').onclick=()=>{
    const params=new URLSearchParams();
    const date=String(row.preferred_at||'').slice(0,10);
    if(date)params.set('date',date);
    if(row.staff_id)params.set('staff',row.staff_id);
    params.set('highlight',row.id);
    dialogHandOffNavV468(close,'#/appointments?'+params.toString());
  };
}
async function initNotifications(){
  if(!S.biz) return;
  await loadNotifications();
  renderBell(currentPage);
  ensureRealtimeChannel();
}

