const workspaceTemplateTextV97=(key,values={},locale=workspaceLocale)=>{
  const copy=WORKSPACE_TEMPLATE_COPY_V97[key],template=copy?.[locale]??copy?.en??'';
  return template.replace(/\{([a-z][a-z0-9_]*)\}/gi,(_,name)=>String(values[name]??''));
};
const WORKSPACE_TEMPLATE_ATTRIBUTES_V97=Object.freeze(['aria-label','title','placeholder']);
const workspaceTemplateAttributeV97=(attribute,key,values={})=>{
  if(!WORKSPACE_TEMPLATE_ATTRIBUTES_V97.includes(attribute)
     ||!WORKSPACE_INTERPOLATED_ATTRIBUTE_INVENTORY_V97.includes(key))return '';
  const encoded=encodeURIComponent(JSON.stringify(values));
  return `data-workspace-${attribute}-template="${esc(key)}" data-workspace-${attribute}-values="${esc(encoded)}" ${attribute}="${esc(workspaceTemplateTextV97(key,values))}"`;
};
const workspaceTemplateInnerHtmlV97=(key,values={},locale=workspaceLocale)=>{
  const copy=WORKSPACE_TEMPLATE_COPY_V97[key],template=copy?.[locale]??copy?.en??'';
  let cursor=0,html='';
  for(const match of template.matchAll(/\{([a-z][a-z0-9_]*)\}/gi)){
    html+=esc(template.slice(cursor,match.index));
    const name=match[1];
    html+=`<span data-workspace-value="${esc(name)}" data-merchant-content>${esc(values[name]??'')}</span>`;
    cursor=match.index+match[0].length;
  }
  return html+esc(template.slice(cursor));
};
const workspaceTemplateHtmlV97=(key,values={})=>`<span data-workspace-template="${esc(key)}">${workspaceTemplateInnerHtmlV97(key,values)}</span>`;
function localizeWorkspaceTemplateV97(element){
  const key=element.dataset.workspaceTemplate;
  let values=workspaceTemplateValuesV97.get(element);
  if(!values){
    values=Object.fromEntries([...element.querySelectorAll('[data-workspace-value]')]
      .map(value=>[value.dataset.workspaceValue,value.textContent]));
    workspaceTemplateValuesV97.set(element,values);
  }
  const localizedHtml=workspaceTemplateInnerHtmlV97(key,values,workspaceLocale);
  if(element.innerHTML!==localizedHtml)element.innerHTML=localizedHtml;
}
function localizeWorkspaceTemplateAttributesV97(element){
  for(const attribute of WORKSPACE_TEMPLATE_ATTRIBUTES_V97){
    const key=element.getAttribute(`data-workspace-${attribute}-template`);
    if(!key)continue;
    let values={};
    try{values=JSON.parse(decodeURIComponent(element.getAttribute(`data-workspace-${attribute}-values`)||''))}catch{}
    element.setAttribute(attribute,workspaceTemplateTextV97(key,values));
  }
}
function isWorkspaceDynamicNodeV97(element){
  if(!element)return false;
  if(element.closest([
    '.wallet-shell','[data-merchant-content]','[data-workspace-template]','.notif-item','.customer-link',
    '.appointment-event','.calendar-event','.customer-programme-card','.customer-reward-card',
    '.customer-offer-card','.customer-perk-card',
    '[data-client-id]','[data-customer-id]','[data-appointment-id]','[data-sale-id]',
    '[data-product-id]','[data-service-id]','[data-staff-id]'
  ].join(',')))return true;
  if(element instanceof HTMLOptionElement){
    return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(element.value);
  }
  return false;
}
function isWorkspaceTableDataNodeV97(element){
  const cell=element?.closest?.('td');
  if(!cell)return false;
  return !element.closest('button,.btn,.pill,[data-workspace-i18n]');
}
function localizeWorkspaceSubtreeV97(container=root){
  if(!container?.querySelectorAll||!root.querySelector('.shell'))return;
  globalThis.document?.documentElement?.setAttribute('lang',workspaceLocale);
  const scopes=[];
  if(container.matches?.('.side,.appbar,.main,[role="dialog"],[data-workspace-i18n]')
     ||container.closest?.('.side,.appbar,.main,[role="dialog"],[data-workspace-i18n]'))scopes.push(container);
  scopes.push(...container.querySelectorAll('.side,.appbar,.main,[role="dialog"],[data-workspace-i18n]'));
  const templates=[...new Set(scopes.flatMap(scope=>[
    ...(scope.matches?.('[data-workspace-template]')?[scope]:[]),
    ...scope.querySelectorAll('[data-workspace-template]')
  ]))];
  for(const template of templates)localizeWorkspaceTemplateV97(template);
  const elements=[...new Set(scopes.flatMap(scope=>[scope,...scope.querySelectorAll('*')]))];
  for(const element of elements){
    if(!(element instanceof Element))continue;
    localizeWorkspaceTemplateAttributesV97(element);
    if(isWorkspaceDynamicNodeV97(element))continue;
    for(const attribute of ['placeholder','title','aria-label','data-label']){
      if(!element.hasAttribute(attribute))continue;
      if(element.hasAttribute(`data-workspace-${attribute}-template`))continue;
      let sources=workspaceAttributeSourcesV97.get(element);
      if(!sources){sources={};workspaceAttributeSourcesV97.set(element,sources)}
      if(!(attribute in sources))sources[attribute]=element.getAttribute(attribute);
      element.setAttribute(attribute,workspaceTranslationV97(sources[attribute]));
    }
    for(const node of element.childNodes){
      if(node.nodeType!==Node.TEXT_NODE||!node.nodeValue.trim()
         ||isWorkspaceDynamicNodeV97(node.parentElement)||isWorkspaceTableDataNodeV97(node.parentElement))continue;
      if(!workspaceTextSourcesV97.has(node))workspaceTextSourcesV97.set(node,node.nodeValue);
      const source=workspaceTextSourcesV97.get(node),trimmed=source.trim();
      node.nodeValue=source.replace(trimmed,workspaceTranslationV97(trimmed));
    }
  }
}
function observeWorkspaceLocalizationV97(){
  workspaceLocalizationObserver?.disconnect();
  const shell=root.querySelector('.shell');if(!shell)return;
  workspaceLocalizationObserver=new MutationObserver(records=>{
    for(const record of records)for(const node of record.addedNodes){
      const element=node.nodeType===Node.ELEMENT_NODE?node:node.parentElement;
      if(!element)continue;
      /* Template localization replaces its own text/value children. Ignore those
         observer records or they recursively rewrite the same innerHTML forever. */
      if(node.nodeType!==Node.ELEMENT_NODE
         &&element.closest?.('[data-workspace-template],[data-merchant-content]'))continue;
      if(node.nodeType===Node.ELEMENT_NODE
         &&element.closest?.('[data-workspace-template],[data-merchant-content]')
         &&!element.matches?.('[data-workspace-template]'))continue;
      localizeWorkspaceSubtreeV97(element);
    }
  });
  workspaceLocalizationObserver.observe(document.body,{childList:true,subtree:true});
}
async function loadWorkspaceLocaleV97(isCurrent=()=>true){
  const userId=S.user?.id||'';
  if(!userId||workspaceLocaleLoadedFor===userId)return;
  const {data,error}=await sb.rpc('get_workspace_locale_preference_v97');
  if(!isCurrent())return;
  workspaceLocaleLoadedFor=userId;
  if(!error&&data){workspaceLocale=normalizeWorkspaceLocaleV97(data.locale);workspaceLocaleVersion=Number(data.version||0)}
  /* v185: fetch the translation tables before the first workspace render, so a zh-CN or ms
     workspace never paints an English frame first. English users never download them. */
  if(workspaceLocale!=='en')await loadWorkspaceI18nV185();
}
async function setWorkspaceLocaleV97(locale){
  const next=normalizeWorkspaceLocaleV97(locale),previous=workspaceLocale;
  if(next===previous)return true;
  /* v185: switching INTO a translated language must wait for the tables, otherwise the first
     re-render after the switch would repaint the same English copy the user just moved away from. */
  if(next!=='en')await loadWorkspaceI18nV185();
  workspaceLocale=next;localizeWorkspaceSubtreeV97();
  const {data,error}=await sb.rpc('set_workspace_locale_preference_v97',{p_locale:next,p_expected_version:workspaceLocaleVersion});
  if(error){workspaceLocale=previous;localizeWorkspaceSubtreeV97();toast('Language preference could not be saved.');return false}
  workspaceLocale=normalizeWorkspaceLocaleV97(data?.locale||next);
  workspaceLocaleVersion=Number(data?.version??workspaceLocaleVersion+1);
  localizeWorkspaceSubtreeV97();return true;
}
function wireWorkspaceLanguageV97(){
  const wirePicker=picker=>{if(!picker)return;picker.onchange=async()=>{
    picker.disabled=true;await setWorkspaceLocaleV97(picker.value);
    if(picker.isConnected){picker.value=workspaceLocale;picker.disabled=false}
  }};
  wirePicker($('workspaceLanguageV97'));
  wirePicker($('workspaceLanguageMobileV151'));
}

function renderShell(page){
  disposeCurrentRoute();
  const priorSide=root.querySelector('.side');
  const priorSideScroll=priorSide?.scrollTop||0;
  const preserveWorkspaceScroll=Boolean(root.querySelector('.shell'));
  const priorWindowX=window.scrollX,priorWindowY=window.scrollY;
  const renderEpoch=++shellRenderEpoch;
  if(customerUiObserver)customerUiObserver.disconnect();
  currentPage=page; // used by the realtime handlers below to know what to auto-refresh
  root.innerHTML=`<div class="shell">
    <aside class="side" aria-label="Workspace navigation">
      <a href="#/dashboard" class="logo" style="display:block">${brandWordmark()}</a>
      <nav class="nav" id="navwrap" aria-label="Main navigation">${navHtml(page)}</nav>
      <div class="foot" aria-label="Application version">${buildIdentityHtml()}</div>
    </aside>
    <div class="col">
      <header class="appbar">
        ${mobileWorkspaceTitleHtml(page)}
        ${globalActionsHtml()}
        ${mobileSearchShellHtml()}
        <div class="topbar-branch-scope-v210" id="profileBranchScopeV158" aria-live="polite"></div>

        <!-- V443 (owner sketch): "Switch workspace" moved out of the header into the profile
             menu's top workspace section (see profileHtml), reachable at every width — the
             narrow-header media query used to hide this control entirely rather than relocate
             it, so this also closes that gap. -->
        ${canReadModule('bookings')?bookingRequestsBadgeWrapHtml():''}
        ${bellHtml()}
        ${profileHtml()}
      </header>
      <main class="main" id="main" tabindex="-1"></main>
    </div>
    ${staffMobileActionsHtml(page)}
  </div>`;
  const main=$('main');
  const side=root.querySelector('.side');
  if(side)side.scrollTop=priorSideScroll;
  if(preserveWorkspaceScroll)requestAnimationFrame(()=>{
    if(side?.isConnected)side.scrollTop=priorSideScroll;
    const maxY=Math.max(0,document.documentElement.scrollHeight-window.innerHeight);
    window.scrollTo(priorWindowX,Math.min(priorWindowY,maxY));
  });
  /* V287 added routes to a curated enhancement set one bug at a time — the Sales ledger was
     "the only such table left outside CUI.mountMain" until the next one wasn't. v294 ends the
     allowlist: every workspace route mounts the enhancer. enhanceTables is idempotent (class,
     caption, thead, data-label and wrapper are all added only when absent), no workspace table
     hand-sets data-responsive, and mounting drives nothing but markup enhancement — so the
     per-route membership question no longer exists, and neither does its failure mode. */
  const enhanceCustomerUi=true;
  customerUiObserver=CUI.mountMain(main);
  wireNav();
  wireGlobalActions();
  wireMobileSearchShell();
  wireStaffMobileActions();
  wireWorkspaceLanguageV97();
  wireBell(page);
  wireBookingRequestsBadgeV329();
  if(canReadModule('bookings'))refreshPendingBookingRequestCountV329();
  wireProfile(page);
  localizeWorkspaceSubtreeV97();
  observeWorkspaceLocalizationV97();
  if(page[0]==='dashboard')typeof recordProductInteractionV100==='function'&&recordProductInteractionV100('merchant.workspace_viewed',S.biz.id,{
    context:{entry_point:'workspace_home',locale:workspaceLocale,surface_version:'v100'}
  });
  /* v255: workspace_viewed only ever covered the home page, so 12 of the 15 modules were
     invisible. surface_viewed generalizes it — the module key travels in surface_key, which is
     a closed route name and not a raw URL. workspace_viewed stays for continuity of the series
     already recorded against it. */
  if(page[0])typeof recordProductInteractionV100==='function'&&recordProductInteractionV100('merchant.surface_viewed',S.biz.id,{
    context:{surface_key:String(page[0]),entry_point:'workspace_nav',
      locale:workspaceLocale,surface_version:'v255'}
  });
  /* Loyalty and retention share one presentation surface (growPage, below) while staying two
     completely separate engines underneath — same RPCs, same routes, same module keys. The
     route key each hash resolves to (page[0]) is still 'loyalty' or 'retention', unchanged;
     only which function that key maps to is new, so the module route-guard above this
     function needs no changes at all. */
  const P={dashboard,till:tillPage,clients:clientsPage,client:clientDetail,sales:salesPage,services:servicesPage,
    /* V288: every ROUTE entry into Programmes is marked as such, so a stale tile drill from an
       earlier visit cannot survive a fresh navigation. */
    grow:(hashParam,routedFocus)=>growPage('overview',hashParam,routedFocus,{fromRouteV288:true}),
    bookings:bookingsPage,loyalty:(hashParam,routedFocus)=>growPage('rewards',hashParam,routedFocus,{fromRouteV288:true}),retention:()=>{/* V364 (owner markup, photo 2: "Retention programs" struck through and renamed
      "Bring Back Rewards", the draft/publish banner struck through with "delete this"). Owner
      ruling when asked: fold this page into the v361 Bring-back module rather than maintain two
      bring-back surfaces. The route survives so every existing link, bookmark and history entry
      still lands somewhere true — it just lands on the module that actually runs. The winback
      EDITOR surface is untouched; only this top-level page redirects. */
      nav('#/grow/bringback');return Promise.resolve();},promotions:promotionsPage,studio:hashParam=>growPage('studio',hashParam,null,{fromRouteV288:true}),storedvalue:hashParam=>growPage('storedvalue',hashParam,null,{fromRouteV288:true}),referrals:referralsPage,
    memberships:membershipsPage,giftcards:giftcardsPage,appointments:appointmentsPage,
    waitlist:waitlistPage,inventory:inventoryPage,packages:packagesPage,reports:reportsPage,customerintel:customerIntelligencePage,support:supportInboxPageV531,
    bottles:bottlesPage,bottlesetup:bottleSetupPageV275,
    staffperf:staffPerfPage,staffmembers:staffMembersPage,dailyreport:dailyReportPage,pnl:pnlPage,expenses:expensesPage,
    setup:setupPage,settings:settingsPage,branches:branchesPage,platform:platformPage,
    'customer-interface':customerInterfacePageV243};
  /* V286: a hash with no page used to render the Dashboard while location.hash still read the
     route that was asked for — the one refusal in the router that answered silently. A staff
     member with a bookmark to a renamed module concluded the bookmark still worked. Every other
     refusal above says so and corrects the URL; so does this one. */
  const pageFn=page[0]?P[page[0]]:dashboard;
  if(!pageFn){
    toast('That page has moved.');
    return nav('#/dashboard');
  }
  const pageResult=pageFn(...page.slice(1));
  Promise.resolve(pageResult).catch(error=>{
    console.error(error);
    if(shellRenderEpoch!==renderEpoch||!main.isConnected)return;
    const title=MODULES[page[0]]?.[1]||(page[0]==='client'?'Customer':'Workspace');
    /* V172: route through the same owner-language mapper as fail() — this card previously
       printed raw browser TypeErrors ("undefined is not an object (evaluating ...)"). */
    main.innerHTML=CUI.errorState({title:`${title} unavailable`,message:ownerErrorText(error)||'Please try again.'});
    CUI.announce(ownerErrorText(error)||'Page unavailable',{assertive:true});
    const retry=$('routeRetry');if(retry)retry.onclick=()=>renderShell(page);
  }).finally(()=>{
    if(shellRenderEpoch!==renderEpoch||!main.isConnected)return;
    const focusX=window.scrollX,focusY=window.scrollY;
    CUI.focusRoute(main,{enhanceContent:enhanceCustomerUi});
    const target=main.querySelector('h1')||main;
    requestAnimationFrame(()=>{
      localizeWorkspaceSubtreeV97();
      target.focus({preventScroll:true});
      const maxY=Math.max(0,document.documentElement.scrollHeight-window.innerHeight);
      window.scrollTo(focusX,Math.min(focusY,maxY));
    });
  });
  initNotifications(); // fire-and-forget, like the page fn above — loads badge + (re)uses the realtime channel
  refreshWaitlistBadge(); // same waitlist queue source, hidden at zero
}
const M=()=> $('main');
function focusRoutedWorkspaceControl(routedFocus,fallback=null){
  if(!routedFocus)return false;
  let target='';
  try{target=decodeURIComponent(String(routedFocus||fallback||''))}catch{return false}
  if(!/^[A-Za-z][\w:-]*$/.test(target))return false;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    const element=$(target);
    if(!element)return;
    let disclosure=element.closest('details');
    while(disclosure){disclosure.open=true;disclosure=disclosure.parentElement?.closest('details')}
    element.focus?.({preventScroll:true});
    element.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
  }));
  return true;
}

/* ---------- v40 staff reversal workflow ----------
   All writes stay behind reverse_sale / reverse_loyalty_redemption. The read model is a
   bounded SECURITY DEFINER RPC because the immutable provenance tables are deliberately
   not browser-readable. Keys survive retries and page re-renders for this tab session. */
const reversalKeys=new Map(),reversalItems=new Map();
const reversalItemKey=(kind,id)=>`${kind}:${id}`;
async function loadReversalWorkflows(clientId=null,limit=100,mode='all'){
  const {data,error}=await sb.rpc('staff_get_reversal_workflows',{
    p_business:S.biz.id,p_client:clientId,p_limit:limit,p_mode:mode});
  if(error){
    if(error.code==='42501'||/permission|authorization|staff required/i.test(error.message||''))return null;
    throw error;
  }
  [...(data?.sales||[])].forEach(x=>reversalItems.set(reversalItemKey('sale',x.id),x));
  [...(data?.redemptions||[])].forEach(x=>reversalItems.set(reversalItemKey('redemption',x.id),x));
  return data||{sales:[],redemptions:[]};
}
function reversalResultHtml(kind,result){
  if(!result)return '';
  if(kind==='sale'&&result.no_money_refund)return `<div class="imp-note"><b>Session use undone.</b> No payment refund was created. ${Number(result.restored_sessions||1)} package session added back.</div>`;
  if(kind==='sale')return `<div class="imp-note"><b>Reversal completed.</b> ${money(Number(result.reversed_cents||0))} reversed · ${money(Number(result.refunded_payment_cents||0))} refunded${result.replayed?' · exact replay verified':''}.</div>`;
  return `<div class="imp-note"><b>Redemption reversed.</b> ${Number(result.restored_points||0)} points restored · ${money(Number(result.reversed_credit_cents||0))} credit compensated${result.replayed?' · exact replay verified':''}.</div>`;
}
function openReversalDialog(kind,item,onDone){
  if(!item?.can_reverse)return toast(item?.refusal_reason||'This item cannot be reversed safely');
  const keyId=reversalItemKey(kind,item.id);
  if(!reversalKeys.has(keyId))reversalKeys.set(keyId,crypto.randomUUID());
  const packageNote=kind==='sale'&&item.is_package_session
    ?'<div class="imp-note"><b>Package session use only.</b> This undoes one recorded package session use. No payment refund occurs.</div>':'';
  const loyaltyNote=kind==='redemption'
    ?`<div class="imp-note"><b>Exact compensation only.</b> ${esc(BRAND.productName)} checks the original points entry, every FEFO batch drain, the programme rules in effect at the time, and whether the ${money(Number(item.credit_cents||0))} reward credit may have been spent. If any proof is incomplete, it refuses the reversal.</div>`:'';
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="reversalModal" role="dialog" aria-modal="true" aria-labelledby="revTitle" tabindex="-1"><div class="modal-card" style="max-width:560px">
    <div class="row"><div><h2 id="revTitle">${kind==='sale'?'Reverse sale':'Reverse redemption'}</h2><p class="muted small">${kind==='sale'?`Sale ${esc(item.id)} · ${money(Number(item.amount_cents||0))}`:`${esc(item.reward_name||'Reward')} · ${Number(item.points_spent||0)} points`}</p></div><span class="spacer"></span><button class="btn ghost sm" id="revClose">Close</button></div>
    ${packageNote}${loyaltyNote}
    <label for="revReason">${kind==='sale'?'Correction note (optional)':'Reason (required, at least 10 characters)'}</label><textarea id="revReason" rows="3" data-workspace-i18n placeholder="${kind==='sale'?'Add context if it helps your team.':'What happened and who approved this correction?'}"></textarea>
    <label style="display:flex;gap:9px;align-items:flex-start;color:var(--ink2)"><input id="revConfirm" type="checkbox" style="width:auto;margin-top:2px">I checked the original record and understand this creates append-only compensating entries.</label>
    <div id="revOutcome"></div><div class="row" style="margin-top:16px"><button class="btn danger" id="revSubmit" disabled>Confirm reversal</button><button class="btn ghost sm" id="revCancel">Cancel</button></div>
  </div></div>`);
  let deactivateDialog;
  const close=()=>{if(deactivateDialog)deactivateDialog();else $('reversalModal')?.remove();if(onDone)onDone()};
  deactivateDialog=CUI.activateDialog($('reversalModal'),{onClose:close,initialFocus:'#revReason'});
  $('revClose').onclick=$('revCancel').onclick=close;
  $('revConfirm').onchange=()=>{$('revSubmit').disabled=!$('revConfirm').checked};
  async function invoke(isReplay=false){
    const reason=$('revReason').value.trim();
    if(kind!=='sale'&&reason.length<10)return toast('Write a reason of at least 10 characters');
    const btn=$('revSubmit');btn.disabled=true;btn.textContent=isReplay?'Verifying…':'Reversing…';
    const args=kind==='sale'
      ?{p_business:S.biz.id,p_sale:item.id,p_note:reason||null,p_idempotency_key:reversalKeys.get(keyId)}
      :{p_business:S.biz.id,p_redemption:item.id,p_reason:reason,p_idempotency_key:reversalKeys.get(keyId)};
    /* V291: the last money confirmation on this dialog was a native confirm(). It is now the
       shared translatable dialog; the tick box is a second deliberate act exactly as before. */
    if(!isReplay){
      const confirmedReversalV291=await confirmDeliberateV288({
        title:'Confirm this reversal?',
        body:kind==='sale'?'This reverses a recorded sale.':'This reverses a recorded loyalty redemption.',
        summaryHtml:'<b>Nothing is deleted</b><p class="small" style="margin-top:5px">The original record stays exactly as it is. Compensating records are added beside it, so the totals move but the history still shows what happened.</p>',
        acknowledgement:'I understand compensating records will be added.',
        confirmLabel:'Confirm reversal',danger:true});
      if(!confirmedReversalV291){btn.disabled=false;btn.textContent='Confirm reversal';return}
    }
    const {data,error}=await sb.rpc(kind==='sale'?'reverse_sale_fast_v84':'reverse_loyalty_redemption',args);
    if(error){
      const conflict=error.code==='23505'||/conflict|another immutable request|already reversed/i.test(error.message||'');
      const loyaltyShortfall=kind==='sale'&&/loyalty_already_spent/i.test(error.message||'');
      $('revOutcome').innerHTML=loyaltyShortfall
        ?`<div class="err"><b>Some points from this sale are no longer available.</b> The refund was not created. ${S.myRole==='owner'?'An owner can explicitly accept the recorded loyalty shortfall; the customer keeps any reward already issued.':'Ask an owner to review and explicitly accept the loyalty shortfall.'}</div>${S.myRole==='owner'?'<button class="btn danger sm" id="revAcceptLoyaltyShortfall" type="button">Accept shortfall and reverse sale</button>':''}`
        :`<div class="err"><b>${conflict?'Changed-request conflict':'Reversal refused'}.</b> ${esc(error.message||'The database could not prove a safe compensation.')}</div>`;
      const acceptShortfall=$('revAcceptLoyaltyShortfall');
      if(acceptShortfall)acceptShortfall.onclick=async()=>{
        const accepted=await confirmDeliberateV288({
          title:'Accept the loyalty shortfall?',
          body:'Some points earned by this sale have already been used or expired.',
          summaryHtml:'<b>The sale will be reversed.</b><p class="small" style="margin-top:5px">Available points from this sale will be removed. Unavailable points will be recorded as an immutable shortfall, and any reward already issued will stay with the customer.</p>',
          acknowledgement:'I accept the recorded loyalty shortfall and understand the issued reward stays valid.',
          confirmLabel:'Accept and reverse sale',danger:true});
        if(!accepted)return;
        acceptShortfall.disabled=true;
        const {data:overrideData,error:overrideError}=await sb.rpc('reverse_sale_fast_accept_loyalty_shortfall_v480',args);
        if(overrideError){acceptShortfall.disabled=false;$('revOutcome').insertAdjacentHTML('beforeend',`<div class="err">${esc(overrideError.message||'The owner override could not be completed.')}</div>`);return}
        $('revOutcome').innerHTML=reversalResultHtml(kind,overrideData||{});
        btn.disabled=true;btn.textContent='Completed';$('revCancel').textContent='Done';
        toast('Reversal completed with recorded loyalty shortfall');
      };
      btn.disabled=false;btn.textContent='Retry same request';return;
    }
    $('revOutcome').innerHTML=reversalResultHtml(kind,data||{});
    btn.disabled=true;btn.textContent='Completed';
    $('revCancel').textContent='Done';
    if(!$('revReplay')){
      $('revCancel').insertAdjacentHTML('beforebegin','<button class="btn ghost sm" id="revReplay">Verify exact replay</button>');
      $('revReplay').onclick=()=>invoke(true);
    }
    toast(data?.replayed?'Exact replay returned the completed result':'Reversal completed');
  }
  $('revSubmit').onclick=()=>invoke(false);
}
function bindReversalButtons(onDone){
  document.querySelectorAll('[data-reverse-kind]').forEach(btn=>btn.onclick=()=>{
    const item=reversalItems.get(reversalItemKey(btn.dataset.reverseKind,btn.dataset.reverseId));
    openReversalDialog(btn.dataset.reverseKind,item,onDone);
  });
}

/* V291 (PDPA erasure, owner-only). A customer may ask for their personal details to be removed.
   The browser never does the removal: erase_client_v290 is the single server writer, and it
   REFUSES while the customer still holds value or property, so the refusal below is printed
   verbatim rather than translated into a guess. This register remembers, for this session only,
   which profiles were erased through this screen, so the profile can say so honestly on the
   re-render; it is not a schema claim, and it is deliberately not persisted. */
const erasedClientsV291=new Map();
const eraseClientAttemptsV291=new Map();
/* Deliberately NOT a compliance claim: this dialog says what the software does to the record,
   and nothing about what any law requires. ⚖️ legal wording stays with the business's counsel. */
function openEraseClientDialogV291({clientId,clientName,onDone}){
  const label=String(clientName||'').trim();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="eraseClientModalV291" role="dialog" aria-modal="true" aria-labelledby="eraseClientTitleV291" tabindex="-1"><div class="modal-card" style="max-width:560px">
    <div class="row"><div><h2 id="eraseClientTitleV291">Erase customer data</h2><p class="muted small" style="margin-top:4px" data-merchant-content>${esc(label||'This customer')}</p></div><span class="spacer"></span><button class="btn ghost sm" id="eraseClientCloseV291" type="button">Close</button></div>
    <div class="imp-note" style="margin-top:12px"><b>What is erased</b><p class="small" style="margin-top:5px">The name, phone number, email address and date of birth on this profile are replaced with anonymous placeholders, and the customer's own app sign-in for this business stops resolving to them.</p></div>
    <div class="imp-note" style="margin-top:10px"><b>What stays, and why</b><p class="small" style="margin-top:5px">Sales, points, credit, appointments and every other ledger entry are kept. They are the accounting record of money that changed hands, so they are never deleted \u2014 they simply stop naming a person.</p></div>
    <p class="muted small" style="margin-top:10px">This cannot be undone, and the details cannot be typed back in afterwards.</p>
    <label for="eraseClientReasonV291">Why is this being erased? (required, at least 8 characters)</label>
    <textarea id="eraseClientReasonV291" rows="3" placeholder="e.g. Customer asked us to remove their details"></textarea>
    <label for="eraseClientNameV291">Type the customer's name exactly to confirm</label>
    <input id="eraseClientNameV291" autocomplete="off" data-merchant-content placeholder="${esc(label)}">
    <div id="eraseClientOutcomeV291" role="status" aria-live="polite"></div>
    <div class="row" style="margin-top:16px"><button class="btn danger" id="eraseClientSubmitV291" type="button" disabled>Erase customer data</button><button class="btn ghost sm" id="eraseClientCancelV291" type="button">Cancel</button></div>
  </div></div>`);
  const modal=$('eraseClientModalV291');
  let deactivate,completed=false;
  const close=()=>{if(deactivate)deactivate();else modal?.remove();if(completed&&onDone)onDone()};
  deactivate=CUI.activateDialog(modal,{onClose:close,initialFocus:'#eraseClientReasonV291'});
  $('eraseClientCloseV291').onclick=$('eraseClientCancelV291').onclick=close;
  const reason=$('eraseClientReasonV291'),typed=$('eraseClientNameV291'),submit=$('eraseClientSubmitV291');
  /* Both gates, together: a reason long enough to mean something, and the name transcribed. The
     name match is case- and space-insensitive so it is a deliberate act, not a typing test. */
  const normalise=value=>String(value||'').trim().replace(/\s+/g,' ').toLowerCase();
  const sync=()=>{submit.disabled=!(reason.value.trim().length>=8&&normalise(typed.value)===normalise(label)&&normalise(label)!=='')};
  reason.oninput=sync;typed.oninput=sync;sync();
  submit.onclick=async()=>{
    const text=reason.value.trim();
    if(text.length<8)return toast('Write at least 8 characters');
    const fingerprint=JSON.stringify({client:clientId,reason:text});
    let attempt=eraseClientAttemptsV291.get(clientId);
    if(!attempt||attempt.fingerprint!==fingerprint){
      attempt={fingerprint,key:crypto.randomUUID()};
      eraseClientAttemptsV291.set(clientId,attempt);
    }
    submit.disabled=true;submit.textContent='Erasing…';
    const {data,error}=await sb.rpc('erase_client_v290',{
      p_business:S.biz.id,p_client:clientId,p_reason:text,p_idem:attempt.key});
    if(!modal.isConnected)return;
    if(error){
      /* The server refuses while active value or kept property remains. Its sentence is the
         truthful one; do not replace it with a generic failure. */
      $('eraseClientOutcomeV291').innerHTML=`<div class="err"><b>Nothing was erased.</b> ${esc(error.message||'The server refused this request.')}</div>`;
      submit.disabled=false;submit.textContent='Erase customer data';return;
    }
    completed=true;
    eraseClientAttemptsV291.delete(clientId);
    erasedClientsV291.set(String(clientId),{reason:text,at:new Date().toISOString(),result:data||null});
    $('eraseClientOutcomeV291').innerHTML='<div class="imp-note"><b>Personal details erased.</b> The ledger entries for this customer are unchanged.</div>';
    submit.textContent='Erased';$('eraseClientCancelV291').textContent='Done';
    toast('Customer data erased');
  };
}

const saleCorrectionAttempts=new Map();
function openSaleAmountCorrectionDialog(item,onDone){
  if(!item?.id||item.reversal_of||Number(item.amount_cents)<=0||item.kind!=='quick_sale'){
    return toast('Only an active quick sale can use fast amount correction');
  }
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="saleCorrectionModal" role="dialog" aria-modal="true" aria-labelledby="saleCorrectionTitle" tabindex="-1"><div class="modal-card" style="max-width:540px">
    <div class="row"><div><h2 id="saleCorrectionTitle">Amend sale amount</h2><p class="muted small">${esc(item.customer_name||'Walk-in')} · original ${money(Number(item.amount_cents))}</p></div><span class="spacer"></span><button class="btn ghost sm" id="saleCorrectionClose" type="button">Close</button></div>
    <div class="imp-note"><b>The original stays in history.</b> ${esc(BRAND.productName)} reverses it and records a corrected replacement together, so customer points and financial records stay synchronized.</div>
    <label for="saleCorrectedAmount">Amended amount (${esc(S.biz.currency||'SGD')})</label>
    <input id="saleCorrectedAmount" type="number" min="0.01" step="0.01" inputmode="decimal" value="${(Number(item.amount_cents)/100).toFixed(2)}">
    <label for="saleCorrectionNote">Correction note (optional)</label>
    <textarea id="saleCorrectionNote" rows="3" placeholder="Add context only if useful"></textarea>
    <label style="display:flex;gap:9px;align-items:flex-start;color:var(--ink2)"><input id="saleCorrectionChecked" type="checkbox" style="width:auto;margin-top:2px">I checked the customer, branch, team member and corrected amount.</label>
    <div id="saleCorrectionOutcome" role="status" aria-live="polite"></div>
    <div class="row" style="margin-top:16px"><button class="btn danger" id="saleCorrectionSubmit" type="button" disabled>Confirm correction</button><button class="btn ghost sm" id="saleCorrectionCancel" type="button">Cancel</button></div>
  </div></div>`);
  const modal=$('saleCorrectionModal'),amount=$('saleCorrectedAmount'),checked=$('saleCorrectionChecked');
  let deactivateDialog,completed=false;
  const close=()=>{if(deactivateDialog)deactivateDialog();else modal?.remove();if(completed&&onDone)onDone()};
  deactivateDialog=CUI.activateDialog(modal,{onClose:close,initialFocus:'#saleCorrectedAmount'});
  $('saleCorrectionClose').onclick=$('saleCorrectionCancel').onclick=close;
  const correctedCents=()=>Math.round(Number(amount.value||0)*100);
  const sync=()=>{
    const cents=correctedCents();
    $('saleCorrectionSubmit').disabled=!checked.checked||!(cents>0)||cents===Number(item.amount_cents);
  };
  checked.onchange=sync;amount.oninput=sync;
  $('saleCorrectionSubmit').onclick=async()=>{
    const cents=correctedCents(),note=$('saleCorrectionNote').value.trim();
    if(!(cents>0))return toast('Enter the corrected amount');
    if(cents===Number(item.amount_cents))return toast('The amount has not changed');
    /* V291: translatable final check before an amount is replaced. */
    const confirmedCorrectionV291=await confirmDeliberateV288({
      title:'Replace this amount?',
      body:`${money(Number(item.amount_cents))} \u2192 ${money(cents)}`,
      summaryHtml:'<b>The original stays in history</b><p class="small" style="margin-top:5px">The original sale is reversed and the corrected one is recorded together, so customer points and the money records stay in step.</p>',
      acknowledgement:'I have checked the corrected amount.',
      confirmLabel:'Replace the amount',danger:true});
    if(!confirmedCorrectionV291||!modal.isConnected)return;
    const fingerprint=JSON.stringify({sale:item.id,amount_cents:cents,note:note||null});
    let attempt=saleCorrectionAttempts.get(item.id);
    if(!attempt||attempt.fingerprint!==fingerprint){
      attempt={fingerprint,key:crypto.randomUUID()};
      saleCorrectionAttempts.set(item.id,attempt);
    }
    const submit=$('saleCorrectionSubmit');submit.disabled=true;submit.textContent='Correcting…';
    const {data,error}=await sb.rpc('correct_quick_sale_amount_v84',{
      p_business:S.biz.id,p_sale:item.id,p_corrected_amount_cents:cents,
      p_idempotency_key:attempt.key,p_note:note||null
    });
    if(error){
      $('saleCorrectionOutcome').innerHTML=`<div class="err"><b>Correction refused.</b> ${esc(error.message||'No records were changed.')}</div>`;
      submit.disabled=false;submit.textContent='Retry correction';return;
    }
    completed=true;
    $('saleCorrectionOutcome').innerHTML=`<div class="imp-note"><b>${data?.replayed?'Correction verified':'Amount corrected'}.</b> Original ${money(Number(data?.original_amount_cents||item.amount_cents))}; replacement ${money(Number(data?.corrected_amount_cents||cents))}${Number(data?.points_earned||0)?` · ${Number(data.points_earned)} points earned on the replacement`:''}.</div>`;
    submit.disabled=true;submit.textContent='Completed';$('saleCorrectionCancel').textContent='Done';
    saleCorrectionAttempts.delete(item.id);
    toast(data?.replayed?'Correction retry verified':'Sale corrected and synchronized');
  };
}

/* ---------- branch filter (shared: dashboard, daily report, P&L, reports) ----------
   One picker implementation reused by all four analytics pages. Owner/manager ("admin"
   role_class) get every branch plus "All branches (consolidated)"; an employee only ever
   sees branches they're actually assigned to via staff_branches — consolidated is never
   offered to them, matching app.can_see_branch()'s server-side rule (p_branch=null is
   ALWAYS denied for a non-admin, even one assigned to every branch individually). The
   branches table itself is readable business-wide by any staff member (v17 deliberately
   left it unscoped so the picker has names to show) — the allow-list built here is what
   the *picker offers*, not the security boundary; the real boundary is server-side
   RLS/RPC, which every consumer of this filter still applies on its own query. */
/* V370: the same answer was fetched on every navigation (wireProfile hydrates the top-bar
   selector unconditionally), on every profile/bell menu open AND close (renderProfile re-runs
   wireProfile), and a second time by the dashboard's own load(). A branch roster changes only
   through the Branches page and the Team panel, both of which invalidate below, so it is held
   for a short window keyed by the firm, the person and their role — role is in the key because
   the admin and employee branches of this function return different sets. */
async function visibleBranchesForCurrentUser({refresh=false}={}){
  const cacheKeyV370=`${S.biz?.id||''}:${S.user?.id||''}:${S.myRole||''}`;
  if(!refresh&&bootstrapCacheFreshV370(branchScopeCacheV370,cacheKeyV370,BOOTSTRAP_CACHE_TTL_V370.branches)){
    /* A fresh array per caller: refreshBranchFilter and the dashboard both sort and filter what
       they get back, and handing out the cached array itself would let one caller's work show up
       in another's. */
    const cached=branchScopeCacheV370.result;
    return {isAdmin:cached.isAdmin,branches:cached.branches.map(branch=>({...branch}))};
  }
  const isAdmin=S.myRole==='owner'||S.myRole==='manager';
  let branches=[];
  if(isAdmin){
    const {data,error}=await sb.from('branches').select('id,name,active,billing_state').eq('business_id',S.biz.id).order('name');
    if(error)throw error;
    branches=data||[];
  }else{
    const {data:me,error:staffError}=await sb.from('staff').select('id').eq('business_id',S.biz.id).eq('user_id',S.user.id).limit(1);
    if(staffError)throw staffError;
    if(me&&me.length){
      const {data,error}=await sb.from('staff_branches').select('branches(id,name,active,billing_state)').eq('business_id',S.biz.id).eq('staff_id',me[0].id);
      if(error)throw error;
      branches=(data||[]).map(r=>r.branches).filter(Boolean).sort((a,b)=>(a.name||'').localeCompare(b.name||''));
    }
  }
  /* Only a SUCCESSFUL read is cached — every failure path above throws, so reaching here means
     the roster is real. */
  branchScopeCacheV370={key:cacheKeyV370,at:Date.now(),result:{isAdmin,branches}};
  return {isAdmin,branches:branches.map(branch=>({...branch}))};
}
/* V285: no page mounts a wrap for this any more. V260/V272 removed the per-page pickers one at a
   time and V285 removed the last two (P&L and Customer intelligence), so the top bar's selector is
   the workspace's single branch control and the pages simply read selectedBranchId. The helper is
   kept intact — it is the only implementation of the employee/admin offer rule and of the
   "never write into a wrap the route has replaced" guard, and a future surface that genuinely
   needs its own picker should reuse it rather than write a third one. */
async function refreshBranchFilter(onChange,isCurrent=()=>true,targetId='branchWrap'){
  const targetIds=Array.isArray(targetId)?targetId:[targetId];
  const currentWraps=()=>targetIds.map(id=>({id,wrap:$(id)})).filter(item=>item.wrap);
  const initialWraps=currentWraps();
  if(!initialWraps.length){ onChange(); return; }
  let isAdmin=S.myRole==='owner'||S.myRole==='manager',branches=[];
  try{({isAdmin,branches}=await visibleBranchesForCurrentUser())}
  catch(e){
    const wraps=currentWraps();
    if(!isCurrent()||!wraps.length)return;
    console.error(e);
    wraps.forEach(({id,wrap})=>{
      if(!wrap.isConnected||$(id)!==wrap)return;
      wrap.innerHTML=`<span class="err small">Branch list unavailable.</span> <button type="button" class="btn ghost sm" data-branch-filter-retry>Retry</button>`;
      const retry=wrap.querySelector('[data-branch-filter-retry]');
      if(retry)retry.onclick=()=>refreshBranchFilter(onChange,isCurrent,targetId);
    });
    return;
  }
  const wraps=currentWraps();
  if(!isCurrent()||!wraps.length)return;
  /* V217: same rule as the top bar — an inactive branch is never a selectable reporting scope. */
  const withheldBranchesV217=branches.filter(branch=>branch.active===false);
  branches=activeBranchesForScopeV217(branches);
  if(!branches.some(branch=>branch.id===selectedBranchId)){
    /* Employees can't request consolidated (the server raises branch_visibility on
       p_branch=null for them) — default to their first assigned branch so the page loads
       clean instead of surfacing that error on first paint. Owners and managers instead
       fall back to the truthful consolidated choice when a remembered branch disappeared. */
    selectedBranchId=isAdmin?null:(branches[0]?.id||null);
  }
  const syncSelections=()=>{
    currentWraps().forEach(({wrap})=>{
      const select=wrap.querySelector('select');
      if(select)select.value=selectedBranchId||'';
    });
  };
  wraps.forEach(({id,wrap})=>{
    if(!wrap.isConnected||$(id)!==wrap)return;
    wrap.innerHTML=(branches.length||isAdmin)
      ? `<select class="qbtn" aria-label="Business branch" style="padding-right:22px">
        ${isAdmin?`<option value="">All branches (consolidated)</option>`:''}
        ${branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}
      </select>${withheldBranchesV217.length?`<p class="muted small" style="margin:6px 0 0">${esc(withheldBranchesV217.map(branchScopeUnavailableReasonV217).join(' '))}</p>`:''}`
      : `<span class="muted small">No branch assigned — ask the owner</span>`;
    const sel=wrap.querySelector('select');
    if(sel){
      sel.value=selectedBranchId||'';
      sel.onchange=()=>{selectedBranchId=sel.value||null;syncSelections();onChange(branches.find(branch=>branch.id===selectedBranchId)||null)};
    }
  });
  onChange(branches.find(branch=>branch.id===selectedBranchId)||null);
}
let reportingScopeV155={mode:'current',branchIds:[]};
/* V217. Owner: the dashboard said "Performance data could not be loaded" and Customers said
   "foreign_or_inactive_branch_scope". One cause for both. A branch added but not yet paid for is
   created active=false / billing_state=pending_payment, and this function fell back to
   branches[0] without looking at `active`. The demo tenant's unpaid branch was named "abc",
   which sorts first, so it silently became the reporting scope for the whole workspace — and
   every reporting RPC refuses an inactive branch by design (v155 raises
   foreign_or_inactive_branch_scope). The workspace was offering a scope the server can never
   answer. An inactive branch is never a valid reporting scope, so it is never chosen here. */
function activeBranchesForScopeV217(branches=[]){
  return (branches||[]).filter(branch=>branch&&branch.active!==false);
}
function branchScopeUnavailableReasonV217(branch){
  if(!branch||branch.active!==false)return '';
  return branch.billing_state==='pending_payment'
    ?`${branch.name||'This branch'} is waiting for payment, so its reports are not available yet.`
    :`${branch.name||'This branch'} is switched off, so its reports are not available.`;
}
/* V272: removing the Business Insights branch select also removed the only place that said an
   unpaid or switched-off branch is LEFT OUT of these figures. A consolidated total nobody can
   scope is the failure this page exists to avoid, and the top bar deliberately carries no such
   pill (V224), so the fact is restated once, next to the figures, in the owner's own terms. */
function reportScopeNoteTextV272(branches=[]){
  const usable=activeBranchesForScopeV217(branches);
  const current=selectedBranchId?usable.find(branch=>branch.id===selectedBranchId):null;
  const covered=current
    ?`${current.name||'the branch selected at the top'} only`
    :usable.length>1
      ?`all ${usable.length} branches you can report on (${usable.map(branch=>branch.name||'Branch').join(', ')})`
      :(usable[0]?.name||'this business');
  const withheld=(branches||[]).filter(branch=>branch&&branch.active===false)
    .map(branchScopeUnavailableReasonV217).filter(Boolean);
  return `Figures below cover ${covered}. ${withheld.join(' ')}`.trim();
}
async function renderReportScopeNoteV272(isCurrent=()=>true,targetId='reportScopeNoteV272'){
  const host=$(targetId);
  if(!host)return;
  let branches=[];
  try{({branches}=await visibleBranchesForCurrentUser())}
  catch(error){
    console.error(error);
    if(isCurrent()&&$(targetId)===host)host.textContent='The branches these figures cover could not be confirmed.';
    return;
  }
  if(!isCurrent()||$(targetId)!==host)return;
  host.textContent=reportScopeNoteTextV272(branches);
}
/* V217: the server's scope codes are precise but unreadable. An owner should never be shown
   `foreign_or_inactive_branch_scope` — they should be told which branch is unavailable and why,
   which after this change should not happen at all, since the pickers no longer offer one. */
function branchScopeErrorHintV217(error){
  const message=String(error?.message||error||'');
  if(/foreign_or_inactive_branch_scope/.test(message))
    return 'The branch being viewed is switched off or waiting for payment. Choose another branch at the top.';
  if(/unauthorised_branch_scope/.test(message))
    return 'You do not have access to the branch being viewed. Choose another branch at the top.';
  if(/operational_branch_required_for_current_scope/.test(message))
    return 'No branch is selected. Choose one at the top.';
  return '';
}
function reportingOperationalBranchIdV155(branches=[]){
  const usable=activeBranchesForScopeV217(branches);
  if(selectedBranchId&&usable.some(branch=>branch.id===selectedBranchId))return selectedBranchId;
  return usable[0]?.id||null;
}
function normaliseReportingScopeV155({branches=[]}={}){
  /* V217: an inactive branch is not an authorised scope — see reportingOperationalBranchIdV155. */
  const authorisedIds=new Set(activeBranchesForScopeV217(branches).map(branch=>branch.id));
  reportingScopeV155={
    mode:['current','selected','all'].includes(reportingScopeV155?.mode)?reportingScopeV155.mode:'current',
    branchIds:[...new Set(reportingScopeV155?.branchIds||[])].filter(id=>authorisedIds.has(id))
  };
  if(reportingScopeV155.mode==='selected'&&!reportingScopeV155.branchIds.length){
    const fallback=reportingOperationalBranchIdV155(branches);
    reportingScopeV155={mode:'current',branchIds:fallback?[fallback]:[]};
  }
  return reportingScopeV155;
}
/* V225: with the per-page scope pickers removed, the top bar is the only control left — so it
   has to actually govern. "All branches" there means consolidated reporting; a named branch
   means that branch. Deriving it here rather than storing a second copy is what stops the two
   from disagreeing, which is the whole reason the second picker was struck out. */
function currentReportingScopePayloadV155(branches=[]){
  const scope=normaliseReportingScopeV155({branches});
  const usable=activeBranchesForScopeV217(branches);
  const followsTopBar=scope.mode!=='selected';
  const mode=followsTopBar?(selectedBranchId?'current':'all'):'selected';
  return {
    p_scope_mode:usable.length?mode:scope.mode,
    p_branch_ids:mode==='selected'?scope.branchIds:[],
    p_operational_branch:reportingOperationalBranchIdV155(branches)
  };
}
function reportingScopeLabelV155(branches=[]){
  const scope=normaliseReportingScopeV155({branches});
  /* V225: follow the same derivation as the payload, so a caption never contradicts the numbers. */
  if(scope.mode!=='selected'&&activeBranchesForScopeV217(branches).length&&!selectedBranchId){
    return branches.length>1?'All accessible branches':(branches[0]?.name||'All accessible branches');
  }
  const byId=new Map((branches||[]).map(branch=>[branch.id,branch.name||'Branch']));
  if(scope.mode==='all')return branches.length>1?'All accessible branches':(branches[0]?.name||'All accessible branches');
  if(scope.mode==='selected'){
    const names=scope.branchIds.map(id=>byId.get(id)).filter(Boolean);
    if(names.length>2)return `${names.slice(0,2).join(' + ')} + ${names.length-2} more`;
    return names.join(' + ')||'Selected branches';
  }
  return byId.get(reportingOperationalBranchIdV155(branches))||'Current branch';
}
function campaignScopeLabelV155(branches=[]){
  return reportingScopeLabelV155(branches);
}
async function renderReportingScopeSelectorV155(onChange,isCurrent=()=>true,targetId='reportingScopeWrap'){
  const wrap=$(targetId);
  if(!wrap){onChange?.();return}
  let branches=[];
  try{({branches}=await visibleBranchesForCurrentUser())}
  catch(error){
    console.error(error);
    if(isCurrent())wrap.innerHTML=`<span class="err small">Reporting scope unavailable.</span> <button type="button" class="btn ghost sm" id="${targetId}Retry">Retry</button>`;
    const retry=$(`${targetId}Retry`);if(retry)retry.onclick=()=>renderReportingScopeSelectorV155(onChange,isCurrent,targetId);
    return;
  }
  if(!isCurrent())return;
  normaliseReportingScopeV155({branches});
  const scope=reportingScopeV155;
  const modeOptions=`<option value="current">Current branch</option>${branches.length>1?'<option value="selected">Selected branches</option><option value="all">All branches</option>':'<option value="all">All accessible branches</option>'}`;
  wrap.innerHTML=`<div class="reporting-scope-control" data-reporting-scope-v155>
    <label class="sr-only" for="${targetId}Mode">Reporting scope</label>
    <select id="${targetId}Mode" class="qbtn" aria-label="Reporting scope">${modeOptions}</select>
    <div class="reporting-scope-branches" id="${targetId}Branches" aria-label="Selected reporting branches"></div>
    <span class="scope-pill">${esc(reportingScopeLabelV155(branches))}</span>
  </div>`;
  const mode=$(`${targetId}Mode`),branchHost=$(`${targetId}Branches`);
  mode.value=scope.mode;
  const renderBranches=()=>{
    if(!branchHost)return;
    branchHost.innerHTML=reportingScopeV155.mode==='selected'
      ?branches.map(branch=>`<label><input type="checkbox" value="${esc(branch.id)}" ${reportingScopeV155.branchIds.includes(branch.id)?'checked':''}> ${esc(branch.name||'Branch')}</label>`).join('')
      :'';
    branchHost.querySelectorAll('input[type="checkbox"]').forEach(input=>input.onchange=()=>{
      reportingScopeV155.branchIds=[...branchHost.querySelectorAll('input[type="checkbox"]:checked')].map(el=>el.value);
      normaliseReportingScopeV155({branches});
      renderReportingScopeSelectorV155(onChange,isCurrent,targetId);
      onChange?.();
    });
  };
  renderBranches();
  mode.onchange=()=>{
    reportingScopeV155.mode=mode.value;
    if(reportingScopeV155.mode==='selected'&&!reportingScopeV155.branchIds.length){
      const op=reportingOperationalBranchIdV155(branches);reportingScopeV155.branchIds=op?[op]:[];
    }
    normaliseReportingScopeV155({branches});
    renderReportingScopeSelectorV155(onChange,isCurrent,targetId);
    onChange?.();
  };
}

/* ---------- dashboard ---------- */
function wireLocalCollapseV154(buttonId,bodyId,storageKey,{openText='Minimise',closedText='Expand'}={}){
  const button=$(buttonId),body=$(bodyId);
  if(!button||!body)return;
  const saved=localStorage.getItem(storageKey);
  const setOpen=open=>{
    body.hidden=!open;
    button.setAttribute('aria-expanded',String(open));
    button.textContent=open?openText:closedText;
  };
  setOpen(saved===null?true:saved==='true');
  button.onclick=()=>{const next=button.getAttribute('aria-expanded')!=='true';localStorage.setItem(storageKey,String(next));setOpen(next)};
}
/* V170: the dashboard must answer "how did the business do" in one sentence before the owner
   reads a single tile. Both the current and the previous-equivalent summary are already
   fetched, so the headline, the per-tile deltas and the loyalty row are all read from the
   figures the KPIs already use. Nothing here invents a total, and a missing or empty previous
   period says so rather than printing a zero the owner would read as a real comparison. */
function dashboardRangeLabelV170(from,to){
  if(from!==to)return `${from} – ${to}`;
  return from===sgDateInputValue()?'today':`on ${from}`;
}
/* V200 (owner: "remove this redundant line"). The V170 headline restated the Revenue and Visits
   tiles that sit directly beneath it, and its comparison sentence restated the per-tile delta
   chips. Two readings of the same two numbers, one above the other. The tiles carry the figure,
   the range and the delta, so the headline was pure duplication and is gone. */
function dashboardDeltaChipV170(change,previousFrom,previousTo){
  if(change===null||change===undefined||!Number.isFinite(change))return '';
  const word=change>0?'up':change<0?'down':'level';
  const glyph=change>0?'▲':change<0?'▼':'▬';
  /* V299: a fall now reads in the same three-tone language Business Insights already uses —
     a −18% and a 0% were both the identical grey pill, distinguished only by the glyph. */
  return `<span class="metric-delta pill ${change>0?'ok':change<0?'no':'off'}"><span aria-hidden="true">${glyph} ${Math.abs(change)}%</span><span class="sr-only">${Math.abs(change)}% ${word} versus ${esc(previousFrom)} to ${esc(previousTo)}</span></span>`;
}
/* V385 (owner markup on the dashboard, photo 1: the ▲400% chip ringed with "Compare with
   what? please state here"). The chip already knew its answer — previousEquivalentRangeV153
   hands it the previous equal-length period — but that answer was only ever spoken to a screen
   reader, inside the .sr-only span. A sighted owner read a percentage with no denominator.
   One caption for the whole row, not one per tile: every chip on the row is measured against
   the SAME previous period, so repeating it four times would be four readings of one fact. It
   is printed only when at least one tile actually has a comparison to make — a first-ever
   period has no previous equivalent, and percentageChangeV153 returns null for all of them. */
/* V385: the house "?" affordance, reworked at V388.
   V385 opened a dialog. The owner (photo 3): "don't need to pop up, usually for such ? or hint
   will just be a text when hover mouse over." So the copy rides the control itself — a CSS
   bubble on hover, the same bubble on keyboard focus so it is not mouse-only, and `title` as the
   native fallback for touch and for anything that reads attributes. No dialog, nothing to
   dismiss, and no wiring at all: the markup IS the behaviour, so a second caller anywhere is one
   markup call. */
function helpDotMarkupV385(title,body){
  const text=String(body||'');
  /* No `title` attribute: it would duplicate the bubble, and an interpolated one is a dynamic
     accessibility attribute the v97 audit rightly refuses outside the named-template mechanism.
     The bubble is the visible copy and the aria-label is the spoken one, both from here. */
  return ` <span class="help-dot-v385" tabindex="0" role="note" ${workspaceTemplateAttributeV97('aria-label','explainHelpDotV385',{topic:String(title||'this')})}><span aria-hidden="true">?</span><span class="help-dot-bubble-v385" data-merchant-content>${esc(text)}</span></span>`;
}
/* V387 (owner, second pass on photo 1: the ▲400% chip ringed again — "the 400% still unknown").
   The V385 legend answered "which period", which is not the question. The question a percentage
   raises is "400% of WHAT", and the only answer is the previous period's own number. It is
   printed on the tile it belongs to, directly under the figure it is compared with, so the two
   numbers can be read against each other without the eye leaving the tile.
   Drawn only when there IS a comparison: a tile with no delta has no previous figure worth
   stating, and a first-ever period would otherwise print "was 0" and invite the reading that
   the business went from nothing to something when nobody was measured at all. */
/* V388: the rows behind a KPI tile.
   The hard rule here is the one V287 was written for — the number on the tile and the list it
   opens must be the same set of people, or the owner is reading two different truths. So each
   reader below reproduces the SERVER's definition rather than inventing a near-enough one:

     new       get_dashboard_summary_v155 counts clients.created_at inside the Singapore day
               window, business-wide, with no other predicate. This is that query, exactly.
     inactive  the tile already drills through staff_list_customers_v155's all_inactive bucket
               (V290); the dialog asks the same RPC for the rows instead of the count.
     visits    the server's valid_visits CTE is counts_as_visit, not a reversal, and not itself
               reversed — which is precisely validVisitSales(), the helper this codebase already
               shares between Customer 360 and bring-back audiences for that reason.
     revenue   the same scoped rows, kept where counts_as_revenue, summed.

   A read that fails says so. It never falls back to a shorter list, because a shorter list under
   a bigger number is worse than an error. */
/* V406: staff_list_customers_v155 refuses a p_limit outside 1..100. This is that ceiling, named
   once so the request and the "showing the first N" line can never disagree. */
const DASHBOARD_INACTIVE_PAGE_V406=100;
/* V405 (owner, photo 6: the KPI tiles "must be able to pop up the data").
   This map used to be declared INSIDE dashboard(). openDashboardMetricRowsV388 is a TOP-LEVEL
   function and read it from there, so every tile click since v388 threw a ReferenceError before
   the dialog was built — as an unhandled promise rejection, which prints nothing a user or
   window.onerror can see, so the tile simply did nothing at all. Reproduced in production before
   this change: the wiring was never the problem, the scope was.
   It is pure data — labels, definitions, routes, button copy, scope — with no closure dependency,
   so it belongs at module scope where BOTH readers can actually see it. */
const DASHBOARD_METRIC_DEFINITIONS_V405={
  visits:{label:'Valid visits',definition:'Original visit sales in this selected period that have not been reversed. Reversal rows are not counted as visits.',action:'View sales',buttonLabel:'View visits',scope:'branch'},
  revenue:{label:'Revenue',definition:'Net revenue from sale records in this selected period, after recorded reversals.',action:'View sales',buttonLabel:'View revenue',scope:'branch'},
  new:{label:'New customer members',definition:'Customer membership or customer records created during the selected period. This figure is business-wide unless the record has an auditable branch attribution.',action:'View customers',buttonLabel:'See new customers',scope:'business'},
  /* V287: this tile counted 30-59 PLUS 60+ and then drilled through to the 30-59 bucket
     only, so the number an owner tapped and the list they landed on could never agree. The
     server's staff_list_customers_v155 accepted exactly four buckets ('30_59','60_89',
     '90_plus','never') and raised unsupported_inactivity_bucket for anything else, so an
     "all inactive" destination was not expressible without a migration, and the number was
     narrowed to match the destination.
     V290 wrote that migration: 'all_inactive' is now an accepted bucket, so the tile counts
     every customer quiet for 30 days or more and lands on exactly that group. The narrowing
     is undone; the rule it enforced — the number and the destination must be the same set of
     people — is what still holds. */
  inactive:{label:'Inactive customers',definition:'Customers whose last valid visit was 30 or more complete Singapore days ago. Tapping this tile opens exactly this group. Never-visited customers are counted separately.',action:'View inactive customers',buttonLabel:'See inactive customers',scope:'business-current'}
};

/* V468 (owner photos 3, 8 and 9: "View visits", "See new customers" and "See inactive customers"
   all did nothing). CUI.activateDialog's teardown unwinds the dialog's pushed history entry with
   history.back(), which is ASYNCHRONOUS — nav() set the hash synchronously and the queued pop
   then undid it, so the dialog shut and the page never moved. This is exactly the v183 sheet
   defect in a second place, and the established fix is reused rather than reinvented: hand the
   dialog's own entry to the destination with replaceState, then route by hand. Every navigating
   exit of a business dialog goes through here, so the footer report link and the per-row customer
   buttons can never drift apart again. */
function dialogHandOffNavV468(close,href){
  const target=String(href||'');
  if(!target){close();return}
  const handOff=(CUI.currentDialogHistoryId?.()||0)>0;
  close({restoreFocus:false,handOffHistory:handOff});
  if(!handOff){nav(target);return}
  try{history.replaceState(null,'',target)}catch{location.hash=target;return}
  route();
}

/* V468 (owner photo 20, arrows from all four Daily report figures: "It needs to be clickable to
   view what is inside"). Two seams were added rather than a second dialog: `def` lets a caller
   bring its own label/definition/route, and `loadRows` lets it supply the rows it can prove match
   its own tile. Everything else — the history hand-off, the customer-cell buttons, the table
   chrome, the error wording — stays in one place. `subtitle` replaces the hardcoded date range
   for a caller whose figure covers a single day. */
async function openDashboardMetricRowsV388(options){
  /* V468: bound with `const`, not as a renamed destructuring target (`{def:defV468}`) and not as a
     bare V-suffixed parameter. The repo's undeclared-identifiers gate is regex-based and sees
     neither form as a declaration, so either one turns a correct edit into a red gate. Keeping the
     gate honest is worth more than the shorter signature — see [[undeclared-identifier-ships-silently]]. */
  const {key,from,to,scopePayload,value,loadRows}=options;
  /* nestly_v519: see the call site — the resolved reporting branch ids, or null when the caller
     supplies its own rows (the Daily report) and no branch filter is this function's business. */
  const branchIdsV519=Array.isArray(options.branchIdsV519)?options.branchIdsV519:null;
  const subtitleV468=options.subtitle;
  const def=options.def||DASHBOARD_METRIC_DEFINITIONS_V405[key]||{};
  const periodTextV468=subtitleV468!==undefined
    ?String(subtitleV468||'')
    :(key==='inactive'?'':`${promotionDateShortV324(from)} – ${promotionDateShortV324(to)}`);
  document.getElementById('metricRowsModalV388')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="metricRowsModalV388" role="dialog" aria-modal="true" aria-labelledby="metricRowsTitleV388" tabindex="-1"><div class="modal-card" style="max-width:640px">
    <div class="row"><div><h2 id="metricRowsTitleV388" style="font-size:16px">${esc(def.label||'Details')}</h2><p class="muted small" style="margin-top:4px">${esc(value)}${periodTextV468?` · ${esc(periodTextV468)}`:''}</p></div><span class="spacer"></span><button class="btn ghost sm" id="metricRowsCloseV388" type="button">Close</button></div>
    <div id="metricRowsBodyV388" style="margin-top:14px" aria-live="polite">${CUI.loadingState({title:'Loading',iconName:'reports'})}</div>
    ${/* V470 (owner, four photos, "remove this button" on View visits / View revenue / See new
         customers / See inactive customers). The dialog was built in v388 as a preview that handed
         off to a report; since v408 every row in it opens the customer directly, so the footer was
         a second, worse way to reach the same place — and the one the owner kept pressing. The
         rows are the destination now. Close is the only exit. */''}
  </div></div>`);
  const modal=document.getElementById('metricRowsModalV388');
  let deactivate;
  /* V468: `close` now forwards its options to the deactivator. The plain Close button still calls
     it bare and keeps today's behaviour; only the two navigating exits pass the hand-off. */
  const close=options=>{if(deactivate)deactivate(options);else modal?.remove()};
  deactivate=CUI.activateDialog(modal,{onClose:close,initialFocus:'#metricRowsCloseV388'});
  document.getElementById('metricRowsCloseV388').onclick=()=>close();
  const body=document.getElementById('metricRowsBodyV388');
  const stillOpen=()=>body.isConnected;
  /* V408 (owner, photo 3: "now that the boxes are clickable — I need to be able to click into the
     individual customer selection"). Each row that HAS a customer opens that customer's profile.
     A row without one — a walk-in sale — is deliberately left inert rather than given a dead
     control: there is no profile to open, and a button that does nothing is worse than plain text.
     The dialog closes before navigating, the same hand-off its footer link already performs, so
     the profile is never rendered underneath an open modal. */
  const customerCellV408=(clientId,label,sub)=>{
    const body=`<b>${esc(label)}</b>${sub?`<br><span class="muted small">${esc(sub)}</span>`:''}`;
    return clientId
      ? `<button type="button" class="metric-row-customer-v408" data-metric-client-v408="${esc(String(clientId))}">${body}</button>`
      : body;
  };
  const table=(head,rows)=>rows.length
    ?`<div class="cui-table-wrap" tabindex="0"><table class="cui-table" data-responsive="true"><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`
    :`<p class="muted small">Nothing in this period.</p>`;
  const failed=message=>{if(stillOpen())body.innerHTML=`<div class="err" role="alert">${esc(message)}</div>`};
  /* Delegated, so it survives every branch's own innerHTML write without five bindings. */
  body.addEventListener('click',event=>{
    const hit=event.target.closest('[data-metric-client-v408]');
    if(!hit)return;
    dialogHandOffNavV468(close,`#/client/${hit.dataset.metricClientV408}`);
  });
  try{
    /* A caller that already holds the rows behind its own figure renders them here. It is given
       the customer-cell builder so its rows keep the same click-into-the-customer behaviour. */
    if(loadRows){
      const supplied=await loadRows({customerCell:customerCellV408});
      if(!stillOpen())return;
      if(supplied?.error)return failed(ownerErrorText(supplied.error));
      body.innerHTML=table(supplied?.head||[],supplied?.rows||[]);
      if(supplied?.note)body.insertAdjacentHTML('beforeend',`<p class="muted small" style="margin-top:10px">${esc(supplied.note)}</p>`);
      return;
    }
    if(key==='new'){
      const {data,error}=await sb.from('clients').select('id,full_name,phone,created_at')
        .eq('business_id',S.biz.id)
        .gte('created_at',sgDateBoundary(from)).lt('created_at',sgDateBoundary(to,1))
        .order('created_at',{ascending:false}).limit(500);
      if(!stillOpen())return;
      if(error)return failed(ownerErrorText(error));
      body.innerHTML=table(['Customer','Joined'],(data||[]).map(row=>`<tr><td data-label="Customer">${customerCellV408(row.id,row.full_name||'—',row.phone)}</td><td data-label="Joined">${esc(sgLedgerDateV154(row.created_at).date)}</td></tr>`));
      return;
    }
    if(key==='inactive'){
      /* V406: this used to ask for a page of two hundred. staff_list_customers_v155 refuses any
         page size outside 1..100 with 'limit must be between 1 and 100', so the Inactive dialog
         could only ever render that error — invisible until V405 let the dialog open at all.
         The constant below is the SERVER's ceiling, not a number chosen here. */
      const {data,error}=await sb.rpc('staff_list_customers_v155',{p_business:S.biz.id,p_search:null,
        p_inactive_bucket:'all_inactive',p_limit:DASHBOARD_INACTIVE_PAGE_V406,p_offset:0,...scopePayload});
      if(!stillOpen())return;
      if(error)return failed(ownerErrorText(error));
      /* V407: staff_list_customers_v155 returns {customers,total} — there is no `rows` key, so
         this read produced an empty array on every call and the dialog showed nothing under a
         tile that said 1. It was masked until V406 by the invalid page size failing first.
         `.customers` is what every other reader of this RPC in this file already uses. */
      const rows=Array.isArray(data?.customers)?data.customers:[];
      /* V287's rule is that the number and the list describe the same people. A firm with more
         than one page of quiet customers cannot have all of them in one dialog, so rather than
         let a short list quietly contradict the tile, the shortfall is stated and the footer link
         — which carries the same all_inactive bucket — is the way to the rest. */
      const cappedV406=rows.length>=DASHBOARD_INACTIVE_PAGE_V406;
      body.innerHTML=table(['Customer','Last visit'],rows.map(row=>`<tr><td data-label="Customer">${customerCellV408(row.id,row.full_name||'—',row.phone)}</td><td data-label="Last visit">${row.last_visit_at?esc(sgLedgerDateV154(row.last_visit_at).date):'<span class="muted">Never</span>'}</td></tr>`));
      /* V470: this used to say "Open <button> below for the rest" — the button it pointed at is
         gone, so it names the page instead. The rule it exists for is unchanged: a list shorter
         than its own tile must say so rather than quietly contradict the number. */
      if(cappedV406)body.insertAdjacentHTML('beforeend',`<p class="muted small" style="margin-top:10px">Showing the first ${DASHBOARD_INACTIVE_PAGE_V406}. Open Customers for the rest.</p>`);
      return;
    }
    const {data,error}=await fetchAllRowsResult(()=>{
      let query=sb.from('sales')
        .select('id,client_id,amount_cents,occurred_at,kind,counts_as_visit,counts_as_revenue,reversal_of,clients(full_name)')
        .eq('business_id',S.biz.id)
        .gte('occurred_at',sgDateBoundary(from)).lt('occurred_at',sgDateBoundary(to,1));
      /* nestly_v519: mirror the server's own `s.branch_id = any(v_scope_ids)`. Without this the
         Visits and Revenue dialogs read the whole business while their tiles read one branch —
         on Cubbly's empty Kopitiam 2 branch a SGD 0.00 tile opened 56 rows totalling SGD 4485.00.
         An empty resolved list would mean "no authorised branches", which the RPC refuses
         outright, so the tile never renders and this path is unreachable with []. */
      if(branchIdsV519&&branchIdsV519.length)query=query.in('branch_id',branchIdsV519);
      return query.order('occurred_at',{ascending:false});
    });
    if(!stillOpen())return;
    if(error)return failed(ownerErrorText(error));
    const scoped=key==='visits'?validVisitSales(data||[]):(data||[]).filter(row=>row?.counts_as_revenue);
    body.innerHTML=table(['When','Customer',key==='visits'?'Kind':'Amount'],scoped.map(row=>`<tr><td data-label="When">${esc(sgLedgerDateV154(row.occurred_at).date)}</td><td data-label="Customer">${customerCellV408(row.client_id,row.clients?.full_name||'Walk-in','')}</td><td data-label="${key==='visits'?'Kind':'Amount'}">${key==='visits'?esc(String(row.kind||'')):esc(money(row.amount_cents||0))}</td></tr>`));
  }catch(error){failed(ownerErrorText(error))}
}
function dashboardMetricWasLineV387(metric,previousRange){
  if(metric?.was==null||metric?.delta==null||!Number.isFinite(Number(metric.delta)))return '';
  /* Only the NUMBER here. The period is stated once in the legend under the row — every tile is
     measured against the same window, so printing the dates three times would be three readings
     of one fact, which is what V200 deleted a whole headline for. */
  return `<span class="metric-was-v387">was ${esc(metric.was)}</span>`;
}
function dashboardDeltaLegendV385(metrics,previousRange){
  /* V387: `Number(null)` is 0, which IS finite — so the original guard treated "no comparison"
     as a comparison and printed the legend under a row of tiles that had none. Every caller of
     percentageChangeV153 returns null for an absent previous period, so null and undefined are
     the two values that must be rejected before the number is looked at. */
  const hasDeltaV387=metric=>metric?.delta!=null&&Number.isFinite(Number(metric.delta));
  const comparable=(metrics||[]).some(hasDeltaV387);
  if(!comparable||!previousRange?.previousFrom||!previousRange?.previousTo)return '';
  const days=Number(previousRange.days)||0;
  const span=days===1?'day':`${days} days`;
  return `<p class="muted small dashboard-delta-legend-v385" style="grid-column:1/-1;margin:2px 0 0">"was" and ▲▼ are the previous ${esc(span)}: ${esc(promotionDateShortV324(previousRange.previousFrom))} – ${esc(promotionDateShortV324(previousRange.previousTo))}.</p>`;
}
function dashboardLoyaltyRowV170(cards){
  return `<section class="dashboard-loyalty" aria-labelledby="dashboardLoyaltyTitle"><div class="dashboard-loyalty-head">${CUI.icon('loyalty',{size:20})}<div><h3 id="dashboardLoyaltyTitle">Loyalty this period</h3><p class="muted small">Programme activity for the selected dates.</p></div></div><div class="dashboard-loyalty-grid">${cards.map(card=>`<div class="dashboard-loyalty-card"><b>${esc(card.label)}</b><span class="v">${esc(card.value)}</span><span class="metric-hint">${esc(card.hint)}</span>${card.retryId?`<button type="button" class="btn ghost sm" id="${card.retryId}">Retry</button>`:''}</div>`).join('')}</div></section>`;
}
/* V278 (owner brief item 9): the bar's own headline on the Dashboard. A bar owner opening the app
   wants one number first — how many bottles am I holding — and one warning — how many run out this
   week. It reuses list_bar_bottles_v275's branch-scoped counts with a limit of one row rather than
   adding a second aggregate that could disagree with the Bottles page.
   BAR TENANTS ONLY, and FAIL-SOFT in every direction: a non-bar sector, a staff member without
   bottle access, or any error at all renders NOTHING. A Dashboard is the first screen of the day;
   it must never be the screen that breaks. */
async function loadDashboardBottlesV278(root,branchId=null){
  const host=root?.querySelector('#dashboardBottlesV278');
  if(!host)return;
  host.innerHTML='';
  if(!isBarSectorV275())return;
  if(S.myRole!=='owner'&&!canReadModule('bottles'))return;
  const {data,error}=await sb.rpc('list_bar_bottles_v275',{p_business:S.biz.id,p_branch:branchId,
    p_status:null,p_search:null,p_expiring_days:null,p_bottle:null,p_limit:1});
  if(!root.isConnected||root!==$('dashboardView'))return;
  if(error)return;
  const counts=data?.counts||{};
  /* V279: the same status colours and the same capacity gauge the Bottles page shows, read from
     the same RPC — a Dashboard that coloured a status differently would be teaching one habit and
     the page another. */
  const capacity=Number(data?.storage_capacity)||0;
  const inStorage=Number(data?.in_storage ?? counts.in_storage)||0;
  const tile=(label,value,iconName,tone)=>`<div class="card kpi"><div class="l">${CUI.icon(iconName,{size:16})} ${esc(label)}</div><div class="v" style="color:${tone}">${esc(String(value))}</div></div>`;
  host.innerHTML=`<section class="card" aria-labelledby="dashboardBottlesTitleV278" style="margin-bottom:18px">
    <div class="cui-card-head">${CUI.icon('bottle',{size:24})}<div><h2 id="dashboardBottlesTitleV278">Bottles</h2><p>What you are holding for your customers right now.</p></div></div>
    <div class="kpis" style="margin-top:12px">${tile('In storage',capacity?`${inStorage} / ${capacity}`:String(inStorage),'inventory',BOTTLE_STATUS_V275.stored.tone)}${tile('Called',Number(counts.called||0),'bell',BOTTLE_STATUS_V275.called.tone)}${tile('At table',Number(counts.at_table||0),'till',BOTTLE_STATUS_V275.at_table.tone)}${tile('Retrieved',Number(counts.retrieved||0),'export',BOTTLE_STATUS_V275.retrieved.tone)}${tile('Expiring this week',Number(counts.expiring_soon||0),'info',BOTTLE_STATUS_V275.expired.tone)}</div>
    <div class="row" style="margin-top:14px"><a class="btn secondary" href="#/bottles">Open Bottles</a></div>
  </section>`;
}

/* V180 (owner instruction: "I want have simple glance of calendar").
   The Today-schedule strip announced today's bookings but showed none of them — an owner had
   to leave the Dashboard to learn whether anyone was coming in. It now renders today's actual
   appointments inline.
   Deliberate choices:
   - TODAY is fixed, independent of the Performance date range above it. The strip is titled
     "Today schedule"; letting the 30d picker widen it would make the heading a lie.
   - Cancelled appointments are excluded from the count but the count is of what is still ON,
     so "3 today" always means three people are actually expected.
   - A failure renders a plain, retryable line. It never renders "0 today", because an unread
     schedule and an empty schedule mean opposite things to someone deciding whether to go in.
   - Capped at 6 chips with an explicit "+N more" so nothing is silently truncated. */
const DASHBOARD_SCHEDULE_CHIP_LIMIT_V180=6;
/* V252: the strip is no longer fixed to today \u2014 the owner asked to view any date. The day
   is still a SINGAPORE calendar date (sgDateInputValue / sgDateBoundary), never a browser-local
   one, so the window fetched is the same day the tabs and the picker name. Because a day can
   now be changed faster than a read returns, each read takes an epoch: a slower earlier day
   must never paint over the day the owner is looking at. */
let dashboardScheduleEpochV252=0;
const dashboardScheduleDayLabelV252=day=>new Intl.DateTimeFormat('en-SG',{
  day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Singapore'
}).format(new Date(sgDateBoundary(day)));
/* V295 (owner markup 2026-08-13: the card read "Today schedule" above the sentence "Nothing
   booked on 13 Aug 2026" — "should not be static, must follow selected date"). The heading is
   what the owner called static, so it names the day actually on screen. Today and tomorrow keep
   their spoken names because that is how the two tabs are labelled; every other day is stated
   as a date, through the same SGT formatter the body already prints. */
const dashboardScheduleHeadingTextV295=day=>{
  const todayV295=sgDateInputValue();
  if(day===todayV295)return 'Today schedule';
  if(day===shiftSgDateInput(todayV295,1))return 'Tomorrow\u2019s schedule';
  return workspaceTemplateTextV97('scheduleHeadingDay',{date:dashboardScheduleDayLabelV252(day)});
};
async function loadDashboardScheduleGlanceV180(root,branchId=null,dateV252=null){
  const host=root?.querySelector('#dashboardScheduleToday');
  const summary=root?.querySelector('#dashboardScheduleSummary');
  if(!host)return;
  if(!canReadModule('appointments')){host.innerHTML='';return}
  const day=dateV252||sgDateInputValue();
  const isTodayV252=day===sgDateInputValue();
  const dayLabelV252=dashboardScheduleDayLabelV252(day);
  /* V295: written before the fetch. The heading is a property of the DAY, not of the answer, so
     it must never lag behind the day the owner just picked while a read is in flight. */
  const headingHostV295=root?.querySelector('#dashboardScheduleHeadingV295');
  if(headingHostV295)headingHostV295.textContent=dashboardScheduleHeadingTextV295(day);
  const epochV252=++dashboardScheduleEpochV252;
  const isCurrentScheduleV252=()=>root.isConnected&&epochV252===dashboardScheduleEpochV252;
  host.innerHTML=isTodayV252
    ?'<p class="muted small">Loading today\u2019s schedule\u2026</p>'
    :`<p class="muted small">Loading the schedule for ${esc(dayLabelV252)}\u2026</p>`;
  const from=sgDateBoundary(day),to=sgDateBoundary(day,1);
  let query=sb.from('appointments')
    .select('id,starts_at,status,clients(full_name),services!appointments_service_id_fkey(name)')
    .eq('business_id',S.biz.id).gte('starts_at',from).lt('starts_at',to)
    .order('starts_at').order('id').limit(50);
  /* The applied branch scope is a closure variable inside dashboard(), so it is PASSED IN
     rather than read here — reaching for it directly threw a ReferenceError. */
  if(branchId)query=query.eq('branch_id',branchId);
  const {data,error}=await query;
  if(!isCurrentScheduleV252())return;
  if(error){
    host.innerHTML=`<p class="muted small" role="status">${isTodayV252?'Today\u2019s schedule':`The schedule for ${esc(dayLabelV252)}`} could not be loaded. <button type="button" class="btn ghost sm" id="dashboardScheduleRetry">Try again</button></p>`;
    const retry=host.querySelector('#dashboardScheduleRetry');
    if(retry)retry.onclick=()=>loadDashboardScheduleGlanceV180(root,branchId,day);
    return;
  }
  const rows=(data||[]).filter(row=>String(row.status||'').toLowerCase()!=='cancelled');
  if(summary){
    summary.textContent=rows.length
      ?(isTodayV252?`${rows.length} ${rows.length===1?'booking':'bookings'} today.`:`${rows.length} ${rows.length===1?'booking':'bookings'} on ${dayLabelV252}.`)
      :(isTodayV252?'Nothing booked for today.':`Nothing booked on ${dayLabelV252}.`);
  }
  if(!rows.length){
    host.innerHTML=isTodayV252
      ?'<p class="muted small">Nothing booked for today — a free day, or a day to fill.</p>'
      :`<p class="muted small">Nothing booked on ${esc(dayLabelV252)} — a free day, or a day to fill.</p>`;
    return;
  }
  const shown=rows.slice(0,DASHBOARD_SCHEDULE_CHIP_LIMIT_V180);
  const overflow=rows.length-shown.length;
  host.innerHTML=`<ol class="dashboard-schedule-chips">${shown.map(row=>{
    const time=(sgt(row.starts_at)||'').slice(11,16);
    const who=row.clients?.full_name||'Walk-in';
    const what=row.services?.name||'';
    /* V375 (owner, photo 15: the 11:30 row ringed — "clickable to pop-up see details & to
       complete & checkout"). The chip links to the Appointments page carrying this appointment's
       id, which that page opens in its existing detail dialog. Deliberately a link to the one
       surface that owns the dialog rather than a second copy of it here: the dialog's complete,
       amend and cancel paths all live inside appointmentsPage's closure. */
    return `<li class="dashboard-schedule-chip"><a class="dashboard-schedule-chip-link-v375" href="#/appointments?appointment=${encodeURIComponent(row.id)}" ${workspaceTemplateAttributeV97('aria-label','viewAppointmentDetails',{customer:who})}><b>${esc(time)}</b><span data-merchant-content>${esc(who)}</span>${what?`<span class="muted small" data-merchant-content>${esc(what)}</span>`:''}</a></li>`;
  }).join('')}${overflow>0?`<li class="dashboard-schedule-chip more"><a href="#/appointments?view=list&preset=today">+${overflow} more</a></li>`:''}</ol>`;
}
/* V182: the benefits SMEs actually offer, in customer-facing words. */
const TIER_BENEFIT_PRESETS_V182=Object.freeze([
  {label:'Birthday treat every year',text:'Birthday treat every year'},
  {label:'Priority booking',text:'Priority booking'},
  {label:'First access to new services',text:'First access to new services'},
  {label:'Free add-on with every visit',text:'Free add-on with every visit'},
  {label:'A welcome gift when they reach this tier',text:'A welcome gift when you reach this tier'}
]);
/* V238: two tier benefit lines are DERIVED, not typed — the owner reported a Diamond tier
   reading "50% more points on every spend" beside a 1.25x multiplier, because the recommended-
   tiers helper wrote the sentence once and nothing ever revisited it. The multiplier owns the
   bonus line and the discount slider owns the discount line; perk_note stays the same newline-
   joined field, so storage, publish and the customer card are untouched. */
const BONUS_POINTS_LINE_RE_V238=/^\d+(\.\d+)?% more points on every spend$/i;
const DISCOUNT_LINE_RE_V238=/^\d+(\.\d+)?% off every visit$/i;
function bonusPointsLineV238(multiplier){
  const pct=Math.round((Number(multiplier)-1)*100);
  return Number.isFinite(pct)&&pct>0?`${pct}% more points on every spend`:'';
}
function discountLineV238(pct){
  const rounded=Math.round(Number(pct));
  return Number.isFinite(rounded)&&rounded>0?`${rounded}% off every visit`:'';
}
/* The threshold means different things per firm, so the help text must follow tier_basis
   rather than hardcode "points" — a spend-based ladder saying "points" is simply wrong. */
function tierBasisHelpV182(program){
  const basis=program?.tier_basis||'visits';
  if(basis==='spend')return 'Total amount this customer has spent with you, in dollars.';
  if(basis==='points_earned')return 'Total points this customer has earned, all time.';
  return 'Number of visits this customer has made.';
}
