  const summaryRowV294=(label,valueHtml,extraHtml='')=>`<div class="c360-summary-row-v294"><span class="c360-summary-label-v294">${esc(label)}</span><span class="c360-summary-value-v294">${valueHtml}</span></div>${extraHtml}`;
