/* Branch scope for the use action. Same role-scoped reader every other branch picker on this
   surface uses, filtered by the same "an inactive branch can never complete anything" rule;
   a failure degrades the card to read-only rather than taking the profile down. */
async function packageUseBranchesV442(){
  try{
    const {branches}=await visibleBranchesForCurrentUser();
    return {branches:activeBranchesForScopeV217(branches),error:false};
  }catch(error){console.error(error);return {branches:[],error:true}}
}
/* The one write this card performs. Same RPC, same idempotency-key discipline and same
   receipt validation as the Packages page's own "Use session" button — a second definition
   of "use a session" is exactly what must not exist. */
async function usePackageSessionV442({businessId,clientPackageId,branchId,attempts}){
  const store=attempts instanceof Map?attempts:new Map();
  const attempt=packageUseAttemptKeyV102(store,clientPackageId,branchId);
  const {data,error}=await sb.rpc('use_package_session_v102',{
    p_business:businessId,p_client_package:clientPackageId,p_branch:branchId,
    p_idempotency_key:attempt.key});
  if(error)return {error};
  const result=packageUseResultV102(data);
  if(!result)return {error:new Error('The package-use receipt was incomplete. Retry with the same branch.')};
  store.delete(attempt.slot);
  return {result};
}
function packageSaleResultV102(data){
  const valid=data?.status==='completed'&&!!data?.sale_id&&!!data?.client_package_id
    &&Number.isFinite(Number(data?.points_earned))&&Number.isFinite(Number(data?.points_total));
  return valid?{
    saleId:String(data.sale_id),
    clientPackageId:String(data.client_package_id),
    pointsEarned:Number(data.points_earned),
    pointsTotal:Number(data.points_total),
    replayed:data.replayed===true
  }:null;
}
function packageUseResultV102(data){
  const valid=data?.status==='completed'&&!!data?.consumption_id&&!!data?.sale_id
    &&!!data?.client_package_id&&!!data?.client_id&&!!data?.branch_id
    &&Number.isFinite(Number(data?.remaining_before))
    &&Number.isFinite(Number(data?.remaining_after))
    &&Number(data?.points_earned)===0
    &&Number.isFinite(Number(data?.points_total));
  return valid?{
    consumptionId:String(data.consumption_id),
    saleId:String(data.sale_id),
    clientPackageId:String(data.client_package_id),
    branchId:String(data.branch_id),
    remainingBefore:Number(data.remaining_before),
    remainingAfter:Number(data.remaining_after),
    pointsEarned:0,
    pointsTotal:Number(data.points_total),
    replayed:data.replayed===true
  }:null;
}
function checkoutPreferencesStateV102(result){
  const available=!result?.error&&result?.data?.status==='available'
    &&typeof result.data.gift_card_sales_enabled==='boolean'
    &&typeof result.data.package_earns_points==='boolean';
  return {
    available,
    giftCardSalesEnabled:available?result.data.gift_card_sales_enabled===true:null,
    packageEarnsPoints:available?result.data.package_earns_points===true:null
  };
}
function packageUseAttemptKeyV102(attempts,clientPackageId,branchId,createKey=()=>crypto.randomUUID()){
  const slot=`${clientPackageId}|${branchId}`;
  if(!attempts.has(slot))attempts.set(slot,createKey());
  return {slot,key:attempts.get(slot)};
}
function checkoutPointsReceiptV102({saleResult,packageResults=[],refreshedPoints=null}={}){
  const operations=[];
  if(saleResult&&Number.isFinite(Number(saleResult.pointsEarned))){
    operations.push({
      kind:'sale',
      pointsEarned:Number(saleResult.pointsEarned),
      pointsTotal:saleResult.pointsTotal!=null&&Number.isFinite(Number(saleResult.pointsTotal))
        ?Number(saleResult.pointsTotal):null
    });
  }
  for(const result of packageResults){
    if(!result||!Number.isFinite(Number(result.pointsEarned)))continue;
    operations.push({
      kind:'package',
      pointsEarned:Number(result.pointsEarned),
      pointsTotal:result.pointsTotal!=null&&Number.isFinite(Number(result.pointsTotal))
        ?Number(result.pointsTotal):null
    });
  }
  const lastOperationTotal=[...operations].reverse().find(item=>item.pointsTotal!=null)?.pointsTotal??null;
  const currentTotal=refreshedPoints!=null&&Number.isFinite(Number(refreshedPoints))
    ?Number(refreshedPoints):null;
  return {
    pointsEarned:operations.reduce((sum,item)=>sum+item.pointsEarned,0),
    // A writer receipt is the checkout snapshot. A later lookup is only a fallback when the
    // writer has no total; a mismatch may be unrelated concurrent ledger activity.
    pointsTotal:lastOperationTotal??currentTotal,
    balanceConsistent:lastOperationTotal==null||currentTotal==null||lastOperationTotal===currentTotal,
    operations
  };
}
function serviceDisplayName(service={}){
  const name=String(service.name||service.service_name||'Service').trim()||'Service';
  const variant=String(service.variant_label||'').trim();
  const duration=Number(service.duration_min);
  const detail=variant||(duration>0?`${duration} min`:'');
  return detail?`${name} · ${detail}`:name;
}
/* V385 (owner markup, photo 2, arrow on Print receipt: "click but nothing happened").
   The button called window.print() directly. In an iOS home-screen web app — which is how the
   owner was running the till, and how a counter tablet is meant to run it — window.print() is a
   documented no-op: no dialog, no error, no console message. Nothing happened is exactly what
   it does there.
   So the standalone case takes the route that DOES work: the receipt is written into a new
   browsing context, which on iOS opens in Safari where printing is available. The in-page path
   is kept for every browser where it already worked, now inside a try/catch with a cleanup
   timer — an exception used to leave the page stuck in its print-only stylesheet. And when
   neither route is available the owner is TOLD, rather than shown a button that does nothing. */
/* V388: the receipt code, big enough to scan off a screen, with the PNG offered. Drawn fresh at
   320px rather than scaling the 132px receipt bitmap, because an upscaled QR loses the crispness
   a scanner needs. The download is built from the canvas the library produces — no network, no
   second encoder — and when the CDN never arrived the url is still shown as text, which is the
   thing that actually matters. */
function openWalletQrDialogV388(url,businessName){
  document.getElementById('walletQrModalV388')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="walletQrModalV388" role="dialog" aria-modal="true" aria-labelledby="walletQrTitleV388" tabindex="-1"><div class="modal-card" style="max-width:420px">
    <div class="row"><div><h2 id="walletQrTitleV388" style="font-size:16px">Customer rewards code</h2><p class="muted small" style="margin-top:4px">Scan to open rewards, points and past visits at <span data-merchant-content>${esc(businessName)}</span>.</p></div><span class="spacer"></span><button class="btn ghost sm" id="walletQrCloseV388" type="button">Close</button></div>
    <div id="walletQrHostV388" class="wallet-qr-host-v388" role="status">Drawing the code…</div>
    <p class="small" style="word-break:break-all;margin-top:10px"><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a></p>
    <div class="row" style="margin-top:14px;gap:8px"><button class="btn sm" id="walletQrSaveV388" type="button" disabled>Save image</button></div>
  </div></div>`);
  const modal=document.getElementById('walletQrModalV388');
  let deactivate;
  const close=()=>{if(deactivate)deactivate();else modal?.remove()};
  deactivate=CUI.activateDialog(modal,{onClose:close,initialFocus:'#walletQrCloseV388'});
  document.getElementById('walletQrCloseV388').onclick=close;
  const host=document.getElementById('walletQrHostV388'),save=document.getElementById('walletQrSaveV388');
  void loadQrLibrary().then(()=>{
    if(!host.isConnected)return;
    host.innerHTML='';
    new QRCode(host,{text:url,width:320,height:320,correctLevel:QRCode.CorrectLevel.M});
    /* qrcodejs paints a canvas and an <img> of it; either can produce the PNG, and which one is
       present depends on the browser. */
    const png=()=>{
      const canvas=host.querySelector('canvas');
      if(canvas)return canvas.toDataURL('image/png');
      return host.querySelector('img')?.src||'';
    };
    save.disabled=false;
    save.onclick=()=>{
      const data=png();
      if(!data)return toast('The image could not be saved. Screenshot the code instead.');
      const link=document.createElement('a');
      link.href=data;link.download=`${BRAND.downloadPrefix}-rewards-qr.png`;
      document.body.appendChild(link);link.click();link.remove();
    };
  }).catch(()=>{
    if(!host.isConnected)return;
    host.innerHTML='<p class="muted small">The code could not be drawn. Share the link below instead.</p>';
  });
}
const posReceiptStandaloneV385=()=>globalThis.navigator?.standalone===true
  ||globalThis.matchMedia?.('(display-mode: standalone)')?.matches===true;
function printPosReceiptV385(){
  const receipt=document.getElementById('posReceiptV142');
  if(!receipt)return toast('The receipt is no longer on screen.');
  if(posReceiptStandaloneV385()){
    let printWindow=null;
    try{printWindow=window.open('','_blank')}catch(error){printWindow=null}
    if(!printWindow)return toast('Open peekaa.asia in Safari to print this receipt.');
    /* Only the receipt's own markup travels, and it is written as a plain document with its own
       styles — the app's stylesheet is fingerprinted per deploy and this window must not depend
       on a url that changes. No script is written into the new document. */
    printWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Receipt</title>
      <meta name="viewport" content="width=device-width,initial-scale=1">
      <style>body{margin:0;padding:10mm;max-width:80mm;font:14px/1.45 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1b1b1b}
        .no-print{display:none}table{width:100%;border-collapse:collapse}img,canvas{max-width:100%}
        @media print{body{padding:4mm}}</style></head><body>${receipt.innerHTML}</body></html>`);
    printWindow.document.close();
    /* Give the written document — the wallet QR image in particular — a moment to lay out before
       the dialog freezes the page. focus() first, or Safari prints the opener on some versions. */
    setTimeout(()=>{try{printWindow.focus();printWindow.print()}catch(error){}},350);
    return;
  }
  document.body.classList.add('pos-receipt-print');
  const clear=()=>document.body.classList.remove('pos-receipt-print');
  window.addEventListener('afterprint',clear,{once:true});
  /* afterprint does not fire in every browser; the page must never be left print-only. */
  setTimeout(clear,60000);
  try{window.print()}catch(error){clear();toast('This browser could not open the print dialog.')}
}
/* nestly_v430 — the till's own unit noun. Every VALUE the counter shows was already pot-correct
   (the v155 lookup and v145's ask-the-server rule), but the labels hardcoded points: a stamps
   firm's counter read "764 pts" over 764 stamps, the receipt said "+6 points", and the voucher
   banner priced a stamp gift in points (go-live battery, 2026-08-22). One resolver, read off the
   same catalogue payload the v404 dialog already trusts; points wording is byte-identical to
   before for every points firm. */
function tillUnitNounV430(catalogRef,short){
  const stampsV430=catalogRef?.customerGiftsV392?.program?.unit==='stamps';
  return stampsV430?'stamps':(short?'pts':'points');
}
/* nestly_v474 (owner: "why it shows 15 stamps in record sale but customer view shows 5 out of 10
   stamps? it is way too messy. I need it to standardise").
   Both figures were true and neither was a bug — they are different QUANTITIES wearing the same
   word. The till printed the programme POT (every stamp ever earned minus redemptions); the
   customer's phone prints their position on THE CARD IN THEIR HAND. On the owner's own customer:
   pot 15, ten already consumed by a completed card, so five on a ten-slot card.
   The standard the owner asked for is the customer's card, because staff and customer talk across
   a counter and the number staff quote has to be the number on the phone being held up at them.
   v474 taught both staff reads to carry `stamp_card` beside the balance; this is the one place
   that turns it into words, so the till and the customer profile cannot word it differently.
   A points firm has no stamp_card and falls straight through to the balance it always printed —
   for points the pot IS what the customer sees, so there was never a discrepancy to fix. */
function stampCardStandingV474(card,balance,unitNoun){
  const slots=Math.max(0,Math.floor(Number(card?.slots)||0));
  if(!slots)return Number.isFinite(Number(balance))
    ?`${Number(balance).toLocaleString('en-SG')} ${unitNoun}`:'';
  const filled=Math.max(0,Math.min(slots,Math.floor(Number(card?.filled)||0)));
  /* The overflow is said out loud rather than dropped. A customer holding more than one card's
     worth is a real state — it is what their own app calls "N already counted toward your next
     card" — and staff who could not see it would be looking at a different truth again, which is
     the whole complaint. */
  const carried=Math.max(0,Math.floor(Number(card?.carried)||0));
  return `${filled} of ${slots} stamps${carried>0?` · ${carried.toLocaleString('en-SG')} toward the next card`:''}`;
}
/* nestly_v432 — the redeem-now list is grouped by WHERE each reward's eligibility comes from
   (owner ruling 2026-08-22: no hidden counter-only gifts; staff and Customer View read the same
   canonical availability, which the server now resolves in app.reward_availability_v432). The
   grouping is pure presentation: `source` arrives from the server per reward, this function only
   buckets and labels. A source this build does not know still renders — under a plain "Rewards"
   heading — because dropping a server-approved reward on the floor would be a second, client-side
   eligibility rule, which is exactly what v145 forbids. */
function groupRedeemableRewardsV432(rewards){
  const labels={stamp_card:'Stamp card',points:'Points'};
  const order=['stamp_card','points'];
  const groups=new Map();
  for(const reward of (Array.isArray(rewards)?rewards:[])){
    if(!reward)continue;
    const key=Object.prototype.hasOwnProperty.call(labels,reward.source)?reward.source:'other';
    if(!groups.has(key))groups.set(key,{source:key,label:labels[key]||'Rewards',rewards:[]});
    groups.get(key).rewards.push(reward);
  }
  return [...groups.values()].sort((a,b)=>{
    const ai=order.indexOf(a.source),bi=order.indexOf(b.source);
    return (ai<0?order.length:ai)-(bi<0?order.length:bi);
  });
}
async function tillPage(){
  const routeMain=M();
  const isTillCurrent=()=>routeMain.isConnected&&M()===routeMain;
  const canRecordSalesAtWorkspace=hasRoleCapability('create_sales')&&canReadModule('clients');
  if(!canRecordSalesAtWorkspace){
    routeMain.innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'Customer lookup and purchase recording are unavailable for this role.',iconName:'till',canWrite:false,moduleLabel:'Record sale'})}${CUI.card({title:'Additional access required',description:'Record sale requires customer read access and permission to record purchases.',body:'<p class="muted small">Ask an owner to review your Customers and Record sale assignments.</p>'})}`;
    return;
  }
  routeMain.innerHTML=CUI.loadingState({title:'Record sale',iconName:'till'});
  const [
    {data:tillStaff,error:tillStaffError},{data:tillBranches,error:tillBranchError},
    {data:tillStaffBranches,error:tillStaffBranchError},
    {data:merchantPaymentStatus,error:merchantPaymentStatusError}
  ]=await Promise.all([
    sb.from('staff').select('id,full_name,user_id').eq('business_id',S.biz.id).eq('active',true).order('full_name'),
    sb.from('branches').select('id,name,is_default').eq('business_id',S.biz.id).eq('active',true).order('name'),
    sb.from('staff_branches').select('staff_id,branch_id').eq('business_id',S.biz.id),
    sb.rpc('get_merchant_payment_status_v142',{p_business:S.biz.id})
  ]);
  if(!isTillCurrent())return;
  if(tillStaffError||tillBranchError||tillStaffBranchError)throw tillStaffError||tillBranchError||tillStaffBranchError;
  /* V187 (owner: "under record sale - i must be able to select who is the sales staff to allocate
     commissions"). Every sale was attributed to whoever was signed in, so at a salon the
     receptionist ringing up a therapist's treatment took the commission. Attribution drives the
     frozen per-sale commission snapshot, so this is money, not a label.
     The acting user stays the DEFAULT — correct for a one-person shop and for F&B — and the
     picker only appears when more than one teammate could have done the work, so it configures
     itself by sector instead of needing a setting. */
  const tillRoster=(tillStaff||[]);
  const tillActingStaffId=tillRoster.find(person=>person.user_id===S.user.id)?.id||null;
  const tillStaffId=tillActingStaffId;
  let tillSaleStaffId=tillActingStaffId;
  /* Only teammates who actually work this branch can be credited; an owner or manager may
     attribute across branches because they legitimately cover more than one. */
  const tillAttributableStaffFor=branchId=>tillRoster.filter(person=>
    canSeeAllTillBranches
    ||person.id===tillActingStaffId
    ||(tillStaffBranches||[]).some(row=>row.staff_id===person.id&&row.branch_id===branchId));
  const canSeeAllTillBranches=S.myRole==='owner'||S.myRole==='manager';
  const tillAssignedBranchIds=new Set((tillStaffBranches||[]).filter(row=>row.staff_id===tillStaffId).map(row=>row.branch_id));
  const assignedTillBranches=(tillBranches||[]).filter(branch=>canSeeAllTillBranches||tillAssignedBranchIds.has(branch.id));
  const branchModuleResults=await Promise.all(assignedTillBranches.map(async branch=>{
    const result=await sb.rpc('get_my_modules_at_v115',{
      p_business:S.biz.id,p_branch:branch.id
    });
    return {branch,result};
  }));
  if(!isTillCurrent())return;
  const branchModuleFailure=branchModuleResults.find(item=>item.result.error||!item.result.data);
  if(branchModuleFailure){
    routeMain.innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'Branch access could not be checked safely.',iconName:'till',canWrite:false,moduleLabel:'Record sale'})}${CUI.card({title:'Record sale could not be loaded',description:'No purchase, redemption, or package use was recorded.',body:'<button type="button" class="btn ghost" id="tBranchModulesRetry">Try again</button>'})}`;
    $('tBranchModulesRetry').onclick=tillPage;
    return;
  }
  const branchModulePermsById=new Map(branchModuleResults.map(({branch,result})=>[
    branch.id,result.data.module_perms&&typeof result.data.module_perms==='object'
      ?result.data.module_perms:{}
  ]));
  const branchCanRead=(branchId,module)=>['r','rw'].includes(branchModulePermsById.get(branchId)?.[module]);
  const branchCanWrite=(branchId,module)=>branchModulePermsById.get(branchId)?.[module]==='rw';
  const canAddClient=()=>branchCanWrite(tillBranchId,'clients');
  const accessibleTillBranches=assignedTillBranches.filter(branch=>
    branchCanWrite(branch.id,'till')&&branchCanRead(branch.id,'clients')
  );
  let tillBranchId=accessibleTillBranches.some(branch=>branch.id===selectedBranchId)?selectedBranchId:
    (accessibleTillBranches.find(branch=>branch.is_default)?.id||accessibleTillBranches[0]?.id||'');
  const canRecordSales=hasRoleCapability('create_sales')&&Boolean(tillBranchId);
  const verifiedPaynowReady=!merchantPaymentStatusError&&merchantPaymentStatus?.paynow_ready===true;
  const legacyTenderOptions=[['cash','Cash'],['card','Card'],['paynow','External PayNow'],['other','Other']];
  const cartTenderOptions=[['cash','Cash'],['card','Card'],
    ...(verifiedPaynowReady?[['paynow_qr','PayNow QR']]:[]),['paynow','External PayNow'],['other','Other']];
  const canScanRedemption=()=>canScanCustomerRedemption({
    createSales:hasRoleCapability('create_sales'),
    clientsReadable:branchCanRead(tillBranchId,'clients'),
    loyaltyWritable:branchCanWrite(tillBranchId,'loyalty')
  });
  if(!tillStaffId||!tillBranchId){
    routeMain.innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'A staff identity and branch with Record sale access are required before taking payment.',iconName:'till',canWrite:false,moduleLabel:'Record sale'})}${CUI.card({title:'Record sale is not available',description:'Ask an owner or Peekaa administrator to review this staff member and branch module policy.',body:'<p class="muted small">No purchase, redemption, or package use was recorded.</p>'})}`;
    return;
  }
  selectedBranchId=tillBranchId;
  typeof recordProductInteractionV100==='function'&&recordProductInteractionV100('merchant.counter_action_opened',S.biz.id,{
    branchId:tillBranchId,
    context:{action_key:'quick_earn',entry_point:'workspace_route',locale:workspaceLocale,surface_version:'v100'}
  });
  let step=1;             // 1=enter number, 2=customer card / new customer / invalid, 3=done
  let phone='';           // digits typed so far in step 1
  let cust=null;          // lookup_client_by_phone result once status==='found'
  let walkin=false;       // v170 walk-in sale: NO customer is linked. `cust` stays null and every
                           // customer-bound control (redemption, packages, memberships, stored value,
                           // PayNow QR) is HIDDEN. evaluate_checkout / record_cart_sale both accept a
                           // null p_client and return points_earned 0 (verified against prod 2026-08-06).
  let notFoundPhone=null; // normalised 8-digit phone when status==='not_found'
  let invalidMsg=null;    // message when status==='invalid'
  let saleIdem=null;      // idempotency key for the CURRENT sale attempt — one fresh
                           // crypto.randomUUID() per sale, reused across retries of that
                           // same sale so a double-tap can never earn points twice; a new
                           // key is only minted when a new sale starts (resetToStart / back).
  let busy=false;         // guards Find/Confirm while a request is in flight
  let doneInfo=null;      // {name, pointsEarned, pointsTotal, duplicate} for step 3
  let quickAddIdem=null;   // stable while retrying one Till customer creation
  let tender=null;         // intentionally selected received tender for this purchase

  /* Catalogue-first is the firm-level Record sale policy. The business row is selected with `*`,
     so the UI consumes the optional backend setting without a second request. Missing/true means
     catalogue-first; only an explicit false enables the legacy amount-only flow. This keeps new
     firms on itemized sales while allowing the platform backend to disable it per firm. */
  let catalogueSelectionEnabled=S.biz.quick_earn_catalogue_enabled!==false;
  let cart=[];            // lines: {lineId,type:'service'|'product'|'custom'|'package'|'membership',ref,label,unit_cents,qty,reason?,key?}
                           // service/product/custom = evaluated by evaluate_checkout, then finalised by ONE record_cart_sale (PS-1C.1);
                           // custom carries a mandatory staff `reason`; giftcard/package/membership = each its own server-idempotent RPC per line.
  let catalog=null;       // catalogue + customer package/voucher entitlements, loaded together
  let catalogLoading=false, catalogError=null;
  /* V373: Record sale is ONE flow with two stages — 'items' (who this is, what they had, what
     they can be given now) and 'review' (the server-priced bill, how they paid, one confirm).
     A cart in recovery is always on 'review'; see drawCartComposer. */
  let tillStageV373='items';
  /* V374 (owner: "now renders Services, Products, Packages and all Diamond benefits vertically
     on one page, causing endless scrolling"). V373 removed the three transaction MODES but left
     their three sections stacked. They are now three tabs, and only the selected one renders. */
  let tillItemsTabV374='items';   // 'items' | 'packages' | 'benefits'
  /* V404: manual-redemption quantity, per reward, for THIS customer's till session. Reset
     wherever the cart's own per-customer state is reset, so one customer's 3 can never be
     carried into the next customer's screen. */
  let tillManualQtyV404={};
  /* V373 retires V257's "Sell package" <details> drawer. That drawer existed to keep package
     SALES off the main screen, and it had to remember its own open state because adding a line
     redrew the panel underneath it and collapsed it. The Add item sheet keeps both promises
     structurally: it is a dialog mounted on document.body, so the redraw that follows every add
     cannot close it, and it remembers which tab is open. */
  let tillAddSheetV373=null;     // null | {tab:'services'|'products'|'usepackage'|'sellpackage'|'membership'|'custom',query:string}
  let tillWhoOpenV373=false;     // the branch/teammate disclosure survives a redraw for the same reason
  const TILL_QUICK_ITEMS_V373=8; // tiles on the main screen; everything else is one tap away in the sheet
  /* V392: how many of the customer's most recent items lead the grid, per kind (owner: "latest 2
     services & products"). Everything else stays one tap away in More items, or one type away in
     the search field beside it. */
  const TILL_RECENT_PER_KIND_V392=2;
  let tillItemSearchV392='';
  const packageUseAttemptsV102=new Map(); // client-package + branch -> stable key until confirmed success
  let saleCommitted=false, saleResult=null; // once the cart sale succeeds it is LOCKED; a retry never
                                             // re-runs it, only the failed gift/package/membership calls.
  let checkoutError=null;  // extras partial-failure banner state (kernel already committed)
  /* ---- PS-1C.1 unified checkout kernel state (two-step: EVALUATE -> FINALISE) ----
     evaluate_checkout is the sole pricing authority; the panel below NEVER computes a payable
     figure or a discount locally. All payable money is copied verbatim from the evaluation. */
  let evalState='idle';    // 'idle'|'evaluating'|'ready'|'expired'|'error'  (drives the checkout panel)
  let evalResult=null;     // authoritative response {evaluation_id,expires_at,server_lines,applied_effects,subtotal_cents,discount_total_cents,total_cents,gst_cents}
  let evalError=null;      // {kind:'zero'|'perm'|'custom'|'generic', message} — evaluate/typed errors; cart stays EDITABLE (fix by changing the cart)
  let evalSeq=0;           // monotonic guard: only the newest evaluate response is applied
  let evalTimer=null;      // debounce handle for re-evaluate on a sale-line change
  let evalExpiryTimer=null;// one-shot handle: flips 'ready'->'expired' when expires_at passes
  let staleConfirm=false;  // after an auto re-evaluate at finalise: "please confirm the new total" (LOCKS the cart)
  /* V257: how many times THIS cart has been re-evaluated because the finalise came back stale.
     The recovery was written for a one-off drift ("the price moved while you were ringing it up"),
     and it re-offered the identical confirm button after every stale. When the stale cause is
     permanent, that redraws the same screen forever — which is exactly what "Price updated —
     please confirm the new total" and a Confirm button that does nothing looked like. */
  let staleReevaluationsV257=0;
  let payError=null;       // {kind:'retry'|'conflict'} — finalise failure (LOCKS the cart so the same idempotency key is reused)
  let paynowAttempt=null;  // V142 provider-backed attempt; while present the cart and amount stay locked
  let paynowPollTimer=null;
  const PAYNOW_SLOT=`peekaa:v142:paynow:${S.biz.id}`;
  // v67 stored-value tender: reserve_checkout_sv_tender result bound to the CURRENT evaluation token.
  // Structurally never offered in prod (the server reports stored_value.spendable=false). All figures
  // (available/reserved/remaining) are server-authoritative; the client computes nothing. A new
  // evaluation (fresh token) always clears this so a stale tender can never ride a re-priced cart.
  let svTender=null;       // null | {reservation_id,reserved_cents,remaining_due_cents,requested_cents}
  let svBusy=false;
  const FINALISE_SLOT='frenly.till.cartFinalise'; // sessionStorage slot for the STABLE finalise idempotency key (writeAttemptKey pattern, F2)
  // The cart is LOCKED (no picker, qty or remove) whenever a finalise is mid-recovery or extras are pending,
  // so a retry reuses the same idempotency key instead of minting a fresh one and double-charging.
  const cartLocked=()=>!!(checkoutError||staleConfirm||payError||paynowAttempt);
  // A cart-sale line (service/product/custom) is priced by evaluate_checkout and finalised by ONE record_cart_sale;
  // everything else (package/membership) is an "extra" line with its own idempotency key + RPC.
  const isCartSaleLine=l=>l.type==='service'||l.type==='product'||l.type==='custom'||l.type==='bundle';
  // Backend not yet on the kernel: evaluate_checkout / record_cart_sale absent (undefined_function
  // 42883, or PostgREST 404 / PGRST202). Detect so checkout can say "update needed", never fall back.
  const isBackendMissing=err=>!!err&&(err.code==='42883'||err.code==='PGRST202'||err.status===404
    ||/Could not find the function|does not exist/i.test(err.message||''));

  /* Wipe every trace of a checkout attempt: timers, the evaluation, and the STABLE finalise key.
     Called on reset, on Back, and when toggling modes — a deliberate cancel per §2. */
  /* V286: `abandon` marks a DELIBERATE end of this checkout (Back, reset, walk-in switch, branch
     change, finalise). Dropping paynowAttempt alone killed the poll and the on-screen attempt but
     left the sessionStorage PayNow request behind, so the next entry to Record sale resumed it —
     re-creating the earlier customer's QR against an unrelated sale. A deliberate abandon drops the
     stored request too. There is no provider cancel API (stripe-connect-command exposes only
     create_paynow), so a LIVE attempt is never abandoned silently: backToPhoneStep refuses while
     one is outstanding, and the branch picker is disabled by cartLocked(). */
  function clearCheckoutState({abandon=false}={}){
    if(evalTimer){clearTimeout(evalTimer);evalTimer=null;}
    if(evalExpiryTimer){clearTimeout(evalExpiryTimer);evalExpiryTimer=null;}
    if(paynowPollTimer){clearTimeout(paynowPollTimer);paynowPollTimer=null;}
    evalState='idle';evalResult=null;evalError=null;staleConfirm=false;staleReevaluationsV257=0;payError=null;svTender=null;svBusy=false;paynowAttempt=null;
    if(abandon)clearPaynowRequestV142();
    clearWriteAttempt(FINALISE_SLOT);
  }
  function resetToStart(){
    clearCheckoutState({abandon:true});
    /* v281 audit: the catalogue snapshot carries the LOOKED-UP CUSTOMER's entitlements
       (packages, vouchers, welcome offer) alongside the branch items. Dropping it only for
       walk-ins meant serving customer A and then customer B offered B customer A's packages —
       and could consume A's sessions on B's sale. Every return to the phone step now drops the
       whole snapshot; the branch items refetch is cheap next to a wrong redemption. */
    catalog=null;catalogError=null;tillItemSearchV392='';
    step=1;phone='';cust=null;walkin=false;notFoundPhone=null;invalidMsg=null;saleIdem=null;quickAddIdem=null;tender=null;busy=false;doneInfo=null;
    cart=[];saleCommitted=false;saleResult=null;checkoutError=null;tillStageV373='items';tillItemsTabV374='items';tillManualQtyV404={};draw();
  }
  /* Leave the cart step and go back to the phone keypad. Same discard-the-cart behaviour the
     "Different number" button always had; it additionally clears the walk-in flag and, when the
     cart was a walk-in, the customer-less catalogue snapshot. */
  function backToPhoneStep(){
    if(checkoutError){toast('Finish or retry the unfinished items first');return}
    /* V286: Back used to abandon a live PayNow QR — the poll died, the attempt vanished from the
       screen, and the customer still paid a sale the server then fulfilled, so the cashier took the
       money twice. Nothing can cancel a Stripe PayNow attempt from here, so the only honest answer
       is to refuse and keep the attempt (and its "Show QR" button) on screen until it settles. */
    if(paynowAttempt){toast('A PayNow payment is still being confirmed — wait for it to complete or expire first');return}
    clearCheckoutState({abandon:true});
    catalog=null;catalogError=null;tillItemSearchV392=''; // v281 audit: see resetToStart — the snapshot is per-customer
    step=1;cust=null;walkin=false;saleIdem=null;tender=null;cart=[];tillStageV373='items';tillItemsTabV374='items';tillManualQtyV404={};draw();
  }
  function draw(){
    /* V373: the Add item sheet and the review stage belong to the cart step alone. Anything that
       leaves that step (a new lookup, a completed sale, a reset) drops both, so a sheet can never
       be left floating over the keypad or a receipt. */
    if(step!==2){if(tillAddSheetV373)closeTillAddSheetV373();tillStageV373='items';tillItemsTabV374='items';}
    if(step===1) return drawStep1();
    if(step===2) return drawStep2();
    return drawStep3();
  }
  /* Walk-in is offered only where it can actually complete: the staff member may record sales,
     the firm is on itemized (catalogue) checkout — the legacy amount-only flow charges by PHONE
     (record_sale_by_phone) and has no customer-less path — and the till was NOT opened to run a
     customer redemption scan, which by definition needs a customer. */
  const canOfferWalkin=()=>canRecordSales&&catalogueSelectionEnabled&&!pendingTillRedemptionScan;
  function startWalkinSale(){
    if(!canOfferWalkin())return;
    clearCheckoutState({abandon:true}); // V286: switching to a walk-in abandons any stored PayNow request
    cust=null;notFoundPhone=null;invalidMsg=null;quickAddIdem=null;saleIdem=null;tender=null;
    cart=[];saleCommitted=false;saleResult=null;checkoutError=null;
    catalog=null;catalogError=null;tillItemSearchV392=''; // V392: a leftover query would hide the next customer's items
    walkin=true;step=2;tillStageV373='items';tillItemsTabV374='items';tillManualQtyV404={};
    CUI.announce('Walk-in sale started. No customer is linked.');
    draw();
  }

  function drawStep1(){
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:canScanRedemption()?"Type the customer's phone number, or scan a redemption QR.":"Type the customer's phone number to record a purchase.",iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale',actions:`${canScanRedemption()?CUI.action({id:'tScanRedemption',label:'Scan customer QR',iconName:'scan',variant:'secondary'}):''}${canReadModule('sales')?CUI.action({id:'tViewSalesHistoryV253',label:'View sales history',iconName:'sales',variant:'secondary'}):''}`})}
      <div class="card frontline-card" style="text-align:center">
        <label class="sr-only" for="tPhone">Customer phone number</label>
        <input id="tPhone" class="frontline-phone" inputmode="numeric" autocomplete="tel-national" maxlength="8" placeholder="···· ····" value="${esc(phone)}">
        <div id="tErr"></div>
        <button class="btn" id="tFind" style="width:100%;margin-top:14px;padding:16px;font-size:17px">${CUI.icon('forward',{size:20})} Next</button>
        <div class="grid frontline-keypad" id="tKeys" aria-label="Phone keypad">
          ${['1','2','3','4','5','6','7','8','9','⌫','0','✕'].map(k=>`<button class="btn ghost" data-k="${k}" ${workspaceTemplateAttributeV97('aria-label',k==='⌫'?'phoneKeyDelete':k==='✕'?'phoneKeyClear':'phoneKeyDigit',k==='⌫'||k==='✕'?{}:{digit:k})}>${k}</button>`).join('')}
        </div>
        <p class="muted small" style="margin-top:14px">⌫ deletes one digit · ✕ clears</p>
        ${canOfferWalkin()?`<hr style="border:none;border-top:1px solid var(--line);margin:14px 0">
        <button class="btn ghost sm" id="tWalkin" style="width:100%;padding:12px">${CUI.icon('till',{size:16})} Walk-in sale</button>
        <p class="muted small" style="margin:6px 0 0">No points, rewards, packages or stored value.</p>`:''}
        ${canScanRedemption()?'':'<p class="muted small">Redemption scanning requires Loyalty write access at this branch.</p>'}
      </div>`;
    const inp=$('tPhone');
    inp.focus();
    inp.oninput=()=>{phone=inp.value.replace(/\D/g,'').slice(0,8);inp.value=phone};
    inp.onkeydown=(e)=>{if(e.key==='Enter') doFind();};
    $('tFind').onclick=doFind;
    if(canScanRedemption())$('tScanRedemption').onclick=()=>openMerchantRedemptionScanner({
      businessId:S.biz.id,branchId:tillBranchId,
      isCurrent:isTillCurrent,onComplete:()=>resetToStart(),
      /* v327: a scanned Peekaa member QR resolves straight into the same customer-card step a
         phone lookup would (cust=the RPC's response — same shape as lookup_client_by_phone),
         skipping the phone keypad entirely. */
      onMemberResolved:data=>{cust=data;walkin=false;notFoundPhone=null;invalidMsg=null;step=2;draw();}
    });
    if(canReadModule('sales')&&$('tViewSalesHistoryV253'))$('tViewSalesHistoryV253').onclick=()=>nav('#/sales');
    if($('tWalkin'))$('tWalkin').onclick=startWalkinSale;
    document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{
      const k=b.dataset.k;
      if(k==='⌫') phone=phone.slice(0,-1);
      else if(k==='✕') phone='';
      else if(phone.length<8) phone+=k;
      inp.value=phone;inp.focus();
    });
  }
  async function doFind(){
    if(busy) return;
    if(!phone){$('tErr').innerHTML='<div class="err">Enter a phone number</div>';return}
    typeof recordProductInteractionV100==='function'&&recordProductInteractionV100('merchant.counter_action_started',S.biz.id,{
      branchId:tillBranchId,
      context:{action_key:'customer_lookup',entry_point:'quick_earn',locale:workspaceLocale,surface_version:'v100'}
    });
    busy=true;$('tFind').disabled=true;$('tFind').textContent='Looking…';
    const {data,error}=await sb.rpc('lookup_client_by_phone',{p_business:S.biz.id,p_phone:phone});
    if(!isTillCurrent())return;
    busy=false;$('tFind').disabled=false;$('tFind').innerHTML=`${CUI.icon('forward',{size:20})} Next`;
    if(error) return fail(error);
    if(data.status==='found'){cust=data;notFoundPhone=null;invalidMsg=null;step=2;draw();return}
    if(data.status==='not_found'){cust=null;notFoundPhone=data.phone;invalidMsg=null;quickAddIdem=crypto.randomUUID();step=2;draw();return}
    if(data.status==='invalid'){invalidMsg=data.message||'Enter a valid Singapore number';step=2;draw();return}
  }

  function drawStep2(){
    if(invalidMsg) return drawInvalid();
    // Walk-in comes BEFORE the !cust branch: there is deliberately no customer to add.
    if(walkin) return catalogueSelectionEnabled?drawCartComposer():drawWalkinUnavailable();
    if(!cust) return drawNewCustomer();
    return catalogueSelectionEnabled?drawCartComposer():drawCustomerCard();
  }
  /* Only reachable if the backend disables itemized checkout while a walk-in cart is open
     (loadCatalog flips catalogueSelectionEnabled). The legacy flow charges by phone, so there is
     no walk-in path — say so and send the cashier back rather than render a customer-less card. */
  function drawWalkinUnavailable(){
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'Walk-in sales need itemized checkout.',iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card" style="text-align:center">
        ${CUI.icon('info',{size:32})}
        <h2 style="margin:8px 0 2px">Walk-in is not available</h2>
        <p class="muted small">This firm records sales by customer phone number. Nothing was charged.</p>
        <button class="btn ghost sm" id="tBack" style="width:100%;margin-top:14px">${CUI.icon('back',{size:16})} Back to phone number</button>
      </div>`;
    $('tBack').onclick=backToPhoneStep;
  }
  function drawInvalid(){
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'The phone number could not be used.',iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card" style="text-align:center">
        ${CUI.icon('info',{size:32})}
        <div class="err" style="margin-top:10px">${esc(invalidMsg)}</div>
        <button class="btn ghost sm" id="tBack" style="margin-top:14px">${CUI.icon('back',{size:16})} Try another number</button>
      </div>`;
    $('tBack').onclick=()=>{invalidMsg=null;step=1;draw()};
  }
  function drawNewCustomer(){
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'This number is new. Add the customer once, then continue.',iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card" style="text-align:center">
        ${CUI.icon('customers',{size:32})}
        <h2 style="margin:8px 0 2px">New customer</h2>
        <p class="muted small"><span data-merchant-content>${esc(notFoundPhone||phone)}</span> <span data-workspace-i18n>isn't in your system yet</span></p>
        <div style="text-align:left"><label for="tName">Name</label><input id="tName" placeholder="Customer's name">
        <label style="display:flex;align-items:center;gap:8px;margin-top:14px;cursor:pointer;color:var(--ink);font-weight:500;font-size:14px">
          <input type="checkbox" id="tConsent" style="width:auto"> Marketing consent given</label></div>
        <div id="tErr2"></div>
        ${canAddClient()?'<button class="btn" id="tAdd" style="width:100%;margin-top:16px;padding:16px;font-size:16px">Add & continue</button>':'<div class="err">Customer creation is read only at this branch.</div>'}
        <button class="btn ghost sm" id="tBack" style="width:100%;margin-top:10px">${CUI.icon('back',{size:16})} Different number</button>
      </div>`;
    $('tBack').onclick=()=>{quickAddIdem=null;step=1;draw()};
    if($('tAdd'))$('tAdd').onclick=async()=>{
      if(busy) return;
      const name=$('tName').value.trim();
      if(name.length<2){$('tErr2').innerHTML='<div class="err">Enter a name</div>';return}
      busy=true;$('tAdd').disabled=true;
      if(!quickAddIdem) quickAddIdem=crypto.randomUUID();
      const {data,error}=await sb.rpc('staff_create_client',{p_business:S.biz.id,p_idempotency_key:quickAddIdem,
        p_phone:notFoundPhone||phone,p_full_name:name,p_marketing_consent:$('tConsent').checked,
        p_source:'till quick add'});
      if(!isTillCurrent())return;
      if(error){busy=false;$('tAdd').disabled=false;$('tErr2').innerHTML=`<div class="err">${esc(humanErrorV295(error))}</div>`;return}
      const {data:lk,error:lkErr}=await sb.rpc('lookup_client_by_phone',{p_business:S.biz.id,p_phone:notFoundPhone||phone});
      if(!isTillCurrent())return;
      busy=false;
      if(lkErr||!lk||lk.status!=='found'){$('tAdd').disabled=false;fail(lkErr||new Error('Customer added, but could not load their card — press Find again'));return}
      toast(data.status==='completed'?'Customer added ✓':'Customer found ✓');
      cust=lk;step=2;draw();
    };
  }
  function drawCustomerCard(){
    const tillAttributableStaff=tillAttributableStaffFor(tillBranchId);
    if(!tillAttributableStaff.some(person=>person.id===tillSaleStaffId))tillSaleStaffId=tillActingStaffId;
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:`Itemized catalogue selection is off for this firm. Confirm the amount paid and payment method; ${BRAND.productName} records the purchase and applies points only when an active published loyalty programme makes it eligible.`,iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card">
        <div style="text-align:center">
          <div data-merchant-content style="font-size:1.9rem;font-weight:700;letter-spacing:-.035em">${esc(cust.full_name)}</div>
          <p class="muted small" data-merchant-content>${esc(cust.phone||'')}</p>
          <p class="inline-status" style="justify-content:center;margin-top:9px;color:var(--green)">${CUI.icon('check',{size:16})}<span>Customer found</span></p>
        </div>
        <hr style="border:none;border-top:1px solid var(--line);margin:18px 0">
        ${canRecordSales?`${accessibleTillBranches.length>1
          ?`<label for="tBranch">Branch</label><select id="tBranch">${accessibleTillBranches.map(branch=>`<option value="${branch.id}" ${branch.id===tillBranchId?'selected':''}>${esc(branch.name)}</option>`).join('')}</select>`
          :`<p class="muted small" style="margin-bottom:12px"><b>Branch:</b> <span data-merchant-content>${esc(accessibleTillBranches[0].name)}</span></p>`}
        ${tillAttributableStaff.length>1?`<label for="tillSaleStaff">Who made this sale?</label>
        <select id="tillSaleStaff" style="margin-bottom:12px">${tillAttributableStaff.map(person=>`<option value="${esc(person.id)}" ${person.id===tillSaleStaffId?'selected':''} data-merchant-content>${esc(person.full_name||'Team member')}${person.id===tillActingStaffId?' (you)':''}</option>`).join('')}</select>
        <p class="muted small" style="margin:-6px 0 12px">Commission for this sale is recorded against this teammate.</p>`:''}
        <label for="tAmt">Amount paid (${S.biz.currency||'SGD'})</label>
        <input id="tAmt" inputmode="decimal" placeholder="0.00" style="font-size:28px;text-align:center;height:56px">
        <fieldset style="border:0;padding:0;margin:16px 0 0"><legend style="font-size:13px;font-weight:700">Payment received</legend>
          <div class="frontline-tenders" id="tTenders">
            ${legacyTenderOptions.map(([value,label])=>`<button type="button" class="btn ghost" data-tender="${value}" aria-pressed="${tender===value}">${label}</button>`).join('')}
          </div>
        </fieldset>
        <div id="tErr3"></div>
        <button class="btn" id="tConfirm" style="width:100%;margin-top:14px;padding:18px;font-size:18px">${CUI.icon('check',{size:20})} Record sale</button>`:'<div class="permission-banner" role="note">Purchases cannot be recorded by this role.</div>'}
        <button class="btn ghost sm" id="tBack" style="width:100%;margin-top:10px">${CUI.icon('back',{size:16})} Different number</button>
      </div>`;
    $('tBack').onclick=()=>{step=1;cust=null;saleIdem=null;draw()};
    if($('tBranch'))$('tBranch').onchange=()=>{tillBranchId=$('tBranch').value;selectedBranchId=tillBranchId;saleIdem=null};
    document.querySelectorAll('[data-tender]').forEach(button=>button.onclick=()=>{
      tender=button.dataset.tender;saleIdem=null;
      document.querySelectorAll('[data-tender]').forEach(choice=>choice.setAttribute('aria-pressed',String(choice===button)));
      CUI.announce(workspaceTemplateTextV97('itemSelected',{item:button.textContent.trim()}));
    });
    /* Re-attributing is a different sale: drop the idempotency key so the next confirm is a
       fresh attempt rather than a replay of the previous teammate's sale. */
    if($('tillSaleStaff'))$('tillSaleStaff').onchange=event=>{
      tillSaleStaffId=event.target.value||tillActingStaffId;saleIdem=null;
    };
    if($('tAmt')){$('tAmt').focus();$('tAmt').oninput=()=>{saleIdem=null}};
    if($('tAmt'))$('tAmt').onkeydown=e=>{if(e.key==='Enter')$('tConfirm')?.click()};
    if($('tConfirm'))$('tConfirm').onclick=async()=>{
      if(busy) return;
      const rawAmount=$('tAmt').value.trim();
      if(!/^\d+(?:\.\d{1,2})?$/.test(rawAmount)){$('tErr3').innerHTML='<div class="err">Enter dollars and cents, for example 12.50</div>';return}
      const amt=Math.round(Number(rawAmount)*100);
      if(!(amt>0)||amt>2147483647){$('tErr3').innerHTML='<div class="err">Enter an amount between 0.01 and 21,474,836.47</div>';return}
      if(!tender){$('tErr3').innerHTML='<div class="err">Choose how the customer paid</div>';return}
      if(!saleIdem) saleIdem=crypto.randomUUID(); // fresh key for this sale; reused on retry
      busy=true;$('tConfirm').disabled=true;$('tConfirm').textContent='Recording…';
      const {data,error}=await sb.rpc('record_sale_by_phone',{p_business:S.biz.id,p_phone:cust.phone||phone,
        p_amount_cents:amt,p_kind:'quick_sale',p_note:null,p_staff:tillSaleStaffId||tillStaffId,p_idem:saleIdem,
        p_branch:tillBranchId,p_method:tender});
      if(!isTillCurrent())return;
      busy=false;
      if(error){$('tConfirm').disabled=false;$('tConfirm').textContent='Record sale';return fail(error)}
      doneInfo=(data.status==='duplicate_ignored')
        ?{name:data.full_name,pointsEarned:0,pointsTotal:data.points,method:data.payment_method,duplicate:true,saleId:data.sale_id||null}
        :{name:data.full_name,pointsEarned:data.points_earned||0,pointsTotal:data.points,method:data.payment_method,duplicate:false,saleId:data.sale_id||null};
      step=3;draw();
    };
  }

  /* ---- catalogue-first checkout: compose an itemized sale from the firm's existing list ----
     Honest write-path map (verified against the v51 migrations, LIVE):
       • service / retail / custom lines -> ONE public.record_cart_sale carrying real line items
         (public.sale_items). That parent row is a kind='quick_sale' via record_quick_sale, so it
         keeps the exact points/retention/referral firing and the reserve->complete idempotency of
         the till today. A single-retail cart FEFO-deducts stock server-side; multi-retail does not.
       • gift cards -> issue_gift_card (unchanged), one call per line, AFTER the sale.
       • packages -> sell_package_v102(…,p_branch,p_idempotency_key) with an authoritative receipt; memberships ->
         enroll_membership_v41(…,p_idempotency_key uuid) 4-arg overload. Both are now server-
         idempotent (v51a keyed ledger), so they are admitted as their own per-line calls exactly
         like gift cards — NEVER as record_cart_sale line items (the engine treats those item_types
         as descriptive; the real package/membership sale rows come only from the overloads). */
  async function loadCatalog(){
    if(catalog||catalogLoading) return;
    catalogLoading=true;catalogError=null;
    /* V286: the ONE async path on this surface with no epoch guard. Switching branch (or customer)
       while this fetch is in flight cleared catalog, but the redraw's loadCatalog() bounced off
       catalogLoading — so when the old response landed it published the PREVIOUS branch's services,
       products and the previous customer's entitlements under the new label, and nothing refetched.
       Staff could then tap items business_get_checkout_catalogue_v94 deliberately withheld, and
       evaluate_checkout rejected the sale with a generic price-check error. Capture what this fetch
       is for and discard it if either changed; the bail redraws, and drawCartComposer's
       `catalog===null` re-issues the load for the branch actually on screen. */
    const forBranchV286=tillBranchId, forClientV286=cust?cust.client_id:null, forWalkinV286=walkin;
    // A walk-in has no customer, so no plan can be sold to one and no entitlement can exist.
    const wantPackages=branchCanWrite(tillBranchId,'packages')&&!walkin;
    const wantMemberships=branchCanWrite(tillBranchId,'memberships')&&!walkin;
    const [checkout,pkg,mem,preferences,entitlements,serviceMeta,bundleRows,tierBenefitsV365,giftCatalogueV392,recentItemsV392]=await Promise.all([
      /* Server returns only checkout-active items effective at this branch. In particular,
         services configured in service_branches must include p_branch; the browser never
         reconstructs or broadens that availability rule. */
      sb.rpc('business_get_checkout_catalogue_v94',{
        p_business:S.biz.id,p_branch:tillBranchId,p_include_inactive:false
      }),
      wantPackages?sb.from('package_plans').select('id,name,price_cents,active').eq('business_id',S.biz.id).eq('active',true).order('name')
        :Promise.resolve({data:null,error:null}),
      wantMemberships?sb.from('membership_plans').select('id,name,price_cents,cadence,active').eq('business_id',S.biz.id).eq('active',true).order('name')
        :Promise.resolve({data:null,error:null}),
      sb.rpc('business_get_checkout_preferences_v102',{p_business:S.biz.id}),
      walkin?Promise.resolve({data:null,error:null}):sb.rpc('staff_get_customer_entitlements_v102',{
        p_business:S.biz.id,p_client:cust.client_id
      }),
      sb.from('services').select('id,name,variant_label,duration_min')
        .eq('business_id',S.biz.id),
      /* v187: bundles were authorable but unsellable. Read the bundle and its member services
         here; which of those services may actually be sold at THIS branch is still decided by
         the checkout catalogue above, never by this list. */
      sb.from('bundles').select('id,name,price_cents,active,bundle_items(service_id,product_id)')
        .eq('business_id',S.biz.id).eq('active',true).order('name'),
      /* V365 (owner, photo 4: "there must be a qrcode for merchant to scan and issue the
         rewards"). The scan already exists — "Scan customer QR" resolves the member code to this
         client (staff_scan_member_qr_v327) — so what was missing was the thing to issue at the
         end of it. This read answers "what is this customer's tier entitled to, and how much of
         it is left in the current period", and rides the same load as the entitlements above for
         the same reason they do: one round trip per looked-up customer.
         Fail-soft: a database without the v365 migration simply yields no panel. */
      walkin?Promise.resolve({data:null,error:null}):sb.rpc('staff_tier_benefits_for_client_v365',{
        p_business:S.biz.id,p_client:cust.client_id
      }),
      /* V392 (owner, photo 1: "only show latest 2 services & products for specified customer").
         What THIS customer had last is a far better guess than the top of the catalogue, and the
         counter is usually repeating a regular's usual. Rides this same load — one round trip per
         looked-up customer, exactly as the entitlements and tier benefits above do.
         An inner join on sales is what scopes these lines to this customer; RLS still decides
         which sales are visible at all. Fail-soft: no history simply means no preference, and the
         grid falls back to the catalogue order it has always used. */
      /* V392 (owner, photo 2: "need to show available rewards" ringed over "Nothing to give on
         this sale" — for a customer holding 75,907 points). The Benefits tab listed vouchers
         already ISSUED, tier benefits and the two one-off offers, but never the point-funded
         gifts this customer could claim right now, so a counter had no way to see that the
         person in front of them could take something home.
         This is the SAME projection Customer 360 uses, deliberately: readiness is resolved
         server-side against the active config version, the redemption capability and the real
         balance. Reading loyalty_rewards and comparing cost to points in the browser would be
         the exact thing v145 forbids — and it would be wrong, because a gift can be live in the
         catalogue and still not claimable. */
      walkin?Promise.resolve({data:null,error:null}):sb.rpc('staff_get_customer_actionable_loyalty_v145',{
        p_business:S.biz.id,p_client:cust.client_id,p_branch:tillBranchId
      }),
      walkin?Promise.resolve({data:null,error:null}):sb.from('sale_items')
        .select('item_type,ref_id,created_at,sales!inner(client_id,business_id)')
        .eq('business_id',S.biz.id).eq('sales.client_id',cust.client_id)
        .in('item_type',['service','product'])
        .not('ref_id','is',null)
        .order('created_at',{ascending:false}).limit(60)
    ]);
    if(!isTillCurrent())return;
    catalogLoading=false;
    // V286: stale response — the branch, the customer or the walk-in flag moved on while it was in flight.
    if(tillBranchId!==forBranchV286||(cust?cust.client_id:null)!==forClientV286||walkin!==forWalkinV286){draw();return;}
    if(checkout.error||!checkout.data){
      catalogError=checkout.error?.message||'The checkout catalogue could not be loaded.';
      draw();return;
    }
    if(checkout.data.platform_allowed===false||checkout.data.enabled!==true){
      catalogueSelectionEnabled=false;S.biz.quick_earn_catalogue_enabled=false;draw();return;
    }
    const preferenceState=checkoutPreferencesStateV102(preferences);
    const preferencesAvailable=preferenceState.available;
    if(preferencesAvailable){
      S.biz.gift_card_sales_enabled=preferenceState.giftCardSalesEnabled;
    }else{
      S.biz.gift_card_sales_enabled=null;
    }
    const activeItems=(Array.isArray(checkout.data.items)?checkout.data.items:[])
      .filter(item=>item?.checkout_active===true&&item?.branch_available!==false);
    const serviceById=Object.fromEntries((serviceMeta.data||[]).map(service=>[service.id,service]));
    /* V392: the customer's own recent item ids, newest first, de-duplicated. Ids only — the name
       and price still come from the checkout catalogue, so an item withdrawn from this branch
       cannot reappear through history. */
    const recentIdsV392=(kind=>{
      const seen=[];
      for(const row of (recentItemsV392?.data||[])){
        if(row?.item_type!==kind||!row.ref_id)continue;
        if(!seen.includes(row.ref_id))seen.push(row.ref_id);
      }
      return seen;
    });
	    catalog={
	      customerGiftsV392:giftCatalogueV392?.error?null:(giftCatalogueV392?.data||null),
	      recentServiceIdsV392:recentIdsV392('service'),
	      recentProductIdsV392:recentIdsV392('product'),
	      services:activeItems.filter(item=>item.item_type==='service')
	        .map(item=>({id:item.item_id,
	          name:serviceDisplayName(serviceById[item.item_id]||item),
	          unit_cents:item.unit_cents||0,
	          image_url:item.image_url||''})),
	      products:activeItems.filter(item=>item.item_type==='product')
	        .map(item=>({id:item.item_id,name:item.name,unit_cents:item.unit_cents||0,image_url:item.image_url||''})),
      packages:(pkg.error||!pkg.data)?null:pkg.data.map(p=>({id:p.id,name:p.name,unit_cents:p.price_cents||0})),
      memberships:(mem.error||!mem.data)?null:mem.data.map(p=>({id:p.id,name:p.name,unit_cents:p.price_cents||0,cadence:p.cadence})),
      customerPackages:entitlements.error?[]:(entitlements.data?.packages||[]),
      customerVouchers:entitlements.error?[]:(entitlements.data?.vouchers||[]),
      /* v215: the welcome offer for a first-time sign-up rides in the same entitlements
         payload as packages and vouchers, because this is the one read the till already
         makes for a looked-up customer. */
      customerWelcomeOffer:entitlements.error?null:(entitlements.data?.welcome_offer||null),
      /* V362: a bring-back voucher rides in the SAME entitlements payload as the welcome offer,
         for the same reason — this is the one read the till already makes for a looked-up
         customer, so a second round-trip would be a second thing to keep in sync. */
      customerBringbackOffer:entitlements.error?null:(entitlements.data?.bringback_offer||null),
      /* nestly_v420: the referral gift the REFERRER is owed, from the same payload. */
      customerReferralOffer:entitlements.error?null:(entitlements.data?.referral_offer||null),
      /* V365: the customer's claimable tier benefits, each with what is left this period. */
      customerTierBenefits:tierBenefitsV365?.error?null:(tierBenefitsV365?.data||null),
      packageEarnsPoints:preferenceState.packageEarnsPoints,
      /* A bundle is offered only when EVERY member in it is sellable at this branch — a bundle
         missing a member is not the deal the customer was quoted, so it is withheld rather than
         quietly sold short. Prices come from the branch's own catalogue.
         nestly_v488: members are services OR products now, each checked against its own branch
         catalogue exactly as before. */
      bundles:bundleRows.error?null:(bundleRows.data||[]).map(bundle=>{
        const catalogueById=new Map(activeItems.filter(item=>item.item_type==='service')
          .map(item=>[item.item_id,item]));
        const productCatalogueV488=new Map(activeItems.filter(item=>item.item_type==='product')
          .map(item=>[item.item_id,item]));
        const wanted=(bundle.bundle_items||[]).map(row=>row.service_id).filter(Boolean);
        const wantedProductsV488=(bundle.bundle_items||[]).map(row=>row.product_id).filter(Boolean);
        const items=wanted.map(serviceId=>{
          const listed=catalogueById.get(serviceId);
          if(!listed)return null;
          return {id:serviceId,
            name:serviceDisplayName(serviceById[serviceId]||listed),
            unit_cents:listed.unit_cents||0};
        });
        const productItemsV488=wantedProductsV488.map(productId=>{
          const listed=productCatalogueV488.get(productId);
          if(!listed)return null;
          return {id:productId,name:listed.name||'Product',unit_cents:listed.unit_cents||0};
        });
        return {id:bundle.id,name:bundle.name,unit_cents:bundle.price_cents||0,
          items:[...items,...productItemsV488].filter(Boolean),
          complete:(wanted.length+wantedProductsV488.length)>0
            &&items.every(Boolean)&&productItemsV488.every(Boolean)};
      }).filter(bundle=>bundle.complete)
    };
    draw();
  }
  function addCatalogLine(type,item){
    if(cartLocked())return;
    const ex=cart.find(l=>l.type===type&&l.ref===item.id);
    if(ex){ex.qty++;}
    else cart.push({lineId:crypto.randomUUID(),type,ref:item.id,label:item.name,unit_cents:item.unit_cents,qty:1});
    CUI.announce(workspaceTemplateTextV97('itemAdded',{item:item.name}));onSaleLinesChanged();
  }
  /* v187 (owner: "i dont see in record sale to sell" a bundle). A bundle is several services at
     one price, and it was authorable in Services → Bundles but unsellable at the till.
     sale_items has no bundle type, and inventing one would put a line in the ledger that no
     report, commission rule or staff-performance figure knows how to read. So a bundle is sold
     as what it IS: its member services, each recorded as a normal service line, priced pro-rata
     from their own list prices so the lines sum to EXACTLY the bundle price. Staff performance,
     service reporting and commissions keep working; revenue is the bundle price, not the sum of
     the parts. The remainder cent goes on the last line, so no rounding is invented or lost. */
  /* V204 removed bundleLinePricesV187. It split a bundle's price across its services in the
     browser — a calculation whose result the server was never willing to accept, which is how
     the till came to show one number and charge another. app.ps1c_bundle_lines_v204 does the
     same allocation where the price actually lives. */
  function addBundleLines(bundle){
    if(cartLocked())return;
    if(!Array.isArray(bundle?.items)||!bundle.items.length){
      return toast('That bundle has no items in it yet.');
    }
    const existing=cart.find(line=>line.type==='bundle'&&line.ref===bundle.id);
    if(existing){existing.qty+=1}
    else{
      cart.push({lineId:crypto.randomUUID(),type:'bundle',ref:bundle.id,
        label:bundle.name,unit_cents:bundle.unit_cents,qty:1});
    }
    CUI.announce(workspaceTemplateTextV97('itemAdded',{item:bundle.name}));onSaleLinesChanged();
  }
  // Custom "Other item": an OPTIONAL note rides with the line and is sent to
  // evaluate_checkout / record_cart_sale as amount_cents + reason; the server validates both.
  // The amount may be negative — a correction the other way — and the server refuses to let one
  // take the sale to zero or below.
  function addCustomLine(cents,reason){
    if(cartLocked())return;
    cart.push({lineId:crypto.randomUUID(),type:'custom',ref:null,label:'Other item',unit_cents:cents,qty:1,reason});
    CUI.announce('Item added');onSaleLinesChanged();
  }
  /* Package/membership lines use qty 1 and a stable per-line uuid key minted at
     add-time (reused verbatim on retry so the authoritative writer dedupes), always a NEW line. */
  function addPlanLine(type,plan){
    if(cartLocked())return;
    cart.push({lineId:crypto.randomUUID(),type,ref:plan.id,label:plan.name,unit_cents:plan.unit_cents,qty:1,key:crypto.randomUUID()});
    CUI.announce(workspaceTemplateTextV97('itemAdded',{item:plan.name}));
    /* V257: a screen-reader announcement was the ONLY feedback, and the redraw closed the drawer
       it was added from, so a sighted owner saw nothing at all. Say it out loud. */
    toast(workspaceTemplateTextV97('itemAdded',{item:plan.name}));
    draw(); // extras do not affect the kernel total
  }
  async function useCustomerPackage(clientPackageId){
    if(busy||cartLocked())return;
    const owned=catalog?.customerPackages?.find(item=>item.client_package_id===clientPackageId);
    if(!owned)return toast('That package is no longer available');
    /* V291 (audit follow-up): a native confirm() cannot be translated, so the one dialog that
       takes value off a customer's package spoke English to a workforce CLAUDE.md says may not
       read it. Same deliberate-confirmation dialog as V288; the fixed sentences are registered in
       the workspace copy tables, and only the plan name and remaining count are interpolated. */
    const confirmedSessionV291=await confirmDeliberateV288({
      title:'Use one session?',
      body:`${owned.plan_name} \u00b7 ${owned.remaining} remaining now.`,
      summaryHtml:'<b>What this does</b><p class="small" style="margin-top:5px">One session is taken off this customer\u2019s package straight away. It is recorded as a $0 visit, so nothing is charged and nothing is refunded. If you take it off by mistake, reverse the session record in Sales.</p>',
      acknowledgement:'I understand one session will be taken off.',
      confirmLabel:'Use one session'});
    if(!confirmedSessionV291||!isTillCurrent()||busy||cartLocked())return;
    const attempt=packageUseAttemptKeyV102(packageUseAttemptsV102,clientPackageId,tillBranchId);
    busy=true;
    const {data,error}=await sb.rpc('use_package_session_v102',{
      p_business:S.biz.id,p_client_package:clientPackageId,p_branch:tillBranchId,
      p_idempotency_key:attempt.key
    });
    if(!isTillCurrent())return;
    busy=false;
    if(error)return fail(error);
    const result=packageUseResultV102(data);
    if(!result)return fail(new Error('The package-use receipt was incomplete. Retry with the same branch.'));
    packageUseAttemptsV102.delete(attempt.slot);
    toast(workspaceTemplateTextV97('sessionUsed',{remaining:result.remainingAfter}));
    catalog=null;draw();
  }
  /* v215: give the first-visit free item. p_qualifying_sale is the sale that proves the
     owner's minimum spend; it is null only for a zero-minimum offer, which needs no purchase.
     The key is stable per grant + sale so a double-tap replays instead of giving a second item. */
  async function redeemWelcomeOfferV215(qualifyingSaleId){
    const offer=catalog?.customerWelcomeOffer;
    if(!offer||busy)return;
    const label=offer.reward_label||'the free item';
    /* V291: translatable confirmation for the one-shot welcome gift (see useCustomerPackage). */
    const confirmedWelcomeV291=await confirmDeliberateV288({
      title:'Give the welcome gift?',
      body:`${label} \u2192 ${cust?.full_name||'this customer'}`,
      summaryHtml:'<b>This can only be done once</b><p class="small" style="margin-top:5px">The free item is given to this customer now and their welcome offer is used up. There is no way to give it a second time.</p>',
      acknowledgement:'I understand this can only be given once.',
      confirmLabel:'Give the free item'});
    if(!confirmedWelcomeV291||!isTillCurrent()||busy)return;
    busy=true;
    const {data,error}=await sb.rpc('staff_redeem_welcome_offer_v215',{
      p_business:S.biz.id,p_client:cust.client_id,p_branch:tillBranchId,
      p_qualifying_sale:qualifyingSaleId||null,
      p_idempotency_key:`v215-${offer.grant_id}-${qualifyingSaleId||'no-sale'}`
    });
    if(!isTillCurrent())return;
    busy=false;
    if(error)return fail(error);
    if(data?.status!=='completed')return fail(new Error('The welcome-offer receipt was incomplete. Check the customer before retrying.'));
    toast(workspaceTemplateTextV97('welcomeOfferGiven',{item:label}));
    catalog=null;
    if(doneInfo)doneInfo.welcomeOfferGivenV215=label;
    draw();
  }
  function changeQty(lineId,delta){
    if(cartLocked())return;
    const l=cart.find(x=>x.lineId===lineId);if(!l||!isCartSaleLine(l))return;
    l.qty=Math.max(1,l.qty+delta);onSaleLinesChanged();
  }
  function removeLine(lineId){
    if(cartLocked())return;
    const l=cart.find(x=>x.lineId===lineId);if(!l)return;
    const wasSale=isCartSaleLine(l);
    cart=cart.filter(x=>x.lineId!==lineId);
    if(wasSale)onSaleLinesChanged();else draw(); // removing an extra does not touch the kernel price
  }
  function cartSaleLines(){return cart.filter(isCartSaleLine)}   // service/product/custom -> evaluate + record_cart_sale
  function extraLines(){return cart.filter(l=>!isCartSaleLine(l))} // package/membership -> own RPC
  function extrasTotalCents(){return extraLines().reduce((s,l)=>s+l.unit_cents*l.qty,0)} // NOT part of the kernel/evaluation total
  /* V257: how many of this plan are on the bill. Packages/memberships are EXTRA lines — one line
     per sale, each with its own stable idempotency key — so this counts lines, not qty. */
  function selectedPlanCountV257(type,id){
    return extraLines().reduce((sum,line)=>sum+((line.type===type&&String(line.ref)===String(id))?1:0),0);
  }
  function extraLineBadge(l,succeeded,failed){
    if(l.type==='package')return succeeded
      ?`Sold · ${Number(l._packageResult?.pointsEarned||0)} points earned · ${Number(l._packageResult?.pointsTotal||0)} total`
      :failed?`Not sold — ${esc(l._error||'failed')}`:'Package — charged at checkout';
    if(l.type==='membership')return succeeded?'Enrolled':failed?`Not enrolled — ${esc(l._error||'failed')}`:'Membership — charged at checkout';
    return '';
  }

  /* ================= PS-1C.1 EVALUATE (step 1 of the kernel journey) =================
     evaluate_checkout is AUTHORITATIVE. It is (re-)called whenever the sale-lines (or branch)
     change while the panel is open, and on demand (expiry refresh). The client sends only line
     identities + qty (never a price) for service/product, and amount_cents + reason for custom. */
  function buildEvalLines(){
    return cartSaleLines().map(l=>{
      if(l.type==='custom')return {catalog_kind:'custom',description:l.label,amount_cents:l.unit_cents*l.qty,reason:l.reason||''};
      /* V204: a bundle is its own catalogue kind. We send the bundle id and quantity and
         NOTHING else — the server reads bundles.price_cents and expands it into one priced
         line per service. Sending a price here would be rejected ('client_priced'), which is
         exactly the guard that hid this bug: the old client split the bundle price locally,
         the split never left the browser, and the customer was charged the sum of the parts. */
      if(l.type==='bundle')return {catalog_kind:'bundle',catalog_id:l.ref,qty:l.qty};
      return {catalog_kind:l.type==='product'?'product':'service',catalog_id:l.ref,qty:l.qty};
    });
  }
  // Fingerprint for the STABLE finalise key: it turns over on any sale-line/branch/client change
  // (a new logical checkout) but stays constant across a stale/expiry re-evaluate of the SAME cart.
  function evalFingerprint(){return JSON.stringify({b:tillBranchId||null,c:cust?cust.client_id:null,l:buildEvalLines()});}
  function clearExpiry(){if(evalExpiryTimer){clearTimeout(evalExpiryTimer);evalExpiryTimer=null;}}
  function scheduleExpiry(){
    clearExpiry();
    if(!evalResult||!evalResult.expires_at)return;
    const ms=new Date(evalResult.expires_at).getTime()-Date.now();
    if(!(ms>0)){evalState='expired';return;}
    evalExpiryTimer=setTimeout(()=>{evalExpiryTimer=null;if(!isTillCurrent())return;if(evalState==='ready'){evalState='expired';draw();}},ms);
  }
  // The message tail after a stable "prefix: ..." error token (custom_line_limit / custom_line_invalid).
  function msgTail(msg){const m=/^\s*[a-z0-9_]+\s*[:\-–]\s*(.+)$/is.exec(msg||'');return (m&&m[1].trim())||(msg||'').trim()||'That custom item is not allowed.';}
  function applyEvalError(error){
    const msg=error&&error.message||'';const code=error&&error.code;
    if(/custom_line_denied/.test(msg))evalError={kind:'perm',message:"You don't have permission for custom prices."};
    else if(/custom_line_limit|custom_line_invalid/.test(msg))evalError={kind:'custom',message:msgTail(msg)};
    else if(/total_zero_not_supported/.test(msg))evalError={kind:'zero',message:"Fully discounted carts aren't supported yet — remove a discount or add an item."};
    else if(code==='42501'||/create_sales/.test(msg))evalError={kind:'perm',message:"You don't have permission to record sales."};
    else if(isBackendMissing(error))evalError={kind:'generic',message:`Checkout needs the latest system update — ask an owner to update ${BRAND.productName}.`};
    else evalError={kind:'generic',message:msg||'The price check could not be completed.'};
    evalState='error';evalResult=null;clearExpiry();
  }
  // Reset the evaluation for the current cart and schedule a fresh (debounced) evaluate. A sale-line
  // change is a deliberate cart-change, so it also clears the stable finalise key (§2).
  function onSaleLinesChanged(){
    evalResult=null;evalError=null;staleConfirm=false;staleReevaluationsV257=0;payError=null;clearExpiry();
    clearWriteAttempt(FINALISE_SLOT);
    const lines=buildEvalLines();
    evalState=lines.length?'evaluating':'idle';
    draw();
    if(lines.length)scheduleEval();
  }
  function scheduleEval(){
    if(evalTimer)clearTimeout(evalTimer);
    evalTimer=setTimeout(()=>{evalTimer=null;runEvaluate();},200);
  }
  // On-demand re-evaluate that PRESERVES the finalise key (used by expiry-refresh and the generic
  // "Try again"): evaluation keys and finalise keys are independent; the finalise key stays stable.
  function refreshEval(){if(evalTimer){clearTimeout(evalTimer);evalTimer=null;}evalState='evaluating';draw();runEvaluate();}
  async function runEvaluate(){
    const lines=buildEvalLines();
    if(!lines.length){evalState='idle';evalResult=null;evalError=null;draw();return;}
    const seq=++evalSeq;
    evalState='evaluating';evalError=null;
    const evalKey=crypto.randomUUID(); // a fresh evaluate key per call is fine — independent of the finalise key
    const {data,error}=await sb.rpc('evaluate_checkout',{p_business:S.biz.id,p_branch:tillBranchId||null,
      p_client:cust?cust.client_id:null,p_lines:lines,p_idempotency_key:evalKey});
    if(!isTillCurrent())return;
    if(seq!==evalSeq)return; // a newer evaluate superseded this one
    if(error){applyEvalError(error);draw();return false;}
    evalResult=data;evalError=null;evalState='ready';svTender=null; // a fresh token invalidates any prior SV hold
    scheduleExpiry();draw();
    return true;
  }

  // One applied/suppressed discount effect from the evaluation. Rule NAMES are not exposed to the
  // client — we show a neutral "Discount" plus its level (item/whole bill). Suppressed effects are
  // greyed with a plain-words reason. Field access is defensive so a minor server shape change is safe.
  function effectRowHtml(e){
    if(!e||typeof e!=='object')return '';
    const suppressed=e.suppressed===true||!!e.suppression_reason;
    const lvl=e.level||e.scope||'';
    const scopeTxt=lvl==='bill'?' (whole bill)':lvl==='line'?' (item)':'';
    if(suppressed){
      const why={stacking:'not stackable with another offer',budget_exhausted:'offer budget used up',no_target:'not applicable'}[e.suppression_reason]||'not applied';
      return `<li class="ck-effect ck-effect-off"><span class="ck-effect-label">${CUI.icon('info',{size:16})}<span>Discount${scopeTxt}</span></span><span class="ck-effect-why">${esc(why)}</span></li>`;
    }
    const amt=e.amount_cents!=null?e.amount_cents:(e.discount_cents!=null?e.discount_cents:(e.amount!=null?e.amount:0));
    /* V370: the automatic tier discount arrives in the same applied_effects list as a Studio rule
       effect, carrying no rule and its own label. It is named on the receipt line, because
       "Discount (whole bill)" tells the counter nothing about why the price dropped — and the
       customer will ask. Every figure is still the server's; only the words differ. */
    const labelV370=e.source==='tier_benefit'
      ?`${String(e.label||'Tier benefit')}${scopeTxt}`
      :`Discount${scopeTxt}`;
    return `<li class="ck-effect"><span class="ck-effect-label">${CUI.icon('loyalty',{size:16})}<span>${esc(labelV370)}</span></span><span>−${money(amt)}</span></li>`;
  }
  // The server-priced checkout panel. Every payable figure here is copied verbatim from the last
  // evaluate_checkout — the client never computes a total or a discount.
  function checkoutPanelHtml(){
    if(!cartSaleLines().length)return ''; // no kernel evaluation without service/product/custom lines
    if(evalState==='evaluating')
      return `<div class="ck-panel" data-checking><div class="ck-checking" role="status">${CUI.icon('retention',{size:16})}<span>Checking price…</span></div></div>`;
    if(evalState==='error'&&evalError)
      return `<div class="ck-notice warn" role="alert">${esc(evalError.message)}</div>`;
    if(!evalResult)return '';
    const r=evalResult;
    const rows=(r.applied_effects||[]).map(effectRowHtml).join('');
    const gstLine=r.gst_cents>0?`<div class="ck-row ck-gst"><span>incl. GST</span><span>${money(r.gst_cents)}</span></div>`:'';
    const totalCls=evalState==='expired'?' ck-stale':'';
    const breakdown=`<div class="ck-panel"${evalState==='expired'?' data-checking':''} aria-label="Amount payable">
        <div class="ck-row"><span>Subtotal</span><span>${money(r.subtotal_cents)}</span></div>
        ${rows}${gstLine}
        <div class="ck-total${totalCls}"><span>Total</span><span>${money(r.total_cents)}</span></div>
      </div>`;
    // v67 stored-value tender — offered ONLY when the server reports a spendable balance > 0 (never
    // in prod this phase). Every amount is server-rendered; the client never sizes the SV portion.
    let svHtml='';
    const sv=r.stored_value;
    if(!walkin&&sv&&sv.spendable===true&&(sv.available_cents||0)>0&&!staleConfirm&&evalState==='ready'&&!payError){
      if(svTender)
        svHtml=`<div class="ck-panel" style="margin-top:10px" aria-label="Stored value applied">
          <div class="ck-row"><span>${CUI.icon('loyalty',{size:16})} Stored value</span><span>−${money(svTender.reserved_cents)}</span></div>
          <div class="ck-total"><span>Cash due</span><span>${money(svTender.remaining_due_cents)}</span></div>
          <button type="button" class="btn ghost sm" id="tSvRemove" style="width:100%;margin-top:8px">Remove stored value</button></div>`;
      else
        svHtml=`<div class="ck-panel" style="margin-top:10px" aria-label="Stored value available">
          <p class="muted small" style="margin:0 0 8px">Stored value available: <b>${money(sv.available_cents)}</b></p>
          <button type="button" class="btn ghost" id="tSvUse" style="width:100%"${svBusy?' disabled':''}>${CUI.icon('loyalty',{size:16})} ${svBusy?'Applying…':'Use stored value'}</button></div>`;
    }
    let notice='';
    if(staleConfirm)notice=`<div class="ck-notice info" role="alert">Price updated — please confirm the new total.</div>`;
    else if(evalState==='expired')notice=`<div class="ck-notice warn" role="status">Price check expired — refresh to get the current price.</div>`;
    else if(payError&&payError.kind==='retry')notice=`<div class="ck-notice warn" role="alert">The payment did not go through. Retry — you will not be charged twice.</div>`;
    else if(payError&&payError.kind==='conflict')notice=`<div class="ck-notice warn" role="alert">This checkout was already used for a different sale. Start a new checkout to continue.</div>`;
    return breakdown+svHtml+notice;
  }
  // The single primary action for the panel, chosen by the current checkout state.
  function checkoutActionHtml(){
    const hasSale=cartSaleLines().length>0, extras=extraLines();
    if(!hasSale)
      return extras.length?`<button class="btn" id="tCartConfirm" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('check',{size:20})} Record sale · ${money(extrasTotalCents())}</button>`:'';
    if(staleConfirm)
      return `<button class="btn" id="tStaleConfirm" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('check',{size:20})} Confirm new total · ${money(evalResult.total_cents)}</button>`;
    if(payError&&payError.kind==='retry')
      return `<button class="btn" id="tPayRetry" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('retention',{size:20})} Retry payment</button>`;
    if(payError&&payError.kind==='conflict')
      return `<button class="btn" id="tNewCheckout" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('retention',{size:20})} Start a new checkout</button>`;
    if(evalState==='evaluating')
      return `<button class="btn" id="tEvalWait" style="width:100%;margin-top:16px;padding:18px;font-size:18px" disabled>Checking price…</button>`;
    if(evalState==='expired')
      return `<button class="btn" id="tRefreshEval" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('retention',{size:20})} Refresh price</button>`;
    if(evalState==='error')
      return evalError&&evalError.kind==='generic'?`<button class="btn" id="tRefreshEval" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('retention',{size:20})} Try again</button>`:'';
    if(evalState==='ready'&&evalResult){
      /* V257: this one button finalises the cart AND sells every extra, so it names the whole
         amount collected — not just the kernel total, which is what made the till look like it
         was asking for two payments. */
      const dueV257=(svTender?svTender.remaining_due_cents:evalResult.total_cents)+extrasTotalCents();
      /* V373 (owner's confirm screen: "[Record sale · $21]"). The tender is chosen directly above
         this button now, so the money has already been taken by the time a hand reaches it — the
         button's job is to record what happened. The FIGURE is unchanged: still the whole amount
         across both records, still the evaluation's. */
      return `<button class="btn" id="tCartConfirm" style="width:100%;margin-top:16px;padding:18px;font-size:18px">${CUI.icon('check',{size:20})} Record sale · ${money(dueV257)}</button>`;
    }
    return '';
  }

  /* ==========================================================================================
     V373 — ONE Record sale flow (owner: "simplify my record sale, make it easy to use and very
     clear — current model too crowded and no tabs to consolidate it").

     What was wrong was not any single control; it was that all of them were on screen at once.
     Every service, every product, every bundle, a "Sell package" drawer, memberships, an
     "Other item" button, the customer's own packages, every tier benefit of their rung, the
     cart, the price panel, the tender buttons and the confirm button — one column, one scroll.
     Worse, it read as three different jobs ("use a package", "record a sale", "sell a package"),
     so a counter hand had to decide WHICH flow they were in before they could ring up a haircut.

     The flow is now the one the owner described: customer -> what they had -> rewards -> confirm.
       stage 'items'  — the customer in one line, the few things tapped most often, their own
                        packages, and only the rewards that can be given on THIS sale
       stage 'review' — the server-priced bill, how they paid, one confirm button
     Everything else lives behind ONE "Add item" sheet with tabs: services, products, use a
     package, sell a package, memberships, other item. Selling a package is a tab, not a journey.

     NOTHING about the money moved. evaluate_checkout is still the only pricing authority and
     every payable figure on both stages is copied from it verbatim; record_cart_sale still
     finalises the cart under one stable idempotency key; packages and memberships are still
     their own server-idempotent writes with their own keys; the lock and recovery states are
     untouched — a locked cart simply forces the review stage, which is where its recovery panel
     has always lived.
     ========================================================================================== */
  function drawCartComposer(){
    if(catalog===null&&!catalogError)loadCatalog();
    /* A cart in recovery — a failed finalise, a stale re-price, a live PayNow QR, unfinished
       extras — has never been editable, and every one of those panels is part of the bill, so
       'review' is the only stage such a cart can be on. */
    if(cartLocked())tillStageV373='review';
    if(tillStageV373==='review'&&!cart.length)tillStageV373='items';
    if(tillStageV373!=='items')closeTillAddSheetV373();
    const reviewing=tillStageV373==='review';
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',
      subtitle:reviewing
        ?'Check the bill, choose how the customer paid, then confirm.'
        :'Choose products or services, review the checked total, then select how the customer paid.',
      iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card till-cart-card till-found-card till-flow-v373">
        ${tillCustomerHeadV373()}
        ${reviewing?tillReviewStageHtmlV373():tillItemsStageHtmlV373()}
      </div>`;
    bindTillControlsV373();
    if(tillAddSheetV373)paintTillAddSheetV373();
  }

  /* ---------------------------------------------------------------- the customer, in one line */
  /* V373 compresses what used to be four rows before the first item — a name block, a
     "member since / last visit" note, a branch <select> and a teammate <select> — into one
     identity line plus a disclosure. Nothing was dropped: the pickers are the same controls,
     with the same ids, the same candidate rules, the same defaults and the same handlers. */
  function tillCustomerHeadV373(){
    const locked=cartLocked();
    const branchPicker=accessibleTillBranches.length>1
      ?`<label for="tBranch">Branch</label><select id="tBranch"${locked?' disabled':''}>${accessibleTillBranches.map(branch=>`<option value="${branch.id}" ${branch.id===tillBranchId?'selected':''}>${esc(branch.name)}</option>`).join('')}</select>`
      :'';
    /* V287. The catalogue composer is the DEFAULT checkout for every firm with catalogue
       selection on, and it carried no "Who made this sale?" control at all — while
       record_cart_sale still sends p_staff. Every commission on the default path was therefore
       attributed to whoever happened to be signed in at the counter. This is the SAME picker the
       legacy amount-only card renders: same id, same candidate rule, same default, same copy. */
    const tillAttributableStaff=tillAttributableStaffFor(tillBranchId);
    if(!tillAttributableStaff.some(person=>person.id===tillSaleStaffId))tillSaleStaffId=tillActingStaffId;
    const staffPickerV287=tillAttributableStaff.length>1
      ?`<label for="tillSaleStaff">Who made this sale?</label>
        <select id="tillSaleStaff" style="margin-bottom:12px"${locked?' disabled':''}>${tillAttributableStaff.map(person=>`<option value="${esc(person.id)}" ${person.id===tillSaleStaffId?'selected':''} data-merchant-content>${esc(person.full_name||'Team member')}${person.id===tillActingStaffId?' (you)':''}</option>`).join('')}</select>
        <p class="muted small" style="margin:-6px 0 12px">Commission for this sale is recorded against this teammate.</p>`
      :'';
    const branchName=accessibleTillBranches.find(branch=>branch.id===tillBranchId)?.name||'';
    const staffName=(tillAttributableStaff.find(person=>person.id===tillSaleStaffId)
      ||tillRoster.find(person=>person.id===tillSaleStaffId))?.full_name||'';
    /* Only offered where there is a genuine choice to make. With one branch and one teammate the
       line above already says which, and a disclosure hiding two read-only facts is furniture. */
    const branchSwitchableV468=accessibleTillBranches.length>1;
    const staffSwitchableV468=tillAttributableStaff.length>1;
    const hasPickersV468=branchSwitchableV468||staffSwitchableV468;
    /* V468-B (owner photo, Record sale items step): "Change branch or teammate" used to be a
       muted 12.5px text link sitting under a separate read-only line — "the control is too
       hidden" per the owner's ruling ("one staff per sale is fine, tag it + commission, but I
       need to see and change who without hunting"). The <details>/<summary>/<select> pair is
       otherwise UNCHANGED — same ids, same tillAttributableStaffFor/branch candidate rules, same
       onchange handlers bound in bindTillControlsV373 further down. Only the summary's content
       and styling change: it now shows the CURRENT branch/teammate (legible at a glance) inside a
       visible chip button that opens the same picker in one tap, instead of a generic link that
       said nothing about who the sale is tagged to. */
    const whoChipTextV468=[branchSwitchableV468?`<b data-merchant-content>${esc(branchName)}</b>`:'',
      staffSwitchableV468?`<b data-merchant-content>${esc(staffName||'Choose teammate')}</b>`:'']
      .filter(Boolean).join(' <span class="till-who-sep-v468">·</span> ');
    const pickers=hasPickersV468
      ?`<details class="till-who-v373 till-who-v468" id="tillWhoV373"${tillWhoOpenV373?' open':''}>
        <summary class="till-who-summary-v468">${CUI.icon('staff',{size:18})}<span class="till-who-summary-text-v468">${whoChipTextV468}</span><span class="till-who-summary-change-v468">Change</span></summary>
        ${branchPicker}
        ${staffPickerV287}</details>`
      :'';
    // Nothing switchable here (one branch, one teammate) — the old plain read-only line stands.
    const contextLine=hasPickersV468?'':[branchName?esc(branchName):'',staffName?`Staff: ${esc(staffName)}`:''].filter(Boolean).join(' · ');
    if(walkin){
      return `<div class="till-head-v373">
        <div class="till-head-id-v373"><b class="till-head-name-v373">Walk-in customer</b>
          <p class="muted small" style="margin:2px 0 0">No points, rewards, packages or stored value.</p>
          ${contextLine?`<p class="muted small" style="margin:2px 0 0" data-merchant-content>${contextLine}</p>`:''}</div>
        <button type="button" class="btn ghost sm" id="tWalkinSwitch">${CUI.icon('customers',{size:16})} Customer</button>
      </div>${pickers}`;
    }
    const tierLabel=catalog?.customerTierBenefits?.tier?.label||'';
    const pointsValue=Number(cust?.points);
    /* nestly_v474: on a stamps firm this is the customer's own card, not the pot. See
       stampCardStandingV474 — the till and the customer profile share that one formatter. */
    const standingFigureV474=cust?.stamp_card
      ?stampCardStandingV474(cust.stamp_card,pointsValue,tillUnitNounV430(catalog,true))
      :(Number.isFinite(pointsValue)?`${pointsValue.toLocaleString('en-SG')} ${tillUnitNounV430(catalog,true)}`:'');
    const standing=[tierLabel?esc(tierLabel):'',standingFigureV474?esc(standingFigureV474):'']
      .filter(Boolean).join(' · ');
    return `<div class="till-head-v373">
      <div class="till-head-id-v373"><b class="till-head-name-v373" data-merchant-content>${esc(cust.full_name)}</b>
        ${standing?`<p class="small till-head-standing-v373" data-merchant-content style="margin:2px 0 0">${standing}</p>`:''}
        ${contextLine?`<p class="muted small" style="margin:2px 0 0" data-merchant-content>${contextLine}</p>`:''}
        ${/* V378 (owner, photo 4: this line struck through). "Member since / Last visit" is history,
             and the counter is mid-sale — the card keeps only what identifies the person in front
             of them. Both facts stay one tap away on the customer profile. */''}</div>
      <p class="inline-status" style="margin:0;color:var(--green)">${CUI.icon('check',{size:16})}<span>Found</span></p>
    </div>${pickers}`;
  }

  /* ------------------------------------------------------------------------- catalogue tiles */
  /* One tile, used by BOTH the quick grid and the Add item sheet, so an item looks the same and
     counts the same wherever it is tapped. */
  function tillSelectedQtyV373(){
    const saleLines=cartSaleLines();
    const selectedCatalogQty=(type,id)=>saleLines.reduce((sum,line)=>sum+(line.type===type&&String(line.ref)===String(id)?Number(line.qty||0):0),0);
    return selectedCatalogQty;
  }
  /* V468-B: the ONE cart line a tile's type+ref maps to (addCatalogLine/addBundleLines always
     merge into an existing line rather than pushing a second one for the same item), so a tile
     needing to show/adjust "its" line just needs this line's id. */
  function tillLineForTileV468(type,id){
    return cart.find(line=>line.type===type&&String(line.ref)===String(id))||null;
  }
  /* V468-B (owner photo, Record sale items step: "I need to be able to deduct the quantity or
     remove entirely in this page"). Reuses the Confirm step's OWN handlers verbatim — data-qty/
     data-remove/data-line are the exact attributes tillCartLinesHtmlV373's row uses, and both are
     wired by the single delegated binder in bindTillControlsV373 (already runs after every draw,
     no new listener needed). The only new decision made here, not a new mutation: at qty 1 the
     "−" tap is wired to data-remove instead of data-qty="-1", because changeQty on its own clamps
     at a floor of 1 (by design, for the Confirm step's separate always-visible × button) — on a
     tile there is no second remove affordance, so decrementing at 1 IS the remove gesture and
     drops the tile back to its untouched, unselected look. */
  function tillTileQtyCtlV468(type,id,qty,itemLabel){
    if(!qty)return '';
    const line=tillLineForTileV468(type,id);
    if(!line)return '';
    const minus=qty>1
      ?`<button type="button" data-qty="-1" data-line="${esc(line.lineId)}" data-merchant-content aria-label="Reduce ${esc(itemLabel)} quantity">−</button>`
      :`<button type="button" class="till-choice-qtyctl-remove-v468" data-remove="${esc(line.lineId)}" data-merchant-content aria-label="Remove ${esc(itemLabel)}">−</button>`;
    return `<div class="till-choice-qtyctl-v468" role="group" aria-label="${esc(itemLabel)} quantity" data-merchant-content>
      ${minus}<output aria-label="Quantity">${qty}</output>
      <button type="button" data-qty="1" data-line="${esc(line.lineId)}" data-merchant-content aria-label="Increase ${esc(itemLabel)} quantity">+</button>
    </div>`;
  }
  function tillCatalogueTilesV373(entries){
    const selectedCatalogQty=tillSelectedQtyV373();
    return entries.map(({type,item})=>{
      const qty=selectedCatalogQty(type,item.id);
      const image=catalogueImageUrlV158(item);
      const tile=`<button type="button" class="choice-button ${image?'has-image':''} ${qty?'is-selected':''}" data-add="${type}" data-id="${esc(item.id)}">${image?`<img class="till-choice-image" src="${esc(image)}" alt="" loading="lazy">`:''}<span class="till-choice-text"><b>${esc(item.name)}</b><span class="till-cart-price">${money(item.unit_cents)}</span></span>${qty?`<span class="till-choice-qty" data-workspace-i18n aria-label="${qty} selected">${qty}</span>`:''}</button>`;
      // Untouched tiles are unwrapped, unchanged markup — the qty row only ever appears once the item is in the cart.
      return qty?`<div class="till-choice-tile-wrap-v468">${tile}${tillTileQtyCtlV468(type,item.id,qty,item.name)}</div>`:tile;
    }).join('');
  }
  /* v187: a bundle is several services at one price. It keeps the service tile's badge — it is a
     cart sale line of its own type, so it counts its own lines, never the services the server
     expands it into. */
  function tillBundleTilesV373(bundles){
    const selectedCatalogQty=tillSelectedQtyV373();
    return bundles.map(bundle=>{
      const qty=selectedCatalogQty('bundle',bundle.id);
      const tile=`<button type="button" class="choice-button ${qty?'is-selected':''}" data-add-bundle="${esc(bundle.id)}"><span class="till-choice-text"><b>${esc(bundle.name)}</b><span class="muted small">${esc(bundle.items.map(item=>item.name).join(' + '))}</span><span class="till-cart-price">${money(bundle.unit_cents)}</span></span>${qty?`<span class="till-choice-qty" data-workspace-i18n aria-label="${qty} selected">${qty}</span>`:''}</button>`;
      return qty?`<div class="till-choice-tile-wrap-v468">${tile}${tillTileQtyCtlV468('bundle',bundle.id,qty,bundle.name)}</div>`:tile;
    }).join('');
  }
  /* V216 (owner: "i need a product modules - instead of just services (because products have no
     minutes)"). The picker used to print a hardcoded "Services" heading and give products none, so
     a cafe with seven products and no services saw an empty "Services" label above unlabelled
     buttons — the app insisting on a concept that business does not have. Each group names itself,
     and a group with nothing in it prints no heading. V373 keeps the rule on the quick grid. */
  function tillGroupHeadingV216(label,count){
    return count?`<b class="small" style="display:block;margin-top:12px">${label}</b>`:'';
  }
  /* nestly_v411 (owner photo 2: "record sale is still missing bundle item"). A bundle was
     authorable, priced and sellable — tillBundleTilesV373 and the data-add-bundle handler have
     existed since v187 — but it rendered in exactly ONE place: inside the More items sheet, on the
     Services tab, below the whole services list. On the main Record sale screen a bundle was
     invisible, and the search box beside the grid could not find one either, because the entries
     it searches were built from services and products only. It is a third group on the grid now,
     with the same heading treatment services and products get, and it disappears the same way
     when the firm has no bundles. Same tiles and the same data-add-bundle attribute, so the
     existing add handler owns it — no second way to put a bundle in the cart. */
  function tillQuickGroupsHtmlV373(shownServices,shownProducts,shownBundles=[]){
    return `${tillGroupHeadingV216('Services',shownServices.length)}${shownServices.length?`<div class="till-cart-catalog till-quick-grid-v373">${tillCatalogueTilesV373(shownServices)}</div>`:''}${tillGroupHeadingV216('Products',shownProducts.length)}${shownProducts.length?`<div class="till-cart-catalog till-quick-grid-v373">${tillCatalogueTilesV373(shownProducts)}</div>`:''}${tillGroupHeadingV216('Bundles',shownBundles.length)}${shownBundles.length?`<div class="till-cart-catalog till-quick-grid-v373">${tillBundleTilesV373(shownBundles)}</div><p class="muted small" style="margin-top:6px">A bundle adds each of its services at the bundle price.</p>`:''}`;
  }
  /* V211/V257: package plans on sale. Each is an EXTRA line with its own idempotency key, so the
     badge counts lines, not quantity. */
  function tillPackagePlanTilesV373(plans){
    return plans.map(p=>{
      const qty=selectedPlanCountV257('package',p.id);
      return `<button type="button" class="choice-button ${qty?'is-selected':''}" data-plan="package" data-id="${esc(p.id)}"><span class="till-choice-text"><b>${esc(p.name)}</b><span class="till-cart-price">${money(p.unit_cents)}</span></span>${qty?`<span class="till-choice-qty" data-workspace-i18n aria-label="${qty} selected">${qty}</span>`:''}</button>`;
    }).join('');
  }
  /* V211 (owner: "i still dont see the package here in record sale - not able to use sessions").
     Spending a session the customer already paid for is the commoner act at a counter than
     selling them another package, so it stays on the main screen; the sheet carries the same
     list for staff who went looking for it there. */
  function tillOwnedPackagesBlockV373({inSheet=false}={}){
    const ownedPkgs=(walkin?[]:(catalog?.customerPackages||[])).filter(item=>Number(item.remaining)>0);
    const ownedPackages=ownedPkgs.length
      ?`<b class="small" style="display:block;margin-top:14px">${inSheet?'Use an existing customer package':'Available packages'}</b>
        <p class="muted small" style="margin:4px 0 8px">No payment is taken. One session is deducted and recorded as a visit. No points are earned — they were earned when the package was bought.</p>
        <div class="till-cart-catalog">${ownedPkgs.map(item=>`<button type="button" class="choice-button" data-use-package="${esc(item.client_package_id)}">
          <b>${esc(item.plan_name||'Package')}</b>
          <span class="muted small">${esc(item.service_name||'Session')}${item.variant_label?' · '+esc(item.variant_label):''}</span>
          <span class="pill ok">${Number(item.remaining)} left</span></button>`).join('')}</div>`
      :'';
    return ownedPackages;
  }

  /* ------------------------------------------------------------------------------- rewards */
  /* V373 (owner: "Do NOT show the full list of tier benefits. Only show benefits that are
     eligible for this transaction today. Auto-apply deterministic discounts. Only require staff
     action for physical rewards").

     A tier benefit that is a percentage and carries NO per-period limit is applied by
     evaluate_checkout itself (V370) — the one place allowed to move money. Printing a Give
     button beside it asked a cashier to hand over a discount the bill had already taken off,
     and pressing it burned an issue record for a benefit with no limit to count it against. It
     is now shown as what it is: automatic, with the server's own figure once the price check
     comes back. Everything a human actually hands over — a free item, a custom perk, a limited
     discount — keeps its Give button. The rest of the ladder moves behind "View all benefits",
     so an unavailable perk is still explainable to a customer without crowding the sale. */
  function tillAutoTierDiscountV373(benefits){
    /* The engine's own rule, read the same way: the best UNLIMITED discount_pct the customer's
       rung entitles them to. The payload is already ordered by threshold desc, so a stable sort
       on the percentage reproduces evaluate_checkout's pick. */
    return benefits.filter(benefit=>benefit.benefit_kind==='discount_pct'&&benefit.limit_count==null)
      .sort((a,b)=>Number(b.discount_percent||0)-Number(a.discount_percent||0))[0]||null;
  }
  function tillBenefitLimitTextV373(benefit){
    if(benefit.limit_count==null)return 'No limit';
    const left=Math.max(0,Number(benefit.remaining)||0);
    const period=benefit.limit_period==='birthday_month'?'this birthday month'
      :benefit.limit_period==='ever'?'in total'
      :`this ${esc(benefit.limit_period||'month')}`;
    return `${left} left ${period}`;
  }
  function tillRewardsBlockV373(){
    if(walkin||!catalog)return {html:'',count:0};
    /* v215: a welcome offer for a first-time sign-up. Where the button lives follows the server
       contract, not convenience: a minimum spend is proved against a REAL recorded sale, so that
       button appears on the receipt once the sale exists. A zero-minimum offer needs no purchase,
       so it is given straight from here. Nothing here decides eligibility —
       staff_redeem_welcome_offer_v215 re-checks all of it. */
    const welcomeOffer=catalog.customerWelcomeOffer||null;
    const welcomeMin=Number(welcomeOffer?.min_spend_cents)||0;
    const welcomeBanner=welcomeOffer
      ?`<div class="permission-banner welcome-offer-v215" style="margin-bottom:14px"><b>Welcome offer &mdash; new sign-up</b>
        <p class="small" style="margin:5px 0">${esc(welcomeOffer.reward_label||'Free item')} is free for this customer.</p>
        ${welcomeMin
          ?`<p class="muted small" style="margin:5px 0">Needs at least ${money(welcomeMin)} on this sale. Ring the sale up first — the free item is offered on the receipt.</p>`
          :`<p class="muted small" style="margin:5px 0">No minimum spend. Nothing is charged.</p>
            <button type="button" class="btn primary sm" id="tWelcomeRedeemV215">Give ${esc(welcomeOffer.reward_label||'the free item')}</button>`}</div>`
      :'';
    /* V362: a bring-back voucher is always redeemable on sight — unlike the welcome offer there
       is no minimum-spend variant, because its condition (being away) was met before it was
       issued. staff_redeem_bringback_v361 re-checks expiry, ownership and branch. */
    const bringbackOffer=catalog.customerBringbackOffer||null;
    const bringbackBanner=bringbackOffer
      ?`<div class="permission-banner welcome-offer-v215" style="margin-bottom:14px"><b>Bring-back voucher</b>
        <p class="small" style="margin:5px 0">${esc(bringbackOffer.reward_label||'Free item')} is free for this customer.</p>
        <p class="muted small" style="margin:5px 0">Sent because they had not visited for ${Math.max(0,Number(bringbackOffer.away_days)||0)} days. Nothing is charged.</p>
        <button type="button" class="btn primary sm" id="tBringbackRedeemV362" data-grant="${esc(bringbackOffer.grant_id)}">Give ${esc(bringbackOffer.reward_label||'the free item')}</button></div>`
      :'';
    /* nestly_v420 (owner, photo 4: "referral why only points option? can also be free gift").
       A gift referral is owed to the REFERRER, and is redeemable on sight for the same reason the
       bring-back voucher is: its condition — the friend's first qualifying visit — was met before
       the grant was written. staff_redeem_referral_v420 re-checks ownership, expiry and branch. */
    const referralOffer=catalog.customerReferralOffer||null;
    const referralBanner=referralOffer
      ?`<div class="permission-banner welcome-offer-v215" style="margin-bottom:14px"><b>Referral gift</b>
        <p class="small" style="margin:5px 0">${esc(referralOffer.reward_label||'Free item')} is free for this customer.</p>
        <p class="muted small" style="margin:5px 0">Earned for introducing a friend who has now visited. Nothing is charged.</p>
        <button type="button" class="btn primary sm" id="tReferralRedeemV420" data-grant="${esc(referralOffer.grant_id)}">Give ${esc(referralOffer.reward_label||'the free item')}</button></div>`
      :'';
    const pendingVouchers=(catalog.customerVouchers||[]).length
      ?`<div class="permission-banner" style="margin-bottom:14px"><b>Reward voucher ready</b>
        ${(catalog.customerVouchers||[]).map(voucher=>`<p class="small" style="margin:5px 0">${esc(voucher.reward_name)} · ${voucher.points_spent} ${tillUnitNounV430(catalog)} <span class="muted">— scan the customer's QR to confirm it</span></p>`).join('')}
        ${canScanRedemption()?`<button type="button" class="btn ghost sm" id="tEntitlementScan">${CUI.icon('scan',{size:16})} Scan reward QR</button>`:''}</div>`
      :'';
    const allBenefits=Array.isArray(catalog.customerTierBenefits?.benefits)?catalog.customerTierBenefits.benefits:[];
    const autoBenefit=tillAutoTierDiscountV373(allBenefits);
    const giveNow=allBenefits.filter(benefit=>benefit.claimable_now!==false&&benefit!==autoBenefit);
    /* The applied figure is the SERVER's, never a percentage this screen worked out for itself. */
    const appliedTierEffect=(evalResult?.applied_effects||[])
      .find(effect=>effect&&effect.source==='tier_benefit'&&!effect.suppressed&&!effect.suppression_reason);
    const tierName=esc(catalog.customerTierBenefits?.tier?.label||'Tier');
    const autoRow=autoBenefit
      ?`<div class="till-tier-benefit-row-v369 till-benefit-auto-v373">
          <span><b class="small">${esc(autoBenefit.sentence||autoBenefit.label||'Discount')}</b>
          <span class="muted small">Applied automatically at payment — no action needed</span></span>
          <span class="pill ok">${appliedTierEffect
            ?`Applied · −${money(appliedTierEffect.amount_cents!=null?appliedTierEffect.amount_cents:0)}`
            :'Automatic'}</span>
        </div>`
      :'';
    const giveRows=giveNow.map(benefit=>`<div class="till-tier-benefit-row-v369">
        <span><b class="small">${esc(benefit.sentence||benefit.label||'Benefit')}</b>
        <span class="muted small">${tillBenefitLimitTextV373(benefit)}</span></span>
        <button type="button" class="btn primary sm" data-tier-benefit-give-v365="${esc(benefit.benefit_id)}" data-label="${esc(benefit.label||'')}">Give</button>
      </div>`).join('');
    const tierBanner=(autoRow||giveRows)
      ?`<div class="permission-banner welcome-offer-v215 till-tier-benefits-v369" style="margin-bottom:14px"><b>${tierName} benefits</b>
        <p class="muted small" style="margin:5px 0">Ready to give now. Peekaa counts each one against its limit.</p>
        ${autoRow}${giveRows}</div>`
      :'';
    /* V392: what this customer's points can actually take home today.
       Affordable gifts lead; the next one up is shown too, with how many points are still needed,
       because "you are 5 away" is the sentence that sells the next visit. Nothing here issues
       anything: a point redemption is confirmed against the customer's own QR
       (staff_scan_member_qr_v327 / the voucher scan below), and inventing a second, unscanned
       give-path from the till would be a way to spend a customer's points without them present.
       So this states what is available and hands over to the scan that already exists. */
    const giftProjectionV392=catalog.customerGiftsV392||null;
    const giftUnitV392=giftProjectionV392?.program?.unit==='stamps'?'stamps':'points';
    const giftsV392=Array.isArray(giftProjectionV392?.rewards)?giftProjectionV392.rewards:[];
    /* available_now and remaining_units are the SERVER's answers. Nothing here recomputes
       readiness from a balance and a cost — see v145. V432: the server list now carries only
       the two actionable states (redeemable now, or genuine progress), each tagged with the
       source its eligibility came from; this screen buckets by that tag and nothing else. */
    const affordableV392=giftsV392.filter(gift=>gift.available_now===true);
    const redeemableGroupsV432=groupRedeemableRewardsV432(affordableV392);
    const nextUpV392=giftsV392.filter(gift=>gift.available_now!==true&&gift.availability==='insufficient_balance')
      .sort((a,b)=>(Number(a.remaining_units)||0)-(Number(b.remaining_units)||0))[0]||null;
    /* nestly_v435 (simulation P1): with the redemption capability OFF the till used to show
       nothing at all here, and staff had no way to know WHY a customer with a full card had no
       redeem button. Name the switch and where it lives. */
    const redemptionOffHintV435=(giftProjectionV392&&giftProjectionV392.redemption_enabled===false&&giftProjectionV392.program)
      ?`<div class="permission-banner till-tier-benefits-v369" style="margin-bottom:14px"><b>Customer redemption is switched off.</b>
        <p class="muted small" style="margin:5px 0">Turn it on under Customer Interface → Customer Action to redeem rewards at the counter.</p></div>`
      :'';
    const giftsBannerV392=(redeemableGroupsV432.length||nextUpV392)
      ?`<div class="permission-banner welcome-offer-v215 till-tier-benefits-v369" style="margin-bottom:14px"><b>Rewards this customer can claim</b>
        ${/* V399: this banner is the one V372 missed. .permission-banner is display:flex with the
             default row direction and no wrap, so the heading, the instruction, every reward row
             and the scan button were all flex items on ONE line — which is why photo 3 shows them
             squashed side by side and running to the card's edge. till-tier-benefits-v369 is the
             existing class that turns exactly this container into a column; the sibling tier
             banner directly above has carried it since V372. Same fix, same class, no new CSS. */''}
        <p class="muted small" style="margin:5px 0">${canManualRedeemV404()
          ?"Scan the customer's QR, or redeem here and say why."
          :"Scan the customer's QR to confirm a redemption."}</p>
        ${/* V404 (owner, photo 1: "'ready' change to redeem > and able to click to redeem", with
             a quantity control "like record sale"). The Ready pill stated a fact nobody could act
             on; it is a control now for staff who hold the manual-redemption permission, and stays
             a pill for everyone else — the server refuses either way, so this only decides what is
             DRAWN. The stepper is the same .till-cart-qty markup the cart lines use, so the
             gesture is the one staff already know. */''}
        ${redeemableGroupsV432.map(group=>`<p class="small till-reward-group-v432" style="margin:8px 0 0"><b>${esc(group.label)}</b></p>
        ${group.rewards.map(gift=>{
          const unitV432=gift.unit==='stamps'?'stamps':gift.unit==='points'?'points':giftUnitV392;
          const costV404=Number.isFinite(Number(gift.cost_units))?`${esc(String(Number(gift.cost_units)))} ${esc(unitV432)}`:'';
          const idV404=esc(String(gift.reward_id||''));
          const qtyV404=tillManualQtyV404[gift.reward_id]||1;
          const actionV404=(canManualRedeemV404()&&gift.reward_id)
            ?`<span class="till-manual-redeem-v404">
                <span class="till-cart-qty">
                  <button type="button" class="btn ghost" data-manual-qty-v404="-1" data-reward-v404="${idV404}" aria-label="Reduce quantity">−</button>
                  <output aria-label="Quantity" data-manual-qty-out-v404="${idV404}">${qtyV404}</output>
                  <button type="button" class="btn ghost" data-manual-qty-v404="1" data-reward-v404="${idV404}" aria-label="Increase quantity">+</button>
                </span>
                <button type="button" class="btn primary sm" data-manual-redeem-v404="${idV404}" data-name-v404="${esc(gift.name||'Reward')}" data-cost-v404="${esc(String(Number(gift.cost_units)||0))}" data-unit-v432="${esc(unitV432)}">Redeem</button>
              </span>`
            :'<span class="pill ok">Ready</span>';
          return `<div class="till-tier-benefit-row-v369">
            <span><b class="small" data-merchant-content>${esc(gift.name||'Reward')}</b>
            <span class="muted small">${costV404}</span></span>
            ${actionV404}
          </div>`;
        }).join('')}`).join('')}
        ${nextUpV392?`<div class="till-tier-benefit-row-v369">
            <span><b class="small" data-merchant-content>${esc(nextUpV392.name||'Reward')}</b>
            <span class="muted small">${esc(String(Math.max(0,Number(nextUpV392.remaining_units)||0)))} more ${esc(nextUpV392.unit==='stamps'?'stamps':nextUpV392.unit==='points'?'points':giftUnitV392)}</span></span>
            <span class="pill off">Not yet</span>
          </div>`:''}
        ${/* V399 (owner, photo 3: the wide "Scan customer QR" button crossed out and a small square
           icon drawn beside it, labelled "smaller button"). The control is unchanged — same id,
           same handler, same scan — it is just the compact icon form now, so it stops competing
           with the reward rows it sits under. The accessible name is kept in full: shrinking a
           control must not shrink what a screen reader is told about it. */''}
        ${(affordableV392.length&&canScanRedemption())?`<button type="button" class="btn ghost sm till-gift-scan-v399" id="tGiftScanV392" aria-label="Scan customer QR" title="Scan customer QR">${CUI.icon('scan',{size:18})}</button>`:''}</div>`
      :'';
    const rewards=`${welcomeBanner}${bringbackBanner}${referralBanner}${tierBanner}${redemptionOffHintV435}${giftsBannerV392}${pendingVouchers}`;
    /* V374: what the Benefits tab counts. An automatic discount is NOT counted — nobody has to
       do anything about it — so the badge means "this many things need a hand", which is the
       only reading that would make a cashier open the tab. */
    /* V392: an affordable gift needs a hand (a scan), so it counts; the "not yet" row does not. */
    const count=giveNow.length+(welcomeOffer?1:0)+(bringbackOffer?1:0)+(catalog.customerVouchers||[]).length
      +affordableV392.length;
    return {html:rewards?`<div class="till-rewards-v373">${rewards}</div>`:'',count};
  }
  /* The whole ladder, on demand: what is available now, and — in plain words — why the rest is
     not. Staff get asked this at the counter; the answer belongs somewhere, just not in the way
     of the sale. */
  function openTillAllBenefitsV373(){
    const payload=catalog?.customerTierBenefits;
    const benefits=Array.isArray(payload?.benefits)?payload.benefits:[];
    if(!benefits.length)return toast('This customer has no tier benefits yet.');
    const autoBenefit=tillAutoTierDiscountV373(benefits);
    const rows=benefits.map(benefit=>{
      const status=benefit===autoBenefit?'<span class="pill ok">Automatic</span>'
        :benefit.claimable_now!==false?'<span class="pill new">Available now</span>'
        :benefit.blocked_reason==='not_birthday_month'?'<span class="pill off">Birthday month only</span>'
        :benefit.blocked_reason==='used_up'?'<span class="pill off">Used up</span>'
        :'<span class="pill off">Not available</span>';
      return `<div class="till-tier-benefit-row-v369">
        <span><b class="small">${esc(benefit.sentence||benefit.label||'Benefit')}</b>
        <span class="muted small">${tillBenefitLimitTextV373(benefit)}</span></span>${status}</div>`;
    }).join('');
    document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="tillAllBenefitsModalV373" role="dialog" aria-modal="true" aria-labelledby="tillAllBenefitsTitleV373" tabindex="-1"><div class="modal-card" style="max-width:520px">
      <div class="row"><div><h2 id="tillAllBenefitsTitleV373">${esc(payload?.tier?.label||'Tier')} benefits</h2><p class="muted small">Everything this customer's tier includes, and what can be given today.</p></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="tillAllBenefitsCloseV373">Close</button></div>
      <div class="till-tier-benefits-v369" style="display:block;margin-top:6px">${rows}</div>
    </div></div>`);
    const node=$('tillAllBenefitsModalV373');
    let deactivate;
    const close=()=>{if(deactivate)deactivate();else node.remove()};
    deactivate=CUI.activateDialog(node,{onClose:close,initialFocus:'#tillAllBenefitsCloseV373'});
    $('tillAllBenefitsCloseV373').onclick=close;
  }

  /* V404 — manual, no-QR redemption. The owner accepted the trade-off explicitly: a QR proved the
     customer was standing there, and nothing here can. What replaces it is evidence, so this
     dialog is deliberately heavier than the scan it substitutes for — it names everything the
     audit row will carry, and it will not confirm without a reason.
     It decides NOTHING: eligibility, balance, limits and the ledger all belong to
     app.redeem_reward_core, reached through staff_manual_redeem_reward_v404, which re-derives the
     permission server-side. The figures below are the ones already on screen, restated. */
  const TILL_MANUAL_REDEEM_MAX_V404=20;
  /* V408 (owner, photo 1: "when press redeem it must reduce the points immediately"). The header's
     "Diamond · 75,937 pts" comes from `cust`, which is the lookup_client_by_phone answer captured
     when the customer was found — redeeming never touched it, so the figure stayed at what it was
     before the spend. Only the catalogue was being refetched.
     The new balance is ASKED FOR, never worked out here: this re-runs the same lookup and takes
     the server's number. Subtracting the cost client-side would be inventing a balance, which is
     exactly what v145 forbids, and it would be wrong the moment anything else moved the ledger.
     The client_id guard means a stale or re-typed number can never swap the customer under the
     cashier while a sale is open. */
  async function refreshTillCustomerStandingV408(){
    const lookupPhone=String(cust?.phone||phone||'').trim();
    if(!lookupPhone||!cust?.client_id)return;
    const {data,error}=await sb.rpc('lookup_client_by_phone',{p_business:S.biz.id,p_phone:lookupPhone});
    if(error||!isTillCurrent())return;
    if(data?.status==='found'&&String(data.client_id)===String(cust.client_id))cust=data;
  }
  function openManualRedeemConfirmV404({rewardId,rewardName,costUnits,quantity,rewardUnit}){
    /* V432: the clicked reward's own unit when the server sent one — a points gift in a mixed
       tenant must not be priced in stamps by the programme-wide noun. The programme unit stays
       the fallback so this dialog keeps working against an older payload. */
    const unit=rewardUnit==='stamps'||rewardUnit==='points'
      ?rewardUnit
      :(catalog?.customerGiftsV392?.program?.unit==='stamps'?'stamps':'points');
    const qty=Math.max(1,Math.min(TILL_MANUAL_REDEEM_MAX_V404,Number(quantity)||1));
    const total=(Number(costUnits)||0)*qty;
    const balanceNow=Number(cust?.points);
    const branchName=accessibleTillBranches.find(branch=>branch.id===tillBranchId)?.name||'';
    const staffName=(tillRoster.find(person=>person.id===tillSaleStaffId)||{}).full_name||'';
    const row=(label,value)=>`<div class="till-tier-benefit-row-v369"><span><b class="small">${esc(label)}</b></span><span class="muted small" data-merchant-content>${esc(value)}</span></div>`;
    document.getElementById('manualRedeemModalV404')?.remove();
    document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="manualRedeemModalV404" role="dialog" aria-modal="true" aria-labelledby="manualRedeemTitleV404" tabindex="-1"><div class="modal-card" style="max-width:var(--dialog-w-md)">
      <div class="row"><div><h2 id="manualRedeemTitleV404" style="font-size:16px">Redeem without the customer's QR</h2>
        <p class="muted small" style="margin-top:4px">This is recorded as a manual redemption, with your name against it.</p></div>
        <span class="spacer"></span><button type="button" class="btn ghost sm" id="manualRedeemCloseV404">Close</button></div>
      <div class="till-tier-benefits-v369" style="display:block;margin-top:10px">
        ${row('Customer',cust?.full_name||'')}
        ${row('Reward',rewardName)}
        ${row('Quantity',String(qty))}
        ${row(`Cost`,`${total} ${unit}${qty>1?` (${Number(costUnits)||0} × ${qty})`:''}`)}
        ${Number.isFinite(balanceNow)?(unit==='stamps'
          /* nestly_v430: a stamp gift is claimed against the COMPLETED CARD — app.redeem_reward_core
             writes a milestone claim and closes the cycle, consumes_balance=false, so the stamp
             count is NOT deducted. The old line subtracted the cost and promised "759 (now 764)",
             a balance the server never produces (go-live battery, 2026-08-22). Points keep the
             debit projection; the server does debit those. */
          ?row('Stamps after',`${balanceNow} — a completed card is used, stamps are not deducted`)
          :row('Points after',`${balanceNow-total} (now ${balanceNow})`)):''}
        ${branchName?row('Branch',branchName):''}
        ${staffName?row('Staff',staffName):''}
      </div>
      <div style="margin-top:14px">
        <label for="manualRedeemReasonV404">Why is this being redeemed without the QR?</label>
        <select id="manualRedeemReasonV404">
          <option value="customer_unable_to_show_qr">Customer unable to show QR</option>
          <option value="other">Other</option>
        </select>
        <div id="manualRedeemNoteWrapV404" hidden style="margin-top:10px">
          <label for="manualRedeemNoteV404">Say what happened</label>
          <input id="manualRedeemNoteV404" type="text" autocomplete="off" maxlength="200" placeholder="Required when you choose Other">
        </div>
      </div>
      <p class="muted small" id="manualRedeemStatusV404" role="status" aria-live="polite" style="margin-top:10px"></p>
      <div class="row" style="margin-top:12px;gap:8px;flex-wrap:wrap">
        <button type="button" class="btn ghost sm" id="manualRedeemCancelV404">Cancel</button>
        <button type="button" class="btn sm" id="manualRedeemConfirmV404">Redeem ${qty>1?`${qty} × `:''}${esc(rewardName)}</button>
      </div>
    </div></div>`);
    const node=document.getElementById('manualRedeemModalV404');
    let deactivate;
    const close=()=>{if(deactivate)deactivate();else node.remove()};
    deactivate=CUI.activateDialog(node,{onClose:close,initialFocus:'#manualRedeemReasonV404'});
    document.getElementById('manualRedeemCloseV404').onclick=close;
    document.getElementById('manualRedeemCancelV404').onclick=close;
    const reason=document.getElementById('manualRedeemReasonV404');
    const noteWrap=document.getElementById('manualRedeemNoteWrapV404');
    reason.onchange=()=>{noteWrap.hidden=reason.value!=='other'};
    const status=document.getElementById('manualRedeemStatusV404');
    const confirm=document.getElementById('manualRedeemConfirmV404');
    /* One key per confirmation, held across retries: a network failure that actually landed must
       replay into the SAME redemption rather than spending the customer's points twice. */
    const idemKey=crypto.randomUUID();
    confirm.onclick=async()=>{
      const note=String(document.getElementById('manualRedeemNoteV404')?.value||'').trim();
      if(reason.value==='other'&&!note){status.textContent='Say what happened before confirming.';return}
      confirm.disabled=true;status.textContent='Redeeming…';
      const {data,error}=await sb.rpc('staff_manual_redeem_reward_v404',{
        p_business:S.biz.id,p_client:cust.client_id,p_reward:rewardId,p_quantity:qty,
        p_branch:tillBranchId||null,p_reason_code:reason.value,
        p_reason_note:note||null,p_idempotency_key:idemKey});
      if(!isTillCurrent())return;
      if(error){
        confirm.disabled=false;
        const message=String(error?.message||'');
        if(message.includes('is not permitted'))return void(status.textContent='You do not have permission to redeem without the customer\u2019s QR. Ask an owner or manager.');
        /* No interpolation here on purpose: the stepper already clamps to the same constant the
           server enforces, so this branch can only be reached by a hand-built call, and a bare
           sentence keeps this off the v97 unreviewed-runtime-copy surface. */
        if(message.includes('manual_redeem_quantity_out_of_range'))return void(status.textContent='That quantity is out of range.');
        if(message.includes('manual_redeem_reason'))return void(status.textContent='A reason is required.');
        if(error?.code==='PGRST202'||error?.code==='42883')return void(status.textContent='Manual redemption needs the latest Peekaa service update.');
        status.textContent=humanErrorV295(error,'That redemption could not be completed. Nothing was changed.');
        return;
      }
      close();
      toast(data?.status==='duplicate_ignored'?'Already redeemed':`${rewardName} redeemed`);
      tillManualQtyV404={};
      catalog=null;
      await refreshTillCustomerStandingV408();
      draw();
    };
  }

  /* ------------------------------------------------------------------------ stage 1: items */
  function tillItemsStageHtmlV373(){
    if(catalogError)
      return `<div class="err" role="alert">${esc(catalogError)}</div><button class="btn ghost sm" id="tCatRetry" style="margin-top:8px">${CUI.icon('retention',{size:16})} Try again</button>${tillLeaveRowV373()}`;
    if(!catalog)
      return `<p class="muted small" role="status">Loading products and services for this branch…</p>${tillLeaveRowV373()}`;
    /* V374: the three sections became three tabs. Each tab reports how much is waiting in it, so
       a ready reward or an unused package is visible WITHOUT opening the tab — otherwise moving
       them off the page would hide the very things a counter must not miss. */
    const packagesReady=(walkin?[]:(catalog.customerPackages||[])).filter(item=>Number(item.remaining)>0).length;
    const rewards=tillRewardsBlockV373();
    const tabs=[
      {key:'items',label:'Items',count:0},
      {key:'packages',label:'Packages',count:packagesReady},
      /* V399 (owner, photos 2 and 3: "Benefits" struck through on the tab strip, "Rewards"
         written above it, on both screenshots). The tab holds point gifts, welcome and
         bring-back offers and reward vouchers as well as tier benefits, so "Rewards" was
         already the truer word for what is inside it. The state key stays 'benefits' —
         renaming that would only churn every reader of tillItemsTabV374 for no gain. */
      {key:'benefits',label:'Rewards',count:rewards.count}
    ].filter(tab=>!(walkin&&tab.key!=='items'));
    if(!tabs.some(tab=>tab.key===tillItemsTabV374))tillItemsTabV374='items';
    const active=tillItemsTabV374;
    const strip=tabs.length>1
      ?`<div class="v150-segment section-subtabs-v200 till-stage-tabs-v374" role="group" aria-label="What to work on">${tabs.map(tab=>`<button type="button" data-till-stage-tab-v374="${tab.key}" aria-pressed="${tab.key===active}">${tab.label}${tab.count?`<span class="till-stage-tab-count-v374">${tab.count}</span>`:''}</button>`).join('')}</div>`
      :'';
    const panel=active==='packages'?tillPackagesPanelHtmlV374()
      :active==='benefits'?tillBenefitsPanelHtmlV374(rewards)
      :tillItemsPanelHtmlV374();
    return `${strip}
      <div class="till-stage-panel-v374">${panel}</div>
      <div id="tcErr"></div>
      ${cart.length?tillStickyCartHtmlV373():`<div class="empty" style="padding:22px 8px"><div>${CUI.icon('sales',{size:28})}</div><p class="muted small" style="margin-top:8px">Nothing added yet. Tap what the customer had.</p></div>`}
      ${tillLeaveRowV373()}`;
  }
  /* Tab 1 — what they had today: the services and products tapped most often, and one door to
     the rest of the catalogue. */
  function tillItemsPanelHtmlV374(){
    const noCheckoutItems=!catalog.services.length&&!(catalog.products&&catalog.products.length);
    /* Services lead because that is what most of these firms sell; a shop with only products —
       a cafe, a chicken-rice stall — simply gets its products in the quick grid instead. */
    const entries=[
      ...catalog.services.map(item=>({type:'service',item})),
      ...(catalog.products||[]).map(item=>({type:'product',item}))
    ];
    /* V392 (owner, photo 1: "only show latest 2 services & products for specified customer", and
       "put search field for services and product").
       Two changes, one screen. The grid leads with what THIS customer last had — a counter is
       usually repeating a regular's usual, and the top of the catalogue is a worse guess than
       their own history. Ids come from their sale_items; the name and price still come from the
       checkout catalogue, so an item withdrawn from this branch cannot reappear through history.
       With no history (a first visit, a walk-in) it falls back to the catalogue order it always
       used, because "latest" of nothing is not an empty grid.
       The search reaches the WHOLE catalogue, not just what the grid is showing — otherwise it
       would only ever find the four tiles already on screen. When a search is typed the "latest"
       preference steps aside: the owner is looking for something specific. */
    const queryV392=tillItemSearchV392.trim().toLowerCase();
    const rankV392=(list,ids)=>{
      const order=new Map((ids||[]).map((id,index)=>[String(id),index]));
      return [...list].sort((a,b)=>{
        const left=order.has(String(a.item.id))?order.get(String(a.item.id)):Number.MAX_SAFE_INTEGER;
        const right=order.has(String(b.item.id))?order.get(String(b.item.id)):Number.MAX_SAFE_INTEGER;
        return left-right;
      });
    };
    const matchesV392=entry=>!queryV392||String(entry.item.name||'').toLowerCase().includes(queryV392);
    const allServicesV392=entries.filter(entry=>entry.type==='service');
    const allProductsV392=entries.filter(entry=>entry.type==='product');
    /* nestly_v411: bundles join the grid and the search. They are NOT put through rankV392 —
       that ranks by this customer's own sale_items history, and a bundle is expanded into its
       member services on the way into the cart, so a bundle id never appears in that history and
       every bundle would rank last for ever. They are ordered by name (the order the read asked
       for) and capped by the same per-kind ceiling the other two groups use. */
    const allBundlesV411=(catalog.bundles||[]);
    const pickV392=(list,ids)=>queryV392
      ?list.filter(matchesV392)
      :rankV392(list,ids).slice(0,TILL_RECENT_PER_KIND_V392);
    const shownServices=pickV392(allServicesV392,catalog.recentServiceIdsV392);
    const shownProducts=pickV392(allProductsV392,catalog.recentProductIdsV392);
    const shownBundles=queryV392
      ?allBundlesV411.filter(bundle=>String(bundle.name||'').toLowerCase().includes(queryV392))
      :allBundlesV411.slice(0,TILL_RECENT_PER_KIND_V392);
    const shown=[...shownServices,...shownProducts];
    /* The hint counts what is genuinely still behind More items, bundles included — it under-read
       by every bundle the firm had before they were on this grid at all. */
    const hiddenCount=(entries.length+allBundlesV411.length)-(shown.length+shownBundles.length);
    const usingHistoryV392=!queryV392&&((catalog.recentServiceIdsV392||[]).length>0||(catalog.recentProductIdsV392||[]).length>0);
    /* The More items tile is rendered even when this branch has no checkout catalogue at all: a
       firm that only sells prepaid packages still has something to add, and hiding the only door
       to the sheet would strand it. */
    const addTile=`<button type="button" class="choice-button till-add-tile-v373" id="tAddItemV373">${CUI.icon('add',{size:20})}<span class="till-choice-text"><b>More items</b><span class="muted small">Everything else</span></span></button>`;
    if(noCheckoutItems)
      return `${CUI.emptyState({iconName:'till',title:'No checkout items at this branch',body:'Ask the owner to make a product or service available in Settings → Checkout catalogue.'})}
        <div class="till-cart-catalog till-quick-grid-v373">${addTile}</div>`;
    return `<div class="till-quick-head-v373"><b class="small">What did they use or buy today?</b>${/* V399 (owner, photo 2: the "What they had last" caption struck out). The grid still leads
        with this customer's own history — only the label describing it is gone, because the tiles
        are self-evident and the caption was competing with the question above it. The
        "N more under More items" hint is a different sentence, was not marked, and stays. */''}${(!usingHistoryV392&&hiddenCount>0)?`<span class="muted small">${hiddenCount} more under More items</span>`:''}</div>
      <div class="till-item-search-v392">
        <label class="sr-only" for="tillItemSearchV392">Search services, products and bundles</label>
        <input id="tillItemSearchV392" type="search" autocomplete="off" placeholder="Search services, products and bundles" value="${esc(tillItemSearchV392)}" ${cartLocked()?'disabled':''}>
      </div>
      ${(queryV392&&!shown.length)?`<p class="muted small" style="margin:10px 0">Nothing in this branch's checkout catalogue matches “${esc(tillItemSearchV392)}”. Try More items, or type an amount below.</p>`:''}
      ${tillQuickGroupsHtmlV373(shownServices,shownProducts,shownBundles)}
      <div class="till-cart-catalog till-quick-grid-v373">${addTile}</div>
      ${tillManualAmountRowHtmlV375()}`;
  }
  /* V375 (owner, photo 4: "put a manually add amount field", arrow into the space under the
     item grid). The amount the customer paid is often the ONLY thing the counter knows — a
     one-off job, a price agreed on the spot — and typing it was two taps deep, inside More items
     → Other item. It is now on the first screen, and it is the SAME addCustomLine the sheet's tab
     calls: one custom-line path, one server validation (custom_line_denied / custom_line_limit /
     custom_line_invalid), so nothing about who may type a price or what the server accepts is
     changed by moving the field. Owner and manager only, for exactly that reason. */
  function tillManualCanTypeAmountV375(){return S.myRole==='owner'||S.myRole==='manager'}
  function tillManualAmountRowHtmlV375(){
    if(!tillManualCanTypeAmountV375())return '';
    return `<div class="till-manual-amount-v375" data-till-manual-amount-v375>
      <label for="tillManualAmountV375"><b class="small">Or type an amount</b></label>
      <div class="row" style="gap:8px;align-items:flex-end;flex-wrap:wrap;margin-top:6px">
        <div><span class="muted small">${esc(S.biz?.currency||'SGD')}</span>
          <input id="tillManualAmountV375" type="number" inputmode="decimal" step="0.01" placeholder="0.00" style="max-width:140px" ${cartLocked()?'disabled':''}></div>
        <div style="flex:1;min-width:min(100%,200px)"><label class="muted small" for="tillManualReasonV375">What was it? (optional)</label>
          <input id="tillManualReasonV375" type="text" maxlength="120" placeholder="e.g. touch-up" ${cartLocked()?'disabled':''}></div>
        <button type="button" class="btn sm" id="tillManualAddV375" ${cartLocked()?'disabled':''}>Add</button>
      </div>
      <p class="muted small" style="margin-top:6px">Adds a one-off line to this sale. It earns whatever your programmes award, the same as any other item.</p>
    </div>`;
  }
  function wireTillManualAmountV375(root){
    const button=root?.querySelector?.('#tillManualAddV375');
    if(!button)return;
    const amountField=root.querySelector('#tillManualAmountV375');
    const reasonField=root.querySelector('#tillManualReasonV375');
    const submit=()=>{
      const cents=Math.round(Number(amountField?.value||'')*100);
      if(!Number.isFinite(cents)||cents===0)return toast('Type an amount first.');
      addCustomLine(cents,String(reasonField?.value||'').trim());
      if(amountField)amountField.value='';
      if(reasonField)reasonField.value='';
    };
    button.onclick=submit;
    if(amountField)amountField.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();submit()}};
  }
  /* Tab 2 — this customer's prepaid sessions, and the one action that sells another. Selling is
     an action rather than a second grid: at a counter, spending a session the customer already
     paid for is far commoner than selling them a new package. */
  function tillPackagesPanelHtmlV374(){
    const owned=tillOwnedPackagesBlockV373();
    const canPkg=branchCanWrite(tillBranchId,'packages')&&!walkin;
    const sellAction=(canPkg&&(catalog.packages||[]).length)
      ?`<button type="button" class="btn ghost" id="tSellPackageV374" style="width:100%;margin-top:14px">${CUI.icon('add',{size:16})} Sell new package</button>`
      :'';
    if(!owned)
      return `${CUI.emptyState({iconName:'packages',title:'No packages yet',body:'This customer has no prepaid sessions left to use.'})}${sellAction}`;
    return `${owned}${sellAction}`;
  }
  /* Tab 3 — only what this sale can actually give. tillRewardsBlockV373 already answers that;
     this tab is where its answer lives instead of trailing the items. */
  function tillBenefitsPanelHtmlV374(rewards){
    const ladder=(!walkin&&Array.isArray(catalog.customerTierBenefits?.benefits)&&catalog.customerTierBenefits.benefits.length)
      ?`<button type="button" class="btn ghost sm" id="tAllBenefitsV373" style="width:100%;margin-top:12px">View all ${esc(catalog.customerTierBenefits?.tier?.label||'tier')} benefits</button>`
      :'';
    if(!rewards.html)
      return `${CUI.emptyState({iconName:'loyalty',title:'Nothing to give on this sale',body:'This customer has no reward, voucher or tier benefit that can be given right now.'})}${ladder}`;
    return `${rewards.html}${ladder}`;
  }
  /* The cart is always in view: the owner's rule is that staff must never scroll to find it.
     Every figure in it is the evaluation's — this bar computes nothing but the item count. */
  function tillStickyCartHtmlV373(){
    const hasSale=cartSaleLines().length>0;
    const count=cart.reduce((sum,line)=>sum+(isCartSaleLine(line)?Number(line.qty||1):1),0);
    let amount='',saved='';
    if(!hasSale){
      amount=extraLines().length?money(extrasTotalCents()):'';
    }else if(evalState==='evaluating'){
      amount='Checking price…';
    }else if(evalState==='ready'&&evalResult){
      amount=money((svTender?svTender.remaining_due_cents:evalResult.total_cents)+extrasTotalCents());
      if(Number(evalResult.discount_total_cents)>0)saved=`You save ${money(evalResult.discount_total_cents)}`;
    }else if(evalState==='expired'){
      amount='Price check expired';
    }
    return `<div class="till-sticky-cart-v373">
      <div class="till-sticky-figures-v373"><b>${count} item${count===1?'':'s'}${amount?` · ${esc(amount)}`:''}</b>
        ${saved?`<span class="ok small">${esc(saved)}</span>`:''}</div>
      <button type="button" class="btn" id="tGoReviewV373">${CUI.icon('forward',{size:20})} Review sale</button>
    </div>`;
  }
  function tillLeaveRowV373(){
    return `<button class="btn ghost sm" id="tBack" style="width:100%;margin-top:10px">${CUI.icon('back',{size:16})} ${walkin?'Switch to customer':'Different number'}</button>`;
  }

  /* ----------------------------------------------------------------------- stage 2: review */
  function tillReviewStageHtmlV373(){
    const hasSale=cartSaleLines().length>0, extras=extraLines(), locked=cartLocked();
    // V257: the one number the customer actually hands over, across both records.
    const collectBaseV257=(hasSale&&evalResult&&evalState!=='error')
      ?(svTender?svTender.remaining_due_cents:evalResult.total_cents):null;
    const combinedTotalV257=(extras.length&&collectBaseV257!=null)
      ?`<div class="ck-panel" style="margin-top:10px" aria-label="Total to collect">
        <div class="ck-total"><span>Total to collect</span><span>${money(collectBaseV257+extrasTotalCents())}</span></div>
        <p class="muted small" style="margin:6px 0 0">Take this once. Today's items and the package are kept as two records so prepaid sessions never count as today's takings — the customer pays one amount.</p>
      </div>`
      :'';
    // tender — needed to finalise a kernel sale; frozen while the cart is locked (retry keeps method)
    /* PayNow QR is customer-bound: the v142 edge command rejects the request unless client_id is a
       uuid (create_paynow -> invalid_request), so it is HIDDEN for a walk-in rather than offered and
       failing at the counter. Cash / card / external PayNow / other are unaffected. */
    const tenderOptions=walkin?cartTenderOptions.filter(([value])=>value!=='paynow_qr'):cartTenderOptions;
    const tenderHtml=(cart.length&&!locked)?`<fieldset style="border:0;padding:0;margin:16px 0 0"><legend style="font-size:13px;font-weight:700">Payment received</legend>
      <div class="frontline-tenders" id="tTenders">${tenderOptions.map(([value,label])=>`<button type="button" class="btn ghost" data-tender="${value}" aria-pressed="${tender===value}">${label}</button>`).join('')}</div>
      ${!hasSale?'<p class="muted small" style="margin-top:6px">No points-earning items in this cart — the tender shows on your receipt only.</p>':''}</fieldset>`:'';
    const paynowHtml=paynowAttempt?`<div class="imp-note" role="status" style="margin-top:12px"><b>PayNow QR · ${money(evalResult?.total_cents||0)}</b><p class="small" style="margin-top:5px">${esc(paynowAttempt.status==='processing'?'Payment is being confirmed.':'Waiting for the customer to pay the locked amount.')}</p><button type="button" class="btn ghost sm" id="tPaynowReopen" style="margin-top:8px">Show QR</button></div>`:'';
    // extras partial-failure panel (kernel already committed — this is the ONLY place a retry runs just the failed extras)
    const partialHtml=checkoutError?`<div class="err" role="alert" style="margin-top:12px"><b>Some steps did not finish</b><p style="margin:4px 0 0">${esc(checkoutError)}</p></div>
      <div class="till-cart-status ${saleCommitted?'ok':''}">${CUI.icon(saleCommitted?'check':'info',{size:16})}<span>${saleCommitted
        ?saleResult?.duplicate
          ?'Sale already recorded earlier · no extra points added'
          :Number(saleResult?.pointsEarned)>0
            ?`Sale recorded · +${Number(saleResult.pointsEarned)} ${tillUnitNounV430(catalog)}`
            :'Sale recorded · no points earned'
        :'No points-earning sale in this cart'}</span></div>
      <button class="btn" id="tRetryGifts" style="width:100%;margin-top:12px;padding:16px">${CUI.icon('retention',{size:20})} Retry unfinished</button>
      <button class="btn ghost sm" id="tFinishPartial" style="width:100%;margin-top:8px">See receipt (with what failed)</button>`:'';
    const actionHtml=(checkoutError||paynowAttempt)?'':checkoutActionHtml();
    /* Points are the server's answer, worked out when the sale is written (record_cart_sale
       returns them and the receipt prints them). evaluate_checkout does not preview them, so
       this screen says what will happen rather than inventing a number. */
    const pointsNote=(!walkin&&hasSale)
      ?`<p class="muted small" style="margin-top:8px">Points are worked out when the sale is recorded — the receipt shows exactly how many were earned.</p>`
      :'';
    /* V468-B: owner struck "Different number" on the Confirm sale step (photo) — no
       ${tillLeaveRowV373()} here any more. The route it served still exists one tap away via
       "Add more items" -> the items stage, which keeps its own tillLeaveRowV373() back-to-keypad
       button, so removing it here does not strand the cashier. */
    return `<b class="small till-review-head-v373">Confirm sale</b>
      ${tillCartLinesHtmlV373()}
      ${checkoutPanelHtml()}
      ${tillExtrasHtmlV373()}
      ${combinedTotalV257}
      ${pointsNote}
      <div id="tcErr"></div>
      ${tenderHtml}
      ${paynowHtml}
      ${partialHtml}
      ${actionHtml}
      ${locked?'':`<button class="btn ghost sm" id="tBackToItemsV373" style="width:100%;margin-top:10px">${CUI.icon('back',{size:16})} Add more items</button>`}`;
  }
  // sale lines (service/product/custom) — per-line CATALOG prices for browsing only; the payable
  // figures live in the checkout panel (evaluation-authoritative).
  function tillCartLinesHtmlV373(){
    const saleLines=cartSaleLines();
    const locked=cartLocked();
    if(!saleLines.length)return '';
    return `<ul class="till-cart-lines">${saleLines.map(l=>{
      const badge=l.type==='custom'?`<span class="till-cart-line-sub">Other item${l.reason?` · ${esc(l.reason)}`:''}</span>`:'';
      const qtyCtl=locked?'':`<div class="till-cart-qty">
        <button type="button" class="btn ghost" data-qty="-1" data-line="${l.lineId}" aria-label="Reduce quantity">−</button>
        <output aria-label="Quantity">${l.qty}</output>
        <button type="button" class="btn ghost" data-qty="1" data-line="${l.lineId}" aria-label="Increase quantity">+</button></div>`;
      const rm=locked?'':`<button type="button" class="btn ghost sm" data-remove="${l.lineId}" ${workspaceTemplateAttributeV97('aria-label','removeItem',{item:l.label})}>${CUI.icon('close',{size:16})}</button>`;
      return `<li class="till-cart-line"><span class="till-cart-line-label">${esc(l.label)}${l.qty>1?` ×${l.qty}`:''}${badge}</span>${qtyCtl}<span class="till-cart-line-amount">${money(l.unit_cents*l.qty)}</span>${rm}</li>`;
    }).join('')}</ul>`;
  }
  /* extras (package / membership) — charged as their OWN records, NOT part of the kernel total,
     so the panel TOTAL keeps matching the evaluation exactly.
     V257 (owner: "why is the session charged separately? cannot together?"). The split is
     deliberate and stays: sell_package_v102 writes a sales row of kind='package' that carries
     its own prepaid entitlement and is judged by that kind's own revenue/visit/points policy,
     while the cart finalises as kind='quick_sale' with sale_items. Merging them would file a
     prepaid package as today's takings. What was wrong was the WORDS: "charged separately"
     reads as "ask the customer to pay twice". It is one payment, two receipts. */
  function tillExtrasHtmlV373(){
    const extras=extraLines();
    const locked=cartLocked();
    if(!extras.length)return '';
    return `<div style="margin-top:14px"><b class="small">Also on this bill · kept as its own receipt</b>
      <ul class="ck-extras">${extras.map(l=>{
        const succeeded=l._status==='issued'||l._status==='done';const failed=l._status==='failed';
        const rm=locked?'':`<button type="button" class="btn ghost sm" data-remove="${l.lineId}" ${workspaceTemplateAttributeV97('aria-label','removeItem',{item:l.label})} style="margin-left:8px">${CUI.icon('close',{size:16})}</button>`;
        return `<li><span>${esc(l.label)}<span class="ck-extra-note">${extraLineBadge(l,succeeded,failed)}</span></span><span style="display:inline-flex;align-items:center;gap:6px">${money(l.unit_cents*l.qty)}${rm}</span></li>`;
      }).join('')}</ul></div>`;
  }

  /* -------------------------------------------------------------------- the Add item sheet */
  /* Everything that is not tapped every few minutes lives here, one tap from the sale, grouped
     by what it IS rather than by which workflow it used to belong to. Selling a package is a
     tab; using one is a tab; neither is a separate journey any more. */
  const TILL_SHEET_TABS_V373=[
    {key:'services',label:'Services'},
    {key:'products',label:'Products'},
    {key:'usepackage',label:'Use package'},
    {key:'sellpackage',label:'Sell package'},
    {key:'membership',label:'Memberships'},
    {key:'custom',label:'Other item'}
  ];
  function tillSheetTabsV373(){
    if(!catalog)return [];
    // Packages and memberships are sold TO a customer (sell_package_v102 / enroll_membership_v41 both
    // take p_client) — structurally impossible for a walk-in, so the tabs are absent, not disabled.
    const canPkg=branchCanWrite(tillBranchId,'packages')&&!walkin;
    const canMem=branchCanWrite(tillBranchId,'memberships')&&!walkin;
    // §6 custom-price ('Other item') entry is OWNER AND MANAGER ONLY (Option A). This is a role,
    // not an individually grantable permission. The server enforces it (custom_line_denied).
    const canCustomLine=S.myRole==='owner'||S.myRole==='manager';
    const available={
      services:catalog.services.length>0||(catalog.bundles||[]).length>0,
      products:(catalog.products||[]).length>0,
      usepackage:!walkin&&(catalog.customerPackages||[]).some(item=>Number(item.remaining)>0),
      sellpackage:canPkg&&(catalog.packages||[]).length>0,
      /* V466: staff cannot enrol a customer into a membership at checkout while the module is
         gated — same UNVERIFIED_MODULES_V466 flag as the router refusal and the grow tile. */
      membership:canMem&&(catalog.memberships||[]).length>0&&!UNVERIFIED_MODULES_V466.includes('memberships'),
      custom:canCustomLine
    };
    return TILL_SHEET_TABS_V373.filter(tab=>available[tab.key]);
  }
  function openTillAddSheetV373(preferredTab){
    if(cartLocked())return;
    const tabs=tillSheetTabsV373();
    if(!tabs.length)return toast('There is nothing to add at this branch yet.');
    tillAddSheetV373={tab:tabs.some(tab=>tab.key===preferredTab)?preferredTab:tabs[0].key,query:''};
    document.body.insertAdjacentHTML('beforeend',`<div class="modal till-add-sheet-v373" id="tillAddSheetV373" role="dialog" aria-modal="true" aria-labelledby="tillAddSheetTitleV373" tabindex="-1"><div class="modal-card">
      <div class="row"><div><h2 id="tillAddSheetTitleV373">Add item</h2><p class="muted small">Tap to add. The sale stays open behind this.</p></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="tillAddSheetCloseV373">Done</button></div>
      <div id="tillAddSheetBodyV373"></div>
    </div></div>`);
    const node=$('tillAddSheetV373');
    let deactivate;
    const close=(options)=>{tillAddSheetV373=null;if(deactivate)deactivate(options);else node.remove()};
    deactivate=CUI.activateDialog(node,{onClose:close,initialFocus:'#tillAddSheetCloseV373'});
    node._closeV373=close;
    $('tillAddSheetCloseV373').onclick=close;
    paintTillAddSheetV373();
  }
  function closeTillAddSheetV373(options){
    const node=$('tillAddSheetV373');
    tillAddSheetV373=null;
    if(!node)return;
    if(typeof node._closeV373==='function')node._closeV373(options);else node.remove();
  }
  function paintTillAddSheetV373(){
    const body=$('tillAddSheetBodyV373');
    if(!body||!tillAddSheetV373)return;
    const tabs=tillSheetTabsV373();
    if(!tabs.length)return closeTillAddSheetV373();
    if(!tabs.some(tab=>tab.key===tillAddSheetV373.tab))tillAddSheetV373.tab=tabs[0].key;
    const active=tillAddSheetV373.tab;
    const query=(tillAddSheetV373.query||'').trim().toLowerCase();
    const match=item=>!query||String(item.name||'').toLowerCase().includes(query);
    const searchable=active==='services'||active==='products';
    let panel='';
    if(active==='services'){
      const services=catalog.services.filter(match);
      const bundles=(catalog.bundles||[]).filter(match);
      panel=`${services.length?`<div class="till-cart-catalog">${tillCatalogueTilesV373(services.map(item=>({type:'service',item})))}</div>`:'<p class="muted small">No services match.</p>'}
        ${bundles.length?`<b class="small" style="display:block;margin-top:14px">Bundles</b><div class="till-cart-catalog">${tillBundleTilesV373(bundles)}</div>
          <p class="muted small" style="margin-top:6px">A bundle adds each of its services at the bundle price.</p>`:''}`;
    }else if(active==='products'){
      const products=(catalog.products||[]).filter(match);
      panel=products.length
        ?`<div class="till-cart-catalog">${tillCatalogueTilesV373(products.map(item=>({type:'product',item})))}</div>`
        :'<p class="muted small">No products match.</p>';
    }else if(active==='usepackage'){
      panel=tillOwnedPackagesBlockV373({inSheet:true});
    }else if(active==='sellpackage'){
      panel=`<p class="muted small" style="margin:0 0 8px">Use only when the customer is buying a prepaid package.</p>
        <div class="till-cart-catalog">${tillPackagePlanTilesV373(catalog.packages||[])}</div>
        <p class="muted small" style="margin-top:8px">${catalog.packageEarnsPoints===true
          ?'Package purchases are eligible for points once at purchase when an active published loyalty programme applies.'
          :catalog.packageEarnsPoints===false
            ?'Package purchases are not eligible for points for this business.'
            :'Package points setting is unavailable. The completed sale receipt will show the server-confirmed points result.'} Using a session never earns points.</p>`;
    }else if(active==='membership'){
      panel=`<div class="till-cart-catalog">${(catalog.memberships||[]).map(p=>`<button type="button" class="choice-button" data-plan="membership" data-id="${esc(p.id)}"><span class="till-choice-text"><b>${esc(p.name)}</b><span class="till-cart-price">${money(p.unit_cents)}</span></span></button>`).join('')}</div>`;
    }else{
      panel=`<button type="button" class="btn ghost" id="tCustomOpen" style="width:100%">${CUI.icon('add',{size:16})} Add other item</button>
        <p class="muted small" style="margin:8px 0 0">A one-off charge that isn't in your catalogue. Custom prices — owner and manager only.</p>`;
    }
    body.innerHTML=`<div class="v150-segment section-subtabs-v200 till-sheet-tabs-v373" role="group" aria-label="What to add">${tabs.map(tab=>`<button type="button" data-till-tab-v373="${tab.key}" aria-pressed="${tab.key===active}">${esc(tab.label)}</button>`).join('')}</div>
      ${searchable?`<label class="sr-only" for="tillAddSearchV373">Search this list</label>
        <input id="tillAddSearchV373" type="search" placeholder="Search" value="${esc(tillAddSheetV373.query||'')}">`:''}
      <div class="till-sheet-panel-v373">${panel}</div>`;
    body.querySelectorAll('[data-till-tab-v373]').forEach(button=>button.onclick=()=>{
      tillAddSheetV373.tab=button.dataset.tillTabV373;tillAddSheetV373.query='';paintTillAddSheetV373();
    });
    const search=$('tillAddSearchV373');
    if(search){
      const hadFocus=document.activeElement===search;
      search.oninput=()=>{
        tillAddSheetV373.query=search.value;
        paintTillAddSheetV373();
        const next=$('tillAddSearchV373');
        if(next){next.focus();next.setSelectionRange(next.value.length,next.value.length)}
      };
      if(hadFocus)search.focus();
    }
    /* The tiles inside the sheet are the same tiles the page renders, so they are bound by the
       same one binder — never a second copy of the handlers. */
    bindTillControlsV373();
  }

  /* --------------------------------------------------------------------------- one binder */
  /* Bound after every render of either stage AND after every repaint of the sheet, because the
     sheet's tiles live on document.body rather than inside the route. Handlers are assigned
     (not added), so re-binding the same node is a no-op rather than a duplicate listener. */
  function bindTillControlsV373(){
    if($('tBack'))$('tBack').onclick=backToPhoneStep;
    if($('tWalkinSwitch'))$('tWalkinSwitch').onclick=backToPhoneStep;
    if($('tGoReviewV373'))$('tGoReviewV373').onclick=()=>{closeTillAddSheetV373();tillStageV373='review';draw()};
    if($('tBackToItemsV373'))$('tBackToItemsV373').onclick=()=>{tillStageV373='items';tillItemsTabV374='items';draw()};
    if($('tAddItemV373'))$('tAddItemV373').onclick=()=>openTillAddSheetV373();
    /* V392: the search redraws the grid as it is typed. The caret is put back where it was —
       draw() replaces the panel, so without this the field would lose focus on every keystroke
       and the counter could type exactly one letter at a time. */
    const tillItemSearchInputV392=$('tillItemSearchV392');
    if(tillItemSearchInputV392)tillItemSearchInputV392.oninput=event=>{
      tillItemSearchV392=event.target.value;
      const at=event.target.selectionStart;
      draw();
      const again=$('tillItemSearchV392');
      if(again){again.focus();try{again.setSelectionRange(at,at)}catch(error){}}
    };
    wireTillManualAmountV375(document);
    if($('tSellPackageV374'))$('tSellPackageV374').onclick=()=>openTillAddSheetV373('sellpackage');
    document.querySelectorAll('[data-till-stage-tab-v374]').forEach(button=>button.onclick=()=>{
      tillItemsTabV374=button.dataset.tillStageTabV374;draw();
    });
    if($('tAllBenefitsV373'))$('tAllBenefitsV373').onclick=openTillAllBenefitsV373;
    const whoV373=$('tillWhoV373');
    if(whoV373)whoV373.ontoggle=()=>{tillWhoOpenV373=whoV373.open};
    if($('tBranch'))$('tBranch').onchange=async()=>{
      tillBranchId=$('tBranch').value;selectedBranchId=tillBranchId;
      /* A branch change invalidates every item and evaluation. Clear the cart, then ask the
         server for this branch's effective catalogue before another selection is possible. */
      closeTillAddSheetV373();
      cart=[];catalog=null;catalogError=null;clearCheckoutState({abandon:true});
      CUI.announce('Branch changed. Checkout catalogue refreshed.');draw();
    };
    /* V287: re-attributing re-renders so the selected teammate is visible on the control that
       set it. The finalise and PayNow idempotency fingerprints already carry tillSaleStaffId, so
       a change of attribution can never replay the previous teammate's sale. */
    if($('tillSaleStaff'))$('tillSaleStaff').onchange=event=>{
      tillSaleStaffId=event.target.value||tillActingStaffId;draw();
    };
    if($('tCatRetry'))$('tCatRetry').onclick=()=>{catalogError=null;catalog=null;draw()};
    document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{
      const type=b.dataset.add, list=type==='service'?catalog.services:catalog.products;
      const item=(list||[]).find(x=>x.id===b.dataset.id);if(item)addCatalogLine(type,item);
    });
    /* V211: spend a session the customer already paid for. useCustomerPackage confirms, calls
       use_package_session_v102 with a stable idempotency key, and is reversible afterwards —
       reversing that session's sale restores it (reverse_sale -> v40_base -> v34_base writes
       package_session_reversals). */
    document.querySelectorAll('[data-use-package]').forEach(b=>b.onclick=()=>
      useCustomerPackage(b.dataset.usePackage));
    /* v215 */
    const welcomeButton=$('tWelcomeRedeemV215');
    if(welcomeButton)welcomeButton.onclick=()=>redeemWelcomeOfferV215();
    /* V362: hand over a bring-back voucher. Deliberately mirrors redeemWelcomeOfferV215's own
       body — same busy guard, same isTillCurrent() re-checks around the await, same cust/
       tillBranchId sources, same catalog=null + draw() refresh. The server re-checks expiry,
       ownership and branch, so this only reports what it decided. */
    const bringbackButton=$('tBringbackRedeemV362');
    if(bringbackButton)bringbackButton.onclick=async()=>{
      const offer=catalog?.customerBringbackOffer;
      if(!offer||busy)return;
      const label=offer.reward_label||'the free item';
      busy=true;
      const {data,error}=await sb.rpc('staff_redeem_bringback_v361',{
        p_business:S.biz.id,p_client:cust.client_id,p_branch:tillBranchId,p_grant:offer.grant_id});
      if(!isTillCurrent())return;
      busy=false;
      if(error)return fail(error);
      if(data?.status!=='completed')return fail(new Error('The bring-back voucher receipt was incomplete. Check the customer before retrying.'));
      toast(workspaceTemplateTextV97('bringbackVoucherGiven',{item:label}));
      catalog=null;
      draw();
    };
    /* nestly_v420: hand over the referral gift. Same shape as the bring-back button above — the
       server owns every decision, this only reports what it decided. */
    const referralButton=$('tReferralRedeemV420');
    if(referralButton)referralButton.onclick=async()=>{
      const offer=catalog?.customerReferralOffer;
      if(!offer||busy)return;
      const label=offer.reward_label||'the free item';
      busy=true;
      const {data,error}=await sb.rpc('staff_redeem_referral_v420',{
        p_business:S.biz.id,p_client:cust.client_id,p_branch:tillBranchId,p_grant:offer.grant_id});
      if(!isTillCurrent())return;
      busy=false;
      if(error)return fail(error);
      if(data?.status!=='completed')return fail(new Error('The referral gift receipt was incomplete. Check the customer before retrying.'));
      toast(workspaceTemplateTextV97('referralGiftGiven',{item:label}));
      catalog=null;
      draw();
    };
    /* V365: give one tier benefit. The idempotency key is per press, so a double-tap on a slow
       connection replays into the SAME issue rather than burning two of the customer's monthly
       allowance; the server answers duplicate_ignored and the count does not move. */
    document.querySelectorAll('[data-tier-benefit-give-v365]').forEach(button=>button.onclick=async()=>{
      if(busy||!cust?.client_id)return;
      const benefitId=button.dataset.tierBenefitGiveV365;
      const label=button.dataset.label||'the benefit';
      busy=true;button.disabled=true;
      const {data,error}=await sb.rpc('staff_issue_tier_benefit_v365',{
        p_business:S.biz.id,p_client:cust.client_id,p_benefit:benefitId,
        p_branch:tillBranchId||null,p_idempotency_key:crypto.randomUUID()});
      if(!isTillCurrent())return;
      busy=false;
      if(error){
        button.disabled=false;
        /* The two refusals staff will actually meet are stated in their own words rather than as
           a raw code — everything else falls through to the standard error surface. */
        const message=String(error?.message||'');
        if(message.includes('tier_benefit_limit_reached'))return toast(workspaceTemplateTextV97('tierBenefitUsedUp',{item:label}));
        if(message.includes('tier_benefit_not_earned'))return toast(workspaceTemplateTextV97('tierBenefitNotEarned',{item:label}));
        /* V367: the two birthday-month refusals, in the counter's own words. */
        if(message.includes('tier_benefit_not_birthday_month'))return toast(workspaceTemplateTextV97('tierBenefitBirthdayOnly',{item:label}));
        if(message.includes('tier_benefit_birthday_unknown'))return toast(workspaceTemplateTextV97('tierBenefitBirthdayUnknown',{item:label}));
        return fail(error);
      }
      toast(workspaceTemplateTextV97(data?.status==='duplicate_ignored'?'tierBenefitAlreadyGiven':'tierBenefitGiven',{item:label}));
      catalog=null;
      draw();
    });
    document.querySelectorAll('[data-add-bundle]').forEach(b=>b.onclick=()=>{
      const bundle=(catalog.bundles||[]).find(x=>x.id===b.dataset.addBundle);
      if(bundle)addBundleLines(bundle);
    });
    document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{
      const type=b.dataset.plan, list=type==='package'?catalog.packages:catalog.memberships;
      const item=(list||[]).find(x=>x.id===b.dataset.id);if(item)addPlanLine(type,item);
    });
    if($('tEntitlementScan'))$('tEntitlementScan').onclick=()=>openMerchantRedemptionScanner({
      businessId:S.biz.id,branchId:tillBranchId,
      isCurrent:isTillCurrent,onComplete:()=>{catalog=null;draw()}
    });
    /* V392: the claimable-gifts banner hands over to the SAME scanner — one redemption path, one
       server confirmation, and the customer is present for it. */
    /* V408: the scan path spent the same points and left the same figure stale. Fixed together —
       one screen, one number, and a cashier cannot be expected to know which door they used. */
    if($('tGiftScanV392'))$('tGiftScanV392').onclick=()=>openMerchantRedemptionScanner({
      businessId:S.biz.id,branchId:tillBranchId,
      isCurrent:isTillCurrent,onComplete:async()=>{catalog=null;await refreshTillCustomerStandingV408();draw()}
    });
    /* V404: the stepper writes the number straight into the <output> rather than re-rendering the
       screen. A full redraw here would move the row under the finger mid-tap, which is exactly the
       jumping the owner complained about elsewhere in this batch. */
    document.querySelectorAll('[data-manual-qty-v404]').forEach(button=>button.onclick=()=>{
      const rewardId=button.dataset.rewardV404;
      const step=Number(button.dataset.manualQtyV404)||0;
      const next=Math.max(1,Math.min(TILL_MANUAL_REDEEM_MAX_V404,(tillManualQtyV404[rewardId]||1)+step));
      tillManualQtyV404[rewardId]=next;
      const out=document.querySelector(`[data-manual-qty-out-v404="${CSS.escape(rewardId)}"]`);
      if(out)out.textContent=String(next);
    });
    document.querySelectorAll('[data-manual-redeem-v404]').forEach(button=>button.onclick=()=>{
      if(busy||!cust?.client_id)return;
      openManualRedeemConfirmV404({
        rewardId:button.dataset.manualRedeemV404,
        rewardName:button.dataset.nameV404||'Reward',
        costUnits:Number(button.dataset.costV404)||0,
        rewardUnit:button.dataset.unitV432||'',
        quantity:tillManualQtyV404[button.dataset.manualRedeemV404]||1
      });
    });
    /* The custom-price dialog replaces the sheet rather than stacking on it: two focus traps on
       screen at once is how a keyboard user gets stuck. */
    if($('tCustomOpen'))$('tCustomOpen').onclick=()=>{
      /* nestly_v438: the v183 hand-off, at the till. closeTillAddSheetV373()'s deactivate
         unwinds its history entry with history.back(), which is ASYNCHRONOUS — the pop used to
         land AFTER openCustomModal() had pushed its own entry, fire the new modal's popstate
         handler, and close the "Other item" form the instant it opened (silently: no error, the
         sheet just vanished). On a fresh business with no catalogue this was the ONLY way to key
         a sale, so the till dead-ended. The outgoing sheet hands its history entry to the
         incoming modal instead — one Back still closes exactly one dialog. */
      const inheritV438=CUI.currentDialogHistoryId();
      closeTillAddSheetV373({handOffHistory:true});
      openCustomModal({inheritHistoryId:inheritV438});
    };
    document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>changeQty(b.dataset.line,parseInt(b.dataset.qty,10)));
    document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeLine(b.dataset.remove));
    document.querySelectorAll('[data-tender]').forEach(button=>button.onclick=()=>{
      tender=button.dataset.tender; // tender is NOT part of the evaluation — do not re-evaluate or rotate the finalise key
      document.querySelectorAll('[data-tender]').forEach(choice=>choice.setAttribute('aria-pressed',String(choice===button)));
      CUI.announce(workspaceTemplateTextV97('itemSelected',{item:button.textContent.trim()}));
    });
    if($('tCartConfirm'))$('tCartConfirm').onclick=doCartCheckout;
    if($('tStaleConfirm'))$('tStaleConfirm').onclick=doCartCheckout;
    if($('tPayRetry'))$('tPayRetry').onclick=doCartCheckout;
    if($('tNewCheckout'))$('tNewCheckout').onclick=startNewCheckout;
    if($('tRefreshEval'))$('tRefreshEval').onclick=refreshEval;
    if($('tRetryGifts'))$('tRetryGifts').onclick=doCartCheckout;
    if($('tPaynowReopen'))$('tPaynowReopen').onclick=()=>renderPaynowDialogV142(paynowAttempt);
    if($('tFinishPartial'))$('tFinishPartial').onclick=()=>finishCartReceipt();
    if($('tSvUse'))$('tSvUse').onclick=applySvTender;
    if($('tSvRemove'))$('tSvRemove').onclick=removeSvTender;
  }
  // v67: bind the customer's stored value to the CURRENT evaluation token. The server sizes the hold
  // (min of the request, the spendable balance, and the bill after discounts) and returns every figure;
  // the panel re-renders from svTender. Requests the full bill total — the server caps it.
  async function applySvTender(){
    if(svBusy||!evalResult||evalState!=='ready'||svTender)return;
    svBusy=true;draw();
    const {data,error}=await sb.rpc('reserve_checkout_sv_tender',{p_business:S.biz.id,
      p_evaluation_id:evalResult.evaluation_id,p_requested_cents:evalResult.total_cents,p_idempotency_key:crypto.randomUUID()});
    if(!isTillCurrent())return;
    svBusy=false;
    if(error){svTender=null;cartErr(isBackendMissing(error)?'Stored value needs the latest system update':(error.message||'Could not apply stored value'));draw();return;}
    svTender={reservation_id:data.reservation_id,reserved_cents:data.reserved_cents,
      remaining_due_cents:data.remaining_due_cents,requested_cents:data.requested_cents};
    draw();
  }
  // Removing stored value re-evaluates the cart: a fresh token orphans the reservation (the server
  // sweep releases it) so the finalise can never silently consume a removed hold.
  function removeSvTender(){svTender=null;refreshEval();}
  function cartErr(msg){const e=$('tcErr');if(e)e.innerHTML=`<div class="err">${esc(msg)}</div>`;else toast(msg)}
  // Deliberate fresh start after a same-key/different-request conflict (§2): mint a NEW finalise key
  // (clear the slot) and re-evaluate the current cart.
  function startNewCheckout(){payError=null;saleCommitted=false;staleConfirm=false;staleReevaluationsV257=0;clearWriteAttempt(FINALISE_SLOT);onSaleLinesChanged();}
  // "Other item" modal — amount + a MANDATORY short reason (3..200). The reason is required by the
  // kernel for custom (unpriced) lines; the amount is sent as amount_cents and re-validated server-side.
  function openCustomModal({inheritHistoryId=0}={}){
    if(cartLocked())return;
    document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="tCustomModal" role="dialog" aria-modal="true" aria-labelledby="tCustomTitle" tabindex="-1"><div class="modal-card" style="max-width:460px">
      <div class="row"><div><h2 id="tCustomTitle">Other item</h2><p class="muted small">A one-off charge that isn't in your catalogue. Owner and manager only.</p></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="tCustomClose">Close</button></div>
      <label for="tCustomAmt">Amount (${S.biz.currency||'SGD'})</label>
      <input id="tCustomAmt" inputmode="decimal" placeholder="0.00" style="font-size:22px;text-align:center;height:52px">
      <p class="muted small" style="margin-top:6px">Use a minus for a correction the other way — <b>-5.00</b> takes $5 off and reduces the points earned to match.</p>
      <label for="tCustomReason">Note (optional)</label>
      <input id="tCustomReason" maxlength="200" placeholder="Leave blank if you are in a hurry">
      <div id="tCustomErr"></div>
      <div class="row" style="margin-top:16px"><button type="button" class="btn" id="tCustomConfirm">${CUI.icon('add',{size:16})} Add item</button><button type="button" class="btn ghost sm" id="tCustomCancel">Cancel</button></div>
    </div></div>`);
    let deactivate;
    const close=()=>{if(deactivate)deactivate();else $('tCustomModal')?.remove();};
    deactivate=CUI.activateDialog($('tCustomModal'),{onClose:close,initialFocus:'#tCustomAmt',inheritHistoryId});
    $('tCustomClose').onclick=$('tCustomCancel').onclick=close;
    const submit=()=>{
      /* V206 (owner: "dont need reason when add item ... for over sold or ad hoc purchase that
         need fast transactions (like negative transaction = minus points away, or positive
         transactions maybe due to under charge)"). A minus sign is now allowed, and the note is
         optional — this control exists to keep a queue moving. The server still records WHO
         keyed it, which is the half of the audit trail that matters, and still refuses to let a
         negative take a sale to zero or below. */
      const raw=($('tCustomAmt').value||'').trim();
      if(!/^-?\d+(?:\.\d{1,2})?$/.test(raw)){$('tCustomErr').innerHTML='<div class="err">Enter dollars and cents, for example 12.50 or -5.00</div>';return;}
      const c=Math.round(Number(raw)*100);
      if(!c||Math.abs(c)>2147483647){$('tCustomErr').innerHTML='<div class="err">Enter an amount other than zero, for example 12.50 or -5.00</div>';return;}
      const reason=($('tCustomReason').value||'').trim();
      if(reason.length>200){$('tCustomErr').innerHTML='<div class="err">Keep the note under 200 characters</div>';return;}
      close();addCustomLine(c,reason);
    };
    $('tCustomConfirm').onclick=submit;
    $('tCustomReason').onkeydown=e=>{if(e.key==='Enter')submit();};
  }

  /* PS-1C.1 FINALISE (step 2 of the kernel journey) + honest extras sequencing.
     Order: (1) ONE record_cart_sale that CONSUMES the evaluation token (p_evaluation_id; p_lines is
     null — the token is authoritative), then (2) one call per package or membership line.
     Idempotency: the finalise reuses ONE
     STABLE key (writeAttemptKey/FINALISE_SLOT) across retries, cleared only on success or an explicit
     cancel/cart-change; each extra carries its own stable uuid `key`. If the kernel finalise fails we
     STOP (no extra attempted) and recover per §2 (stale re-confirm / retry / conflict). If it
     succeeds it is LOCKED (saleCommitted) and never re-run; a retry re-invokes only the failed extras. */
  function readPaynowRequestV142(){try{return JSON.parse(sessionStorage.getItem(PAYNOW_SLOT)||'null')}catch{return null}}
  function writePaynowRequestV142(value){try{sessionStorage.setItem(PAYNOW_SLOT,JSON.stringify(value))}catch{}}
  function clearPaynowRequestV142(){try{sessionStorage.removeItem(PAYNOW_SLOT)}catch{}}
  function closePaynowDialogV142(){
    const modal=$('tPaynowModalV142');if(!modal)return;
    if(typeof modal._deactivate==='function')modal._deactivate();else modal.remove();
  }
  function renderPaynowDialogV142(attempt){
    if(!attempt)return;
    closePaynowDialogV142();
    const branchName=accessibleTillBranches.find(branch=>branch.id===tillBranchId)?.name||'Selected branch';
    const qr=attempt.qr||{};
    document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="tPaynowModalV142" role="dialog" aria-modal="true" aria-labelledby="tPaynowTitleV142" tabindex="-1"><div class="modal-card" style="max-width:500px;text-align:center">
      <div class="row"><div style="text-align:left"><h2 id="tPaynowTitleV142">PayNow · ${money(attempt.amount_cents)}</h2><p class="muted small" data-merchant-content>${esc(S.biz.name)} · ${esc(branchName)}</p></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="tPaynowCloseV142">Close</button></div>
      ${qr.data?`<div id="tPaynowQrV142" role="img" data-merchant-content aria-label="PayNow QR for ${esc(money(attempt.amount_cents))}" style="display:grid;place-items:center;width:min(300px,100%);aspect-ratio:1;margin:18px auto;padding:14px;background:#fff;border:1px solid var(--line);border-radius:14px"></div>`:CUI.loadingState({title:'Waiting for payment confirmation',iconName:'till'})}
      <div class="imp-note" style="text-align:left"><b>Amount locked: ${money(attempt.amount_cents)}</b><p class="small" style="margin-top:5px">The customer cannot change this amount. Keep this screen open until Stripe confirms payment.</p></div>
      <p class="muted small" style="margin-top:10px">Stripe PayNow QRs stay valid for up to 1 hour. This exact total is held for the full QR payment window.</p>
      ${qr.hosted_instructions_url?`<a class="btn ghost" href="${esc(qr.hosted_instructions_url)}" target="_blank" rel="noopener noreferrer" style="margin-top:12px">Open Stripe payment page</a>`:''}
      <p class="muted small" id="tPaynowStatusV142" role="status" aria-live="polite" style="margin-top:14px">${attempt.status==='processing'?'Confirming payment…':'Awaiting payment…'}</p>
    </div></div>`);
    const modal=$('tPaynowModalV142');
    modal._deactivate=CUI.activateDialog(modal,{onClose:()=>modal.remove(),initialFocus:'#tPaynowCloseV142'});
    $('tPaynowCloseV142').onclick=()=>modal._deactivate();
    const qrHost=$('tPaynowQrV142');
    if(qrHost&&qr.data)new QRCode(qrHost,{text:String(qr.data),width:260,height:260,correctLevel:QRCode.CorrectLevel.M});
  }
  function completePaynowReceiptV142(status){
    const lines=(status.server_lines||[]).map(line=>({label:line.name||'Item',qty:Number(line.qty||1),
      amount:Number(line.unit_price_cents||0)*Number(line.qty||1)}));
    doneInfo={receipt:true,name:status.customer_name||'Customer',tender:'PayNow (Stripe verified)',
      saleId:status.sale_id||null,lines,effects:status.applied_effects||[],
      subtotal:Number(status.subtotal_cents||0),discount:Number(status.discount_total_cents||0),
      gst:Number(status.gst_cents||0),total:Number(status.amount_cents||0),extras:[],hasSale:true,extrasTotal:0,
      pointsEarned:Number(status.points_earned||0),pointsTotal:Number(status.points_total||0),
      pointsBalanceConsistent:true,duplicate:false,paymentReference:status.payment_reference||null,
      businessName:status.business_name||S.biz.name,branchName:status.branch_name||'',paidAt:status.paid_at||new Date().toISOString()};
    saleCommitted=true;paynowAttempt=null;clearPaynowRequestV142();
    if(paynowPollTimer){clearTimeout(paynowPollTimer);paynowPollTimer=null;}
    closePaynowDialogV142();checkoutError=null;step=3;draw();
  }
  /* V370: the PayNow poll ran at 2s forever with no visibility gate — a till tablet left on a
     payment screen asked the database 1,800 times an hour whether a QR nobody was showing had
     been paid. It now SUSPENDS while the tab is hidden and resumes the instant it is shown, so
     the payment flow itself is unchanged: no cap, no backoff, no missed terminal state (the
     first poll after resume reads the current status, whatever happened while away). */
  let paynowHiddenResumeV370=null;
  function paynowSuspendedForVisibilityV370(attemptId){
    if(globalThis.document?.visibilityState!=='hidden')return false;
    if(paynowHiddenResumeV370)return true;
    paynowHiddenResumeV370=()=>{
      if(globalThis.document?.visibilityState==='hidden')return;
      document.removeEventListener('visibilitychange',paynowHiddenResumeV370);
      paynowHiddenResumeV370=null;
      /* Only resume a poll that is still wanted: the dialog may have been closed, or the
         attempt cleared, while the tab was away. paynowAttempt is nulled by every terminal
         path (completePaynowReceiptV142, the failure branches, closePaynowDialogV142). */
      if(!isTillCurrent()||!paynowAttempt)return;
      pollPaynowAttemptV142(attemptId);
    };
    document.addEventListener('visibilitychange',paynowHiddenResumeV370);
    return true;
  }
  async function pollPaynowAttemptV142(attemptId){
    if(!attemptId)return;
    if(paynowSuspendedForVisibilityV370(attemptId))return;
    const {data,error}=await sb.rpc('get_pos_paynow_attempt_v142',{p_attempt:attemptId});
    if(!isTillCurrent())return;
    if(error){paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(attemptId),2500);return;}
    if(data.status==='succeeded'){completePaynowReceiptV142(data);return;}
    if(['refund_required','refund_pending'].includes(data.status)){
      if(paynowAttempt)paynowAttempt.status=data.status;
      const statusNode=$('tPaynowStatusV142');if(statusNode)statusNode.textContent=data.status==='refund_pending'
        ?'Stripe accepted the refund request and is still processing it—do not charge this customer again.'
        :'Payment was received, but the sale could not complete. The refund request is being sent—do not charge this customer again.';
      paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(attemptId),3000);return;
    }
    if(data.status==='refund_failed'){
      if(paynowAttempt)paynowAttempt.status=data.status;
      const statusNode=$('tPaynowStatusV142');if(statusNode)statusNode.textContent='Stripe could not complete the automatic refund. Issue a manual refund in Stripe and contact the customer. Do not charge again.';
      paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(attemptId),10000);return;
    }
    if(['failed','canceled','expired','fulfilment_failed','refunded'].includes(data.status)){
      clearPaynowRequestV142();paynowAttempt=null;closePaynowDialogV142();
      payError=null;
      if(step===2&&cust&&cartSaleLines().length)onSaleLinesChanged();else draw();
      const message=data.status==='refunded'
        ?'Stripe confirms the payment was refunded. Start a new checkout only if the customer still wants to pay.'
        :data.status==='expired'?'This QR expired without a confirmed payment. Check the total and create a new QR.'
        :'Payment did not complete. Check the total and create a new QR.';
      cartErr(message);return;
    }
    if(paynowAttempt)paynowAttempt.status=data.status;
    const statusNode=$('tPaynowStatusV142');if(statusNode)statusNode.textContent=data.status==='processing'?'Confirming payment…':'Awaiting payment…';
    paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(attemptId),2000);
  }
  async function beginPaynowPaymentV142(){
    if(extraLines().length)return cartErr('PayNow QR supports the checked sale total only. Complete package or membership purchases separately.');
    let request=readPaynowRequestV142();
    /* The attributed teammate is part of the idempotency fingerprint: changing who is credited is
       a different sale, and must not silently replay the previous attribution. */
    const fingerprint=[S.biz.id,tillBranchId,cust.client_id,tillSaleStaffId||tillStaffId,evalResult.evaluation_id].join(':');
    if(!request||request.fingerprint!==fingerprint)request={fingerprint,idempotency_key:crypto.randomUUID(),
      business_id:S.biz.id,branch_id:tillBranchId,client_id:cust.client_id,staff_id:tillSaleStaffId||tillStaffId,evaluation_id:evalResult.evaluation_id};
    writePaynowRequestV142(request);
    busy=true;const btn=$('tCartConfirm')||$('tPayRetry');if(btn){btn.disabled=true;btn.textContent='Creating QR…'}
    const executed=await sb.functions.invoke('stripe-connect-command',{body:{action:'create_paynow',...request}});
    if(!isTillCurrent())return;
    busy=false;
    if(executed.error||!executed.data?.attempt_id){payError={kind:'retry'};draw();cartErr(executed.data?.message||'PayNow QR could not be created. Retry uses the same payment attempt.');return;}
    request={...request,attempt_id:executed.data.attempt_id};writePaynowRequestV142(request);
    payError=null;paynowAttempt=executed.data;draw();renderPaynowDialogV142(paynowAttempt);
    if(paynowPollTimer)clearTimeout(paynowPollTimer);
    paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(paynowAttempt.attempt_id),800);
  }
  async function resumePaynowPaymentV142(){
    const request=readPaynowRequestV142();
    if(!request||request.business_id!==S.biz.id)return;
    const required=['idempotency_key','branch_id','client_id','staff_id','evaluation_id'];
    if(required.some(key=>!/^[0-9a-f-]{36}$/i.test(String(request[key]||'')))){
      clearPaynowRequestV142();return;
    }
    if(accessibleTillBranches.some(branch=>branch.id===request.branch_id)){
      tillBranchId=request.branch_id;selectedBranchId=request.branch_id;
    }
    busy=true;
    const executed=await sb.functions.invoke('stripe-connect-command',{body:{action:'create_paynow',...request}});
    if(!isTillCurrent())return;
    busy=false;
    if(executed.error||!executed.data?.attempt_id){
      if(/^[0-9a-f-]{36}$/i.test(String(request.attempt_id||''))){
        paynowAttempt={attempt_id:request.attempt_id,status:'checking',expires_at:null,amount_cents:0};
        toast('Payment outcome is still being checked. Do not create another QR yet.');
        paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(request.attempt_id),500);
        return;
      }
      toast('The previous PayNow request is still reserved. Retry when the connection returns; do not create another QR.');
      return;
    }
    writePaynowRequestV142({...request,attempt_id:executed.data.attempt_id});
    paynowAttempt=executed.data;
    renderPaynowDialogV142(paynowAttempt);
    if(paynowPollTimer)clearTimeout(paynowPollTimer);
    paynowPollTimer=setTimeout(()=>pollPaynowAttemptV142(paynowAttempt.attempt_id),500);
  }
  async function doCartCheckout(){
    if(busy)return;
    const saleLines=cartSaleLines(), extras=extraLines(), hasSale=saleLines.length>0;
    if(!cart.length)return cartErr('Add at least one item');
    if(hasSale){
      if(!evalResult||evalState==='evaluating')return cartErr('Wait for the price check to finish');
      if(evalState==='error')return cartErr('Fix the highlighted item before taking payment');
      if(!tender)return cartErr('Choose how the customer paid');
    }
    if(walkin&&extras.length)return cartErr('Packages and memberships need a customer. Switch to a customer to sell them.');
    // Defensive: the PayNow QR tender is not rendered for a walk-in (the v142 command requires a client).
    if(walkin&&tender==='paynow_qr')return cartErr('PayNow QR needs a customer. Take cash, card, external PayNow or other.');
    if(tender==='paynow_qr')return beginPaynowPaymentV142();
    busy=true;checkoutError=null;
    const confirmBtn=$('tCartConfirm')||$('tStaleConfirm')||$('tPayRetry')||$('tRetryGifts');
    if(confirmBtn){confirmBtn.disabled=true;confirmBtn.textContent='Working…'}
    // (1) kernel finalise — only if there is a sale and it is not already committed
    if(hasSale&&!saleCommitted){
      const finaliseKey=writeAttemptKey(FINALISE_SLOT,evalFingerprint()); // stable across retries; new only on a cart/branch change
      // p_client is null for a walk-in — record_cart_sale permits it and returns points_earned 0.
      const {data,error}=await sb.rpc('record_cart_sale',{p_business:S.biz.id,p_client:cust?cust.client_id:null,
        p_branch:tillBranchId,p_staff:tillSaleStaffId||tillStaffId,p_method:tender,p_idempotency_key:finaliseKey,
        p_lines:null,p_evaluation_id:evalResult.evaluation_id,p_paid:true});
      if(!isTillCurrent())return;
      if(error){busy=false;payError=null;return handleFinaliseError(error);}
      // success — including a same-key replay (duplicate_ignored) which is treated as success
      clearWriteAttempt(FINALISE_SLOT);clearExpiry();
      saleCommitted=true;staleConfirm=false;payError=null;
      const duplicate=isReplayResult(data);
      saleResult={duplicate,saleId:data&&data.sale_id||null,pointsEarned:duplicate?0:(data&&data.points_earned||0),
        // A walk-in has no customer and therefore no points balance to report on the receipt.
        pointsTotal:(!walkin&&Number.isFinite(Number(data?.points_total)))?Number(data.points_total):null,
        lines:saleLines.map(l=>({label:l.label,qty:l.qty,amount:l.unit_cents*l.qty,type:l.type})),
        subtotal:evalResult.subtotal_cents,discount:evalResult.discount_total_cents,
        gst:evalResult.gst_cents,total:evalResult.total_cents,effects:(evalResult.applied_effects||[]),
        sv:(data&&data.stored_value)||null};
    }
    // (2) extras — each independent and server-idempotent; failures are collected, not thrown
    let anyExtraFailed=false;
    for(const l of extras){
      if(l._status==='issued'||l._status==='done')continue;
      let res;
      if(l.type==='package')res=await sb.rpc('sell_package_v102',{p_business:S.biz.id,p_client:cust.client_id,
        p_plan:l.ref,p_branch:tillBranchId,p_idempotency_key:l.key});
      else res=await sb.rpc('enroll_membership_v41',{p_business:S.biz.id,p_client:cust.client_id,
        p_plan:l.ref,p_idempotency_key:l.key});
      if(!isTillCurrent())return;
      if(res.error){anyExtraFailed=true;l._status='failed';
        l._error=isBackendMissing(res.error)?'needs the latest system update':(res.error.message||'failed');continue}
      if(l.type==='package'){
        const result=packageSaleResultV102(res.data);
        if(!result){anyExtraFailed=true;l._status='failed';l._error='server receipt was incomplete';continue}
        l._packageResult=result;l._status='done';l._error=null;
      }else{l._status='done';l._error=null}
    }
    busy=false;
    if(anyExtraFailed){
      checkoutError='The sale is safe. Some items could not be completed. Retry to finish just those — nothing is charged twice.';
      draw();return;
    }
    finishCartReceipt();
  }
  /* §2 token lifecycle at FINALISE — each outcome maps to ONE distinct, low-literacy UI state.
     The payable amount is NEVER changed silently: a stale token re-evaluates once and then WAITS
     for an explicit confirm; nothing here loops. */
  async function handleFinaliseError(error){
    const msg=error&&error.message||'', code=error&&error.code;
    if(isBackendMissing(error)){ // kernel not deployed — nothing was charged
      payError=null;evalError={kind:'generic',message:`Checkout needs the latest system update — ask an owner to update ${BRAND.productName}. Nothing was charged.`};evalState='error';draw();return;}
    if(/total_zero_not_supported/.test(msg)){ // fully-discounted cart — typed message, NO re-evaluate
      payError=null;evalError={kind:'zero',message:"Fully discounted carts aren't supported yet — remove a discount or add an item."};evalState='error';draw();return;}
    if((code==='P0001'&&/stale_evaluation/.test(msg))||(code==='22023'&&/\bstale\b/i.test(msg))){ // re-evaluate ONCE, then confirm
      payError=null;staleConfirm=false;
      staleReevaluationsV257+=1;
      /* V257: ONCE means once. A second stale on the same cart is not drift a re-price can settle
         — the server is refusing this cart every time — so stop re-offering the same confirm and
         say so. Nothing was charged (every stale aborts the whole finalise transaction), and the
         cart unlocks so staff can change the items and get a queue moving. */
      if(staleReevaluationsV257>1){
        evalError={kind:'generic',message:'This price could not be locked, so nothing was charged. Take the bundle out of the cart, add its services on their own, and take payment again — and tell an owner this bundle cannot be sold yet.'};
        evalState='error';evalResult=null;clearExpiry();draw();return;}
      const ok=await runEvaluate();
      if(!isTillCurrent())return;
      if(ok===true&&evalState==='ready')staleConfirm=true; // fresh price is shown; wait for an explicit confirm
      draw();return;}
    if(code==='22023'&&/idempotency key conflicts|key conflict/i.test(msg)){ // same key, different request
      payError={kind:'conflict'};draw();return;}
    if(code==='42501'||/create_sales/.test(msg)){ // permission denied
      payError=null;evalError={kind:'perm',message:"You don't have permission to record sales."};evalState='error';draw();return;}
    payError={kind:'retry'};draw(); // network / timeout / lost response / anything else — keep the key, offer Retry
  }
  async function finishCartReceipt(){
    const extras=extraLines(), r=saleResult;
    // A walk-in has no balance to re-read — skip the lookup entirely.
    const refreshed=walkin?{data:null,error:null}:await sb.rpc('lookup_client_by_phone',{
      p_business:S.biz.id,p_phone:cust.phone||phone
    });
    if(!isTillCurrent())return;
    const refreshedPoints=(walkin||refreshed.error)?null:Number(refreshed.data?.points);
    const packageResults=extras
      .filter(line=>line.type==='package'&&line._status==='done'&&line._packageResult)
      .map(line=>line._packageResult);
    const pointsReceipt=checkoutPointsReceiptV102({
      saleResult:r,packageResults,refreshedPoints
    });
    doneInfo={receipt:true,walkin,name:walkin?'Walk-in':cust.full_name,tender:tender==='paynow'?'External PayNow':tender,saleId:r?r.saleId:null,
      lines:r?r.lines.map(l=>({label:l.label,qty:l.qty,amount:l.amount})):[],
      effects:r?(r.effects||[]):[],subtotal:r?r.subtotal:0,discount:r?r.discount:0,gst:r?r.gst:0,total:r?r.total:0,
      extras:extras.map(l=>({type:l.type,label:l.label,amount:l.unit_cents*l.qty,
        status:l._status==='failed'?'failed':'done',code:l._code||null,error:l._error||null,
        pointsEarned:l.type==='package'?Number(l._packageResult?.pointsEarned||0):0,
        pointsTotal:l.type==='package'&&Number.isFinite(Number(l._packageResult?.pointsTotal))
          ?Number(l._packageResult.pointsTotal):null})),
      hasSale:!!r,extrasTotal:extrasTotalCents(),
      /* v215: the receipt is where a minimum-spend welcome offer becomes redeemable, because
         only now does a real sale exist to prove the spend against. Withheld when the sale
         falls short, so staff are never shown a button the server will refuse. */
      welcomeOfferV215:(!walkin&&catalog?.customerWelcomeOffer&&r&&r.saleId
        &&Number(r.total)>=(Number(catalog.customerWelcomeOffer.min_spend_cents)||0))
        ?{label:catalog.customerWelcomeOffer.reward_label||'Free item',saleId:r.saleId}:null,

      pointsEarned:pointsReceipt.pointsEarned,
      pointsTotal:pointsReceipt.pointsTotal,
      pointsBalanceConsistent:pointsReceipt.balanceConsistent,
      duplicate:r?r.duplicate:false,businessName:S.biz.name,
      branchName:accessibleTillBranches.find(branch=>branch.id===tillBranchId)?.name||'',
      paidAt:new Date().toISOString(),paymentReference:null};
    checkoutError=null;clearCheckoutState({abandon:true});step=3;draw(); // V286: a finalised sale retires any stored PayNow request
  }
  function drawStep3(){
    if(doneInfo&&doneInfo.receipt)return drawCartReceipt();
    const outcome=legacySaleReceiptV145(doneInfo,tillUnitNounV430(catalog));
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:'Sale recorded. The screen is ready for the next customer.',iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card" style="text-align:center">
        ${CUI.icon('check',{size:32})}
        <h2 style="margin:8px 0 4px">${outcome.heading}</h2>
        ${outcome.pointsEarned>0
          ?`<p style="font-size:1.6rem;font-weight:700;letter-spacing:-.035em;color:var(--green);margin-top:4px;font-variant-numeric:tabular-nums">${outcome.message}</p>`
          :`<p class="muted">${outcome.message}</p>`}
        <p class="muted small" style="margin-top:6px">${esc(doneInfo.name)} · ${esc(doneInfo.method||'payment')} received${outcome.pointsTotal!=null?` · now ${outcome.pointsTotal} points total`:''}</p>
        ${canScanRedemption()&&doneInfo.saleId?`<button class="btn ghost" id="tRedeemOffer" style="width:100%;margin-top:16px;padding:14px">Redeem customer offer ${CUI.icon('scan',{size:20})}</button>`:''}
        <button class="btn" id="tNext" style="width:100%;margin-top:20px;padding:16px;font-size:16px">Next customer ${CUI.icon('forward',{size:20})}</button>
      </div>`;
    if($('tRedeemOffer'))$('tRedeemOffer').onclick=()=>openMerchantRedemptionScanner({
      businessId:S.biz.id,branchId:tillBranchId,
      saleId:doneInfo.saleId,customerName:doneInfo.name,isCurrent:isTillCurrent
    });
    $('tNext').onclick=resetToStart;
  }
  /* Cart-mode receipt: line labels (browsing prices) + the EVALUATION-authoritative breakdown
     (subtotal, applied discounts, GST, TOTAL) captured verbatim at finalise. Points earned are the
     sum of the core-sale and exact package-writer receipts, never a before/after balance delta. */
  function drawCartReceipt(){
    const d=doneInfo;
    const anyExtraFailed=d.extras.some(x=>x.status==='failed');
    const lineRows=d.lines.map(l=>`<li><span>${esc(l.label)}${l.qty>1?` ×${l.qty}`:''}</span><span>${money(l.amount)}</span></li>`).join('');
    const appliedEffects=(d.effects||[]).filter(e=>!(e&&(e.suppressed===true||e.suppression_reason)));
    const breakdown=d.hasSale?`<div class="ck-panel" style="text-align:left" aria-label="Amount charged">
        <div class="ck-row"><span>Subtotal</span><span>${money(d.subtotal)}</span></div>
        ${appliedEffects.map(effectRowHtml).join('')}
        ${d.gst>0?`<div class="ck-row ck-gst"><span>incl. GST</span><span>${money(d.gst)}</span></div>`:''}
        <div class="ck-total"><span>Total</span><span>${money(d.total)}</span></div>
      </div>`:'';
    const extraRows=d.extras.map(x=>{
      const failed=x.status==='failed';
      const name=x.type==='package'?`${esc(x.label)} ${failed?'(not sold)':`· sold${x.pointsEarned>0?` · +${x.pointsEarned} ${tillUnitNounV430(catalog)}`:''}`}`
        :`${esc(x.label)} ${failed?'(not enrolled)':'· enrolled'}`;
      return `<li><span>${name}</span><span>${failed?'—':money(x.amount)}</span></li>`;
    }).join('');
    /* V257: the receipt names one collected amount over both records — the sale and every extra
       that actually completed. A failed extra was never collected, so it is excluded. */
    const collectedV257=(d.hasSale?Number(d.total||0):0)
      +d.extras.filter(x=>x.status!=='failed').reduce((sum,x)=>sum+Number(x.amount||0),0);
    const extrasBlock=d.extras.length?`<div style="margin-top:12px;text-align:left"><b class="small">Also charged · own record</b>
      <ul class="till-receipt-lines">${extraRows}</ul>
      <div class="ck-panel" style="margin-top:8px"><div class="ck-total"><span>Total collected</span><span>${money(collectedV257)}</span></div></div></div>`:'';
    M().innerHTML=`${CUI.pageHeader({title:'Record sale',subtitle:anyExtraFailed?'Checkout saved. Some items did not finish.':'Checkout saved. Ready for the next customer.',iconName:'till',canWrite:canRecordSales,moduleLabel:'Record sale'})}
      <div class="card frontline-card till-cart-card pos-receipt" id="posReceiptV142" style="text-align:center">
        ${CUI.icon(anyExtraFailed?'info':'check',{size:32})}
        <p class="small" data-merchant-content style="margin:4px 0"><b>${esc(S.biz.legal_name||d.businessName||S.biz.name)}</b>${d.branchName?` · ${esc(d.branchName)}`:''}</p>
        ${S.biz.legal_name&&(d.businessName||S.biz.name)&&S.biz.legal_name!==(d.businessName||S.biz.name)?`<p class="muted small" data-merchant-content style="margin:0">trading as ${esc(d.businessName||S.biz.name)}</p>`:''}
        ${S.biz.registration_number?`<p class="muted small" data-merchant-content style="margin:0">Reg. no. ${esc(S.biz.registration_number)}</p>`:''}
        ${S.biz.gst_registered?'':'<p class="muted small" style="margin:0">Not GST registered</p>'}
        <p class="muted small" style="margin:0">${esc(d.paidAt?sgt(d.paidAt):sgt(new Date().toISOString()))}${d.saleId?` · Receipt ${esc(String(d.saleId).slice(0,8).toUpperCase())}`:''}</p>
        <h2 style="margin:8px 0 4px">${d.duplicate?'Already recorded':anyExtraFailed?'Mostly done':'Done'}</h2>
        ${d.walkin?`<p class="muted">Walk-in — no points earned</p>`
          :d.pointsEarned>0
          ?`<p style="font-size:24px;font-weight:700;letter-spacing:-.03em;color:var(--green);margin-top:2px;font-variant-numeric:tabular-nums">+${d.pointsEarned} ${tillUnitNounV430(catalog)}</p>`
          :d.hasSale?(d.duplicate
          ?`<p class="muted">This sale was already recorded — no extra points added.</p>`
          :`<p class="muted small">No points earned for this purchase.</p>`)
          :`<p class="muted small">No points-earning items — none earned.</p>`}
        ${d.hasSale?`<ul class="till-receipt-lines" style="text-align:left">${lineRows}</ul>${breakdown}`:''}
        ${extrasBlock}
        ${d.welcomeOfferGivenV215
          ?`<p class="ok small" role="status" style="margin-top:10px">${esc(d.welcomeOfferGivenV215)} given free — welcome offer used.</p>`
          :d.welcomeOfferV215
          ?`<div class="permission-banner welcome-offer-v215" style="margin-top:12px;text-align:left"><b>Welcome offer unlocked</b>
              <p class="small" style="margin:5px 0">This sale meets the minimum, so ${esc(d.welcomeOfferV215.label)} is free for this first-time customer.</p>
              <button type="button" class="btn primary sm" id="tWelcomeReceiptRedeemV215">Give ${esc(d.welcomeOfferV215.label)}</button></div>`
          :''}
        <p class="muted small" style="margin-top:8px">${esc(d.name)} · ${esc(d.tender||'payment')} received</p>
        ${d.pointsTotal!=null?`<p class="small" data-merchant-content style="margin:2px 0 0">${tillUnitNounV430(catalog)==='stamps'?`Total stamps earned to date: <b>${d.pointsTotal}</b>`:`Points balance after this visit: <b>${d.pointsTotal}</b>`}</p>`:''}
        ${d.paymentReference?`<p class="muted small">Provider reference: ${esc(d.paymentReference)}</p>`:''}
        ${anyExtraFailed?`<p class="err" role="alert" style="margin-top:10px">Some items could not be completed. Reopen this customer to try again — the recorded sale will not be charged twice.</p>`:''}
        ${!d.walkin&&canScanRedemption()&&d.saleId?`<button class="btn ghost" id="tRedeemOffer" style="width:100%;margin-top:16px;padding:14px">Redeem customer offer ${CUI.icon('scan',{size:20})}</button>`:''}
        ${d.walkin?'':`<div class="receipt-qr-block" style="margin-top:16px;padding-top:14px;border-top:1px solid var(--hair)">
          <div id="receiptWalletQr" style="display:flex;justify-content:center"></div>
          <p class="muted small" style="margin-top:8px">Scan to open your rewards, points and past visits at ${esc(S.biz.name)}.</p>
        </div>`}
        <button class="btn ghost no-print" id="tPrintReceiptV142" style="width:100%;margin-top:16px;padding:14px">Print receipt</button>
        <button class="btn no-print" id="tNext" style="width:100%;margin-top:10px;padding:16px;font-size:16px">Next customer ${CUI.icon('forward',{size:20})}</button>
      </div>`;
    if($('tRedeemOffer'))$('tRedeemOffer').onclick=()=>openMerchantRedemptionScanner({
      businessId:S.biz.id,branchId:tillBranchId,
      saleId:d.saleId,customerName:d.name,isCurrent:isTillCurrent
    });
    /* v215: the sale that unlocked the offer is passed as the qualifying sale, so the server
       proves the minimum spend against a real record rather than trusting this screen. */
    if($('tWelcomeReceiptRedeemV215'))$('tWelcomeReceiptRedeemV215').onclick=()=>
      redeemWelcomeOfferV215(d.welcomeOfferV215?.saleId||null);
    /* V196 (owner: "allow for QRcode to let user to download or view").
       The QR points at THIS BUSINESS'S customer portal, not at a per-receipt URL. A public
       receipt link would put a purchase record — items, amounts, staff, the customer's points
       balance — behind nothing but an unguessable string, which is a PDPA decision rather than
       an implementation detail. The portal shows the same customer their own receipt history
       once they are signed in, so the scan reaches the same information without publishing it.
       Walk-in sales get no QR: there is no customer to show anything to. */
    const receiptQrHost=$('receiptWalletQr');
    if(receiptQrHost&&S.biz.slug){
      /* V388 (owner, photo 2: "this qrcode brings me to a booking page for cubbly instead of
         revealing the qrcode"). It encoded the PUBLIC BOOKING PORTAL while the caption under it
         promised "your rewards, points and past visits" — so a customer who scanned their own
         receipt landed on a form to book another appointment. `wallet/<slug>` is the route that
         actually shows them what the caption says. */
      const walletUrl=publicAppUrl(`wallet/${encodeURIComponent(S.biz.slug)}`);
      /* And the second half of the same mark: "it should popup the qrcode for user to screenshot
         or download". The receipt code is 132px so the printed slip stays tidy; that is too small
         to photograph off a screen, so tapping it opens the same code big enough to scan and
         offers the PNG. */
      receiptQrHost.style.cursor='zoom-in';
      receiptQrHost.setAttribute('role','button');
      receiptQrHost.setAttribute('tabindex','0');
      receiptQrHost.setAttribute('title','Show this code larger');
      const openLargeV388=()=>openWalletQrDialogV388(walletUrl,S.biz.name||'this business');
      receiptQrHost.onclick=openLargeV388;
      receiptQrHost.onkeydown=event=>{
        if(event.key==='Enter'||event.key===' '){event.preventDefault();openLargeV388()}
      };
      void loadQrLibrary()
        .then(()=>{
          if(!receiptQrHost.isConnected)return;
          new QRCode(receiptQrHost,{text:walletUrl,width:132,height:132,correctLevel:QRCode.CorrectLevel.M});
        })
        .catch(()=>{
          if(!receiptQrHost.isConnected)return;
          /* The receipt must still be complete without the CDN: print the link as text. */
          receiptQrHost.innerHTML=`<span class="small" style="word-break:break-all">${esc(walletUrl)}</span>`;
        });
    }
    $('tPrintReceiptV142').onclick=()=>printPosReceiptV385();
    $('tNext').onclick=resetToStart;
  }

  /* A phone handed in from the global app-bar search starts step 1 pre-filled and, when it is a
     complete number, runs the same lookup a keypad tap would (lookup_client_by_phone) — no new
     call, just a jump straight to the customer's card. */
  if(pendingTillPhone){phone=String(pendingTillPhone).replace(/\D/g,'').slice(0,8);pendingTillPhone='';}
  draw();
  if(readPaynowRequestV142())requestAnimationFrame(()=>resumePaynowPaymentV142());
  if(pendingTillRedemptionScan){
    pendingTillRedemptionScan=false;
    if(canScanRedemption())requestAnimationFrame(()=>{
      if(isTillCurrent())$('tScanRedemption')?.click();
    });
  }
  if(phone.length===8)doFind();
}

/* ---------- sales ---------- */
function sgLedgerDateV154(iso){
  const fallback={date:'—',time:''};
  if(!iso)return fallback;
  const d=new Date(iso);
  if(Number.isNaN(d.getTime()))return fallback;
  return {
    date:new Intl.DateTimeFormat('en-SG',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Singapore'}).format(d),
    time:new Intl.DateTimeFormat('en-SG',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Asia/Singapore'}).format(d)
  };
}
function saleRecordStatusV154(s,w={}){
  if(s.reversal_of)return {label:'Reversal',tone:'no',details:`Compensating reversal row. Audit record id of the sale it reverses: ${s.reversal_of}`};
  /* V287: this was the last line in the Sales audit disclosure that dropped a bare UUID into
     prose. It follows the two V267 lines above: the id stays, because a reconciler inside this
     collapsed disclosure genuinely needs the key, but it is named as a record id instead of
     reading like a person's name.
     V290: it also moved ABOVE the Reversed branch, and the server finally sends the keys it
     reads. A v84 amount correction ALWAYS writes a reversal row, so w.reversal_sale_id is set on
     the corrected original — while Reversed was tested first, this branch could never be reached
     even once the linkage arrived, and a correction went on reading as a cancellation. */
  if(w.correction_sale_id||w.corrected_sale_id||s.corrected_by){
    const ref=w.correction_sale_id||w.corrected_sale_id||s.corrected_by;
    return w.corrected_sale_id&&!w.correction_sale_id
      ?{label:'Correction',tone:'new',details:`Replacement sale row, written to correct an earlier amount. Audit record id of the sale it corrects: ${ref}`}
      :{label:'Corrected',tone:'new',details:`Original sale row, later corrected. Audit record id of the correction: ${ref}`};
  }
  if(w.reversal_sale_id)return {label:'Reversed',tone:'off',details:`Original sale row, fully reversed. Audit record id of the reversal: ${w.reversal_sale_id}`};
  return {label:'Sale',tone:'ok',details:'Original sale row.'};
}
async function salesPage(){
  /* Paint the page shell BEFORE the ledger queries: a blank white main is not a load
     state, and a failed query must leave a retryable card in place, not an empty page. */
  const routeMain=M(),isCurrent=()=>routeMain.isConnected&&M()===routeMain;
  /* V291: Export CSV is only offered on the render that has a ledger behind it. The loading,
     denied and load-error headers reuse the same markup WITHOUT it, so the page never paints a
     download button that has nothing to download and no handler bound to it. */
  const salesHeadHtmlV291=(withExport=false)=>`<header class="v150-titlebar"><div class="cui-page-title">${CUI.icon('sales',{size:24})}<div><h1>Sales</h1><p>Every sale you have recorded. Fix or cancel one here.</p></div></div><div class="v150-title-actions">${withExport?CUI.action({id:'salesExportV291',label:'Export CSV',iconName:'export',variant:'secondary',className:'sm'}):''}<a class="btn" href="#/till">${CUI.icon('till',{size:16})}<span>Record sale</span></a></div></header>`;
  const salesHead=salesHeadHtmlV291(false);
  routeMain.innerHTML=`${salesHead}
    <section class="card sales-ledger-card" id="salesShell"><div class="v150-soft-head"><b>Sales ledger</b><p>A sale is never deleted. Cancel one and both rows stay, so the numbers always add up.</p></div>
      <div style="margin-top:8px">${CUI.tableSkeleton({rows:6,columns:7})}</div></section>`;
  /* V287: without this guard a role that cannot read Sales fell straight through to the ledger
     query, and RLS answered with zero rows — so a permission denial was painted as "No sales
     match these filters". Never show an empty result where the truthful answer is "you cannot
     see this". */
  if(!canReadModule('sales')){
    routeMain.innerHTML=`${salesHead}<section class="card">${CUI.emptyState({iconName:'info',title:'Sales access needed',body:'Ask the owner for Sales access to see this ledger. This is a permission limit, not an empty ledger.'})}</section>`;
    return;
  }
  /* V287: the companion `clients` fetch here pulled EVERY customer row in the business, paged,
     on every open of this page — and nothing ever read it. Customer names arrive embedded on
     each sale row (`clients(full_name)`) and the Customer search filters that same text. */
  const [
    {data:saleStaff,error:staffError}
  ]=await Promise.all([
    fetchAllRowsResult(()=>sb.from('staff').select('id,full_name,user_id',{count:'exact'}).eq('business_id',S.biz.id).eq('active',true).order('full_name').order('id'))]);
  if(!isCurrent())return;
  const salesLoadError=staffError;
  if(salesLoadError){
    const shell=$('salesShell');
    if(shell)shell.innerHTML=`<div class="err" role="alert"><b>Sales could not be loaded. Nothing was changed.</b><p class="muted small" style="margin-top:5px">${esc(salesLoadError.message||'Please try again.')}</p></div>
      <div style="margin-top:16px">${CUI.action({id:'salesRetry',label:'Retry',iconName:'retention'})}</div>`;
    const retry=$('salesRetry');if(retry)retry.onclick=()=>salesPage();
    return;
  }
  const saleTeam=saleStaff||[];
  const signedInStaff=saleTeam.find(person=>person.user_id===S.user?.id);
  /* V266 (owner, in red on the Sales page: "I tried to filter by dates & click apply but
     cannot, please solve!!!"). The defaults are named once so Clear filters can restore the
     dates too — it used to reset only the four non-date controls, so a range narrowed down to
     nothing could not be undone by the button whose whole job is undoing filters. */
  const salesDefaultToV266=sgDateInputValue(),salesDefaultFromV266=shiftSgDateInput(salesDefaultToV266,-29);
  /* V291: the filtered answer in full (counts, export, payment-state filtering) and how much of
     it is currently painted. */
  const SALES_PAGE_SIZE_V291=50;
  let salesFilteredRowsV291=[],salesWorkflowV291={},salesVisibleCountV291=SALES_PAGE_SIZE_V291;
  M().innerHTML=`${salesHeadHtmlV291(true)}
    <section class="card sales-ledger-card"><div class="v150-soft-head"><b>Sales ledger</b><p>A sale is never deleted. Cancel one and both rows stay, so the numbers always add up.</p></div>
      <div class="sales-filter-panel" aria-label="Sales filters">
        <div class="sales-filter-row">
          <div><label for="salesFrom">From</label><input type="date" id="salesFrom" value="${salesDefaultFromV266}"></div>
          <div><label for="salesTo">To</label><input type="date" id="salesTo" value="${salesDefaultToV266}"></div>
          <div><label for="salesCustomer">Customer search</label><input id="salesCustomer" type="search" placeholder="Name"></div>
        </div>
        <div class="sales-filter-row secondary">
          <div><label for="salesStaff">Team member</label><select id="salesStaff"><option value="">All staff</option>${saleTeam.map(person=>`<option value="${person.id}">${esc(person.full_name||'Team member')}</option>`).join('')}</select></div>
          <div><label for="salesType">Sale type</label><select id="salesType"><option value="">All types</option><option value="quick_sale">Quick sale</option><option value="service">Service</option><option value="package">Package</option><option value="gift_card">Gift card</option><option value="membership">Membership</option></select></div>
          <div><label for="salesPayment">Payment state</label><select id="salesPayment"><option value="">All states</option><option value="true">Paid</option><option value="false">Unpaid</option></select></div>
          <button class="btn sm" id="salesApply">Apply filters</button>
        </div>
        <div class="row" style="gap:12px;align-items:center;flex-wrap:wrap"><button class="btn ghost sm" id="salesClear">Clear filters</button><span class="muted small" id="salesFilterSummary" role="status" aria-live="polite"></span></div>
      </div>
      <div id="recent" style="margin-top:8px">${CUI.tableSkeleton({rows:6,columns:7})}</div></section>`;
  const salesFilterNoteV266=(text,tone='')=>{
    const note=$('salesFilterSummary');if(!note)return;
    note.textContent=text;note.className=tone==='warn'?'small':'muted small';
    note.style.color=tone==='warn'?'#C24135':'';
  };
  async function loadRecent(){
    const from=$('salesFrom')?.value,to=$('salesTo')?.value,staff=$('salesStaff')?.value,type=$('salesType')?.value,paid=$('salesPayment')?.value;
    if(from&&to&&from>to){salesFilterNoteV266('The From date is after the To date. Nothing was filtered.','warn');return}
    const applyButton=$('salesApply');
    if(applyButton)CUI.setButtonBusy(applyButton,{busy:true,label:'Applying…'});
    try{
    let query=sb.from('sales').select('*, clients(full_name), staff(full_name)').eq('business_id',S.biz.id);
    /* V266: the To boundary was built as `<date>T23:59`, which drops the final 59 seconds of
       the chosen day — a sale recorded at 23:59:30 SGT fell outside a range that named its own
       date. Singapore calendar days are half-open instants: [From 00:00 SGT, To+1 day 00:00 SGT). */
    if(from)query=query.gte('occurred_at',sgDateBoundary(from,0));
    if(to)query=query.lt('occurred_at',sgDateBoundary(to,1));
    /* V260: the per-page Branch filter was struck out — the top bar's branch scope
       (selectedBranchId) is the single source of truth for which branch the query covers. */
    if(selectedBranchId)query=query.eq('branch_id',selectedBranchId);
    if(staff)query=query.eq('staff_id',staff);
    if(type)query=query.eq('kind',type);
    const {data:sl,error}=await fetchAllRowsResult(()=>query.order('occurred_at',{ascending:false}).order('id',{ascending:false}));
    if(error){fail(error);salesFilterNoteV266('These filters could not be applied. The rows below are unchanged.','warn');return}
    const workflow=await loadReversalWorkflows(null,Math.max(100,(sl||[]).length)).catch(e=>{fail(e);return null});
    const W=Object.fromEntries((workflow?.sales||[]).map(x=>[x.id,x]));
    const customerSearch=String($('salesCustomer')?.value||'').trim().toLowerCase();
    let rows=customerSearch?(sl||[]).filter(s=>String(s.clients?.full_name||'Walk-in').toLowerCase().includes(customerSearch)):(sl||[]);
    /* V266: Payment state used to filter on `sales.paid`, a column that does not exist —
       PostgREST answers 42703 and the WHOLE ledger read fails, so choosing Paid or Unpaid left
       the previous rows sitting on screen and Apply looked dead. Settlement lives in
       `payments`, one row per taking, so the state is derived from whether the sale is
       referenced there. */
    let paymentStateApplied=!paid;
    if(paid){
      const ids=rows.map(row=>row.id);
      try{
        const settled=new Set((ids.length?await fetchRowsByIds('payments','sale_id',ids,'sale_id'):[]).map(row=>row.sale_id));
        rows=rows.filter(row=>settled.has(row.id)===(paid==='true'));
        paymentStateApplied=true;
      }catch(paymentError){fail(paymentError)}
    }
    /* V291 (audit follow-up). fetchAllRowsResult pages the WHOLE filtered ledger — a year of a
       busy cafe is tens of thousands of rows — and every one of them was turned into table
       markup on each Apply. The full set is still fetched, because the count summary, the CSV
       export and the payment-state filter all have to act on the complete answer; only the
       PAINT is now bounded. Load more extends the painted window; it never re-queries, so the
       rows already on screen cannot shuffle underneath the person reading them. */
    salesFilteredRowsV291=rows;salesWorkflowV291=W;
    salesVisibleCountV291=Math.min(rows.length,SALES_PAGE_SIZE_V291);
    renderSalesRowsV291();
    /* V266: pressing Apply with a range that happens to contain the same sales used to change
       nothing at all on screen, which reads as a broken button. State the range that is now in
       force and how many rows it matched, next to the control that set it. */
    const period=`${from?dashboardScheduleDayLabelV252(from):'the earliest sale'} to ${to?dashboardScheduleDayLabelV252(to):'the latest sale'}`;
    salesFilterNoteV266(paymentStateApplied
      ?`Showing ${rows.length} ${rows.length===1?'sale':'sales'} · ${period}`
      :`Showing ${rows.length} ${rows.length===1?'sale':'sales'} · ${period} · payment state could not be read, so it was not applied`,
      paymentStateApplied?'':'warn');
    }finally{
      if(applyButton?.isConnected)CUI.setButtonBusy(applyButton,{busy:false});
    }
  }
  function renderSalesRowsV291(){
    const host=$('recent');if(!host)return;
    const rows=salesFilteredRowsV291,W=salesWorkflowV291;
    const shown=rows.slice(0,salesVisibleCountV291);
    host.innerHTML=(rows&&rows.length)?`<div class="cui-table-wrap" tabindex="0" role="region" aria-label="Sales ledger"><table data-responsive="true"><tr><th>When</th><th>Customer</th><th>Team member</th><th>Record status</th><th class="num">Gross</th><th class="num">Net</th><th></th></tr>
      ${shown.map(s=>{const w=W[s.id]||{},when=sgLedgerDateV154(s.occurred_at),status=saleRecordStatusV154(s,w);return `<tr><td><span class="sales-date-v154"><b>${esc(when.date)}</b><span>${esc(when.time)}</span></span></td><td>${esc(s.clients?.full_name||'Walk-in')}</td>
        <td>${esc(s.staff?.full_name||'Unattributed')}</td>
        <td><span class="pill ${status.tone} record-status">${esc(status.label)}</span>${w.is_package_session?'<br><span class="muted small" data-workspace-i18n>Package session · no payment refund</span>':''}<details class="sales-audit-details"><summary>Audit details</summary><p class="muted small">${esc(status.details)}${w.refusal_reason?` ${esc(w.refusal_reason)}`:''}</p></details></td>
        <td class="num">${money(s.amount_cents)}</td><td class="num"><b>${money(Number(w.net_amount_cents??s.amount_cents))}</b></td>
        <td>${w.can_reverse?`<div class="row" style="gap:6px;flex-wrap:wrap">${s.kind==='quick_sale'&&s.amount_cents>0&&!s.reversal_of?`<button class="btn ghost sm" data-correct-sale="${s.id}">Amend</button>`:''}<button class="btn danger sm" data-reverse-kind="sale" data-reverse-id="${s.id}">Reverse</button></div>`:w.refusal_reason?`<span class="muted small">${esc(w.refusal_reason)}</span>`:''}</td></tr>`}).join('')}</table></div>
      <div class="row" style="margin-top:14px;gap:12px;flex-wrap:wrap;align-items:center"><span class="muted small" role="status" aria-live="polite">Showing ${shown.length} of ${rows.length} ${rows.length===1?'sale':'sales'}</span><span class="spacer"></span>${shown.length<rows.length?`<button class="btn ghost sm" type="button" id="salesLoadMoreV291">Load more</button>`:''}</div>`
      :CUI.emptyState({iconName:'sales',title:'No sales match these filters',body:'Try a wider date range or clear filters. Use Record sale when you need to create a new sale.'});
    bindReversalButtons(loadRecent);
    host.querySelectorAll('[data-correct-sale]').forEach(button=>button.onclick=()=>{
      const sale=rows.find(row=>row.id===button.dataset.correctSale);
      if(sale)openSaleAmountCorrectionDialog({
        ...sale,customer_name:sale.clients?.full_name||'Walk-in'
      },loadRecent);
    });
    const more=$('salesLoadMoreV291');
    if(more)more.onclick=()=>{
      salesVisibleCountV291=Math.min(rows.length,salesVisibleCountV291+SALES_PAGE_SIZE_V291);
      renderSalesRowsV291();
      /* Keep the reader where they were: focus the control they just pressed, or the summary
         line when the last page has been reached and the button is gone. */
      ($('salesLoadMoreV291')||$('recent'))?.focus?.();
    };
  }
  /* V291: the export mirrors the Customers export — same csvField/csvRows quoting, same
     download-prefix naming — and writes exactly the filtered set the summary line counts, not
     the painted window. */
  const salesExportV291=$('salesExportV291');
  if(salesExportV291)salesExportV291.onclick=()=>{
    const rows=salesFilteredRowsV291,W=salesWorkflowV291;
    if(!rows.length)return toast('No sales match these filters');
    const table=[['when','customer','team_member','type','record_status','gross','net'],
      ...rows.map(s=>{
        const w=W[s.id]||{},when=sgLedgerDateV154(s.occurred_at),status=saleRecordStatusV154(s,w);
        return [`${when.date} ${when.time}`,s.clients?.full_name||'Walk-in',s.staff?.full_name||'Unattributed',
          s.kind||'',status.label,(Number(s.amount_cents||0)/100).toFixed(2),
          (Number(w.net_amount_cents??s.amount_cents??0)/100).toFixed(2)];
      })];
    const blob=new Blob([csvRows(table)],{type:'text/csv;charset=utf-8'});
    const link=document.createElement('a');
    link.href=URL.createObjectURL(blob);link.download=`${BRAND.downloadPrefix}-sales.csv`;link.click();
    toast('CSV downloaded');
  };
  ['salesStaff','salesType','salesPayment'].forEach(id=>{const el=$(id);if(el)el.onchange=loadRecent});
  /* V266: the dates are committed by Apply filters, not by every keystroke inside the date
     input — a half-typed year would otherwise fire a query the owner never asked for. Editing
     one says so, so the button visibly has something to do. */
  ['salesFrom','salesTo'].forEach(id=>{const el=$(id);if(el)el.oninput=()=>salesFilterNoteV266('Dates changed — press Apply filters.')});
  $('salesApply').onclick=loadRecent;
  $('salesCustomer').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();loadRecent()}};
  $('salesClear').onclick=()=>{
    ['salesCustomer','salesStaff','salesType','salesPayment'].forEach(id=>$(id).value='');
    $('salesFrom').value=salesDefaultFromV266;$('salesTo').value=salesDefaultToV266;
    loadRecent();
  };
  loadRecent();
}

/* ---------- services ---------- */
async function servicesPage(){
  const routeMain=M(),isCurrent=()=>routeMain.isConnected&&M()===routeMain;
  const canWrite=canWriteModule('services');
  const canUploadCatalogueMedia=S.myRole==='owner';
  M().innerHTML=`<header class="v150-titlebar"><div class="cui-page-title">${CUI.icon('services',{size:24})}<div><h1>Services</h1><p>Manage what customers can book.</p></div></div>
    <div class="v150-title-actions">${canWrite?importBtn('services')+CUI.action({id:'openBundleForm',label:'Add bundle',variant:'secondary',className:'sm'})+CUI.action({id:'openServiceForm',label:'Add service',iconName:'add'}):''}</div></header>
    ${canWrite?'':`<div class="card" role="status" style="margin-bottom:16px"><b>Read-only services access</b><p class="muted small" style="margin-top:5px">You can review services and bundles. Ask for Services edit access to change them.</p></div>`}
    <div class="v150-segment" role="tablist" aria-label="Services catalogue"><button type="button" id="servicesSeg" aria-pressed="true">Services</button><button type="button" id="bundlesSeg" aria-pressed="false">Bundles</button></div>
    <div class="services-segment-body" id="serviceSegmentBody">${canWrite?`<div class="card" id="serviceFormCard" style="display:none;margin-bottom:16px"><div class="v150-soft-head"><b>Add service</b><p>Save one bookable service, then return to the catalogue.</p></div>
      <label for="sn">Name</label><input id="sn" placeholder="e.g. Signature Facial">
      <label for="sv">Variation (optional)</label><input id="sv" placeholder="e.g. 30 min, 60 min, Deep tissue">
      <p class="muted small" style="margin-top:5px">Use the same service name with different variations, durations and prices.</p>
      <label for="sp">Price (${S.biz.currency||'SGD'})</label><input id="sp" type="number" min="0" step="0.01">
      <label for="sd">Duration (minutes)</label><input id="sd" type="number" min="5" step="5" value="60">
      <!-- V325 (owner-authorized exception #3, 2026-08-14 Customer Interface cosmetics brief):
           buffer_before_min/buffer_after_min already existed on services with no UI anywhere.
           Two more fields on the existing add form, wired into the existing insert — no new
           save path, no new RPC. -->
      <label for="sbb">Buffer before (minutes)</label><input id="sbb" type="number" min="0" step="5" value="0">
      <label for="sba">Buffer after (minutes)</label><input id="sba" type="number" min="0" step="5" value="0">
      <div style="margin-top:16px" class="row"><button class="btn" id="sadd">Save service</button><button class="btn ghost sm" id="cancelServiceForm">Cancel</button></div></div>`:''}
    <div class="card"><div class="v150-soft-head"><b>Services catalogue</b><p>Active services can be selected for bookings and sales.</p></div><div id="slist" style="margin-top:8px">${CUI.tableSkeleton({rows:4,columns:5})}</div></div>
    <div id="commissionWrap"></div></div>`;
  /* Keep the list in memory so an add reflects INSTANTLY (one insert round-trip that
     returns the row, then local splice + re-render) instead of a second full re-fetch. */
  let svCache=[];
  function renderSvc(){
    const sv=svCache;
    $('slist').innerHTML=(sv&&sv.length)?`<div class="cui-table-wrap" tabindex="0" role="region" aria-label="Services catalogue"><table data-responsive="true"><tr><th>Service</th><th class="num">Price</th><th class="num">Mins</th><th>Status</th><th></th></tr>
      ${sv.map(s=>{
        const image=catalogueImageUrlV158(s);
        const photoAction=canUploadCatalogueMedia?cataloguePhotoInputHtmlV158({assetKind:'service',entityId:s.id,label:image?'Change photo':'Attach photo'}):'';
        return `<tr><td><div class="service-media-cell">${image?`<img class="catalogue-thumb" src="${esc(image)}" alt="" loading="lazy">`:`<span class="catalogue-thumb" aria-hidden="true">${CUI.icon('services',{size:20})}</span>`}<div><b>${esc(serviceDisplayName(s))}</b>${photoAction?`<div style="margin-top:6px">${photoAction}</div>`:''}</div></div></td><td class="num">${money(s.price_cents)}</td><td class="num">${s.duration_min}</td>
      <td><span class="pill ${s.active?'on':'off'}">${statusOnOff(s.active)}</span></td>
      <td>${canWrite?`<div class="row" style="gap:6px;flex-wrap:wrap"><button class="btn ghost sm" data-svc-edit="${s.id}">Edit</button><button class="btn ghost sm" onclick="toggleSvc('${s.id}',${!s.active})">${s.active?'Turn off':'Turn on'}</button></div>`:'<span class="muted small">View only</span>'}</td></tr>${canWrite&&editingServiceId===s.id?`<tr class="service-edit-row"><td colspan="5"><div class="v150-soft-head"><b>Edit service</b><p>Correct anything you typed wrongly. Changes apply to future bookings and sales; past records keep the price they were sold at.</p></div>
        <div class="field-grid">
          <div><label for="svcEditName">Name</label><input id="svcEditName" value="${esc(s.name||'')}"></div>
          <div><label for="svcEditVariant">Variation (optional)</label><input id="svcEditVariant" value="${esc(s.variant_label||'')}"></div>
          <div><label for="svcEditPrice">Price (${S.biz.currency||'SGD'})</label><input id="svcEditPrice" type="number" min="0" step="0.01" value="${((s.price_cents||0)/100).toFixed(2)}"></div>
          <div><label for="svcEditDuration">Duration (minutes)</label><input id="svcEditDuration" type="number" min="5" step="5" value="${Number(s.duration_min)||60}"></div>
          <div><label for="svcEditBufferBefore">Buffer before (minutes)</label><input id="svcEditBufferBefore" type="number" min="0" step="5" value="${Number(s.buffer_before_min)||0}"></div>
          <div><label for="svcEditBufferAfter">Buffer after (minutes)</label><input id="svcEditBufferAfter" type="number" min="0" step="5" value="${Number(s.buffer_after_min)||0}"></div>
        </div>
        <div class="row" style="margin-top:12px"><button class="btn sm" data-svc-save="${s.id}">Save changes</button><button class="btn ghost sm" data-svc-cancel="1">Cancel</button><span class="muted small" id="svcEditStatus" role="status" aria-live="polite"></span></div></td></tr>`:''}`;
      }).join('')}</table></div>`
      :CUI.emptyState({iconName:'services',title:'No services yet',body:'Add your first service so customers can book and staff can select it during checkout.'});
    if(canUploadCatalogueMedia)bindCataloguePhotoUploadsV158({onSaved:()=>load()});
    bindServiceEditors();
  }
  if(canWrite)$('sadd').onclick=async()=>{
    const name=$('sn').value.trim(),variant=$('sv').value.trim()||null,
      price=Math.round(parseFloat($('sp').value||'0')*100),dur=parseInt($('sd').value||'60');
    const bufferBefore=parseInt($('sbb')?.value||'0',10)||0,bufferAfter=parseInt($('sba')?.value||'0',10)||0;
    if(name.length<2) return toast('Name required');
    const btn=$('sadd');CUI.setButtonBusy(btn,{busy:true,label:'Saving…'});
    const {data,error}=await sb.from('services').insert({
      business_id:S.biz.id,name,variant_label:variant,price_cents:price,duration_min:dur,
      buffer_before_min:bufferBefore,buffer_after_min:bufferAfter
    }).select().single();
    CUI.setButtonBusy(btn,{busy:false});
    if(error) return fail(error);
    svCache=[...svCache,data].sort((a,b)=>a.name.localeCompare(b.name));
    renderSvc();
    toast('Service added');$('sn').value='';$('sv').value='';$('sp').value='';
    if($('sbb'))$('sbb').value='0';if($('sba'))$('sba').value='0';$('sn').focus();
    if($('serviceFormCard'))$('serviceFormCard').style.display='none';
  };
  if(canWrite&&$('openServiceForm'))$('openServiceForm').onclick=()=>{$('serviceFormCard').style.display='block';$('serviceSegmentBody').style.display='block';$('bundleSegmentBody').style.display='none';$('servicesSeg').setAttribute('aria-pressed','true');$('bundlesSeg').setAttribute('aria-pressed','false');$('sn')?.focus()};
  if(canWrite&&$('cancelServiceForm'))$('cancelServiceForm').onclick=()=>{$('serviceFormCard').style.display='none'};
  /* V183 (owner: "no edit function ... what if i key wrongly, then the service how can i remove
     the time?"). The catalogue could only be Disabled, so a typo in a price or duration was
     permanent — the only workaround was to disable the row and re-add it, which orphans its
     photo and its bookings. This edits the row in place. Past sales are untouched: they carry
     their own snapshotted price, so correcting the catalogue never rewrites history. */
  let editingServiceId=null;
  function bindServiceEditors(){
    document.querySelectorAll('[data-svc-edit]').forEach(b=>b.onclick=()=>{
      editingServiceId=b.dataset.svcEdit;renderSvc();
      document.getElementById('svcEditName')?.focus();
    });
    document.querySelectorAll('[data-svc-cancel]').forEach(b=>b.onclick=()=>{editingServiceId=null;renderSvc()});
    document.querySelectorAll('[data-svc-save]').forEach(b=>b.onclick=async()=>{
      const id=b.dataset.svcSave,status=$('svcEditStatus');
      const name=$('svcEditName').value.trim();
      const variant=$('svcEditVariant').value.trim()||null;
      const price=Math.round(parseFloat($('svcEditPrice').value||'0')*100);
      const duration=parseInt($('svcEditDuration').value||'0',10);
      const bufferBefore=parseInt($('svcEditBufferBefore')?.value||'0',10)||0;
      const bufferAfter=parseInt($('svcEditBufferAfter')?.value||'0',10)||0;
      if(name.length<2){if(status)status.textContent='Give the service a name.';return}
      if(!(price>=0)){if(status)status.textContent='Enter a price of 0 or more.';return}
      if(!(duration>=5)){if(status)status.textContent='Enter a duration of at least 5 minutes.';return}
      CUI.setButtonBusy(b,{busy:true,label:'Saving…'});
      const {data,error}=await sb.from('services')
        .update({name,variant_label:variant,price_cents:price,duration_min:duration,
          buffer_before_min:bufferBefore,buffer_after_min:bufferAfter}).eq('id',id).select().limit(1);
      if(b.isConnected)CUI.setButtonBusy(b,{busy:false});
      if(error){if(status)status.textContent=ownerErrorText(error);return}
      const row=svCache.find(x=>x.id===id);
      if(row&&data&&data[0])Object.assign(row,data[0]);
      editingServiceId=null;renderSvc();toast('Service updated');
    });
  }
  window.toggleSvc=async(id,to)=>{
    if(!canWrite)return;
    const {error}=await sb.from('services').update({active:to}).eq('id',id);
    if(error)return fail(error);
    const s=svCache.find(x=>x.id===id);if(s)s.active=to;renderSvc();
  };
  async function load(){
    const [servicesResult,mediaMap]=await Promise.all([
      sb.from('services').select('*').eq('business_id',S.biz.id).order('name'),
      canUploadCatalogueMedia?loadCatalogueMediaVersionsV158().catch(error=>{console.warn('Catalogue media versions unavailable',error);return new Map()}):Promise.resolve(new Map())
    ]);
    const {data:sv,error}=servicesResult;
    if(!isCurrent())return;
    if(error){
      $('slist').innerHTML=`<div class="err">Services could not be loaded. <button class="btn ghost sm" id="servicesRetry">Retry</button></div>`;
      $('servicesRetry').onclick=load;return;
    }
    svCache=(sv||[]).map(service=>{
      const asset=mediaMap.get(catalogueMediaCacheKeyV158('service',service.id));
      return {...service,image_url:catalogueImageUrlV158(asset)||service.image_url||''};
    });renderSvc();
  }
  load();
  /* V180: the per-service commission override lives here now, next to the price it overrides.
     It is owner-only and self-guards on its mount point, so a non-owner simply gets nothing. */
  loadCommissionConfig();
  /* bundles */
  M().insertAdjacentHTML('beforeend',`<div class="services-segment-body" id="bundleSegmentBody" style="display:none">
    <div class="card">${canWrite?'<div id="bundleFormCard" style="display:none"><div class="v150-soft-head"><b id="bundleFormTitleV285">Add bundle</b><p>Bundle means several services sold together at one combined price. Packages remain separate.</p></div>':''}
      ${canWrite?`
      <label for="bnm">Name</label><input id="bnm" placeholder="e.g. Cut + Colour">
      <label for="bpr">Bundle price (${S.biz.currency||'SGD'})</label><input id="bpr" type="number" min="0" step="0.01">
      <label>Included services</label><div id="bsv" class="small"></div>
      <div style="margin-top:12px" class="row"><button class="btn sm" id="badd3">Save bundle</button><button class="btn ghost sm" id="cancelBundleForm">Cancel</button></div></div>`:''}
      <div class="v150-soft-head"><b>Bundles catalogue</b><p>Several services at one price. Packages remain in the Packages module.</p></div>
      <div id="blist3" style="margin-top:12px">${CUI.tableSkeleton({rows:3,columns:5})}</div></div></div>`);
  let bundleCacheV285=[],editingBundleIdV285=null;
  async function loadBR(){
    const [servicesResult,bundlesResult,productsResultV488]=await Promise.all([
      sb.from('services').select('id,name').eq('business_id',S.biz.id).eq('active',true).order('name'),
      /* nestly_v488: product members ride the same row; a pre-v488 server that has no product_id
         column answers this select with an error, which the existing loadError path reports
         honestly instead of painting a half-true catalogue. */
      sb.from('bundles').select('*, bundle_items(service_id, product_id, services(name), products(name))').eq('business_id',S.biz.id).order('name'),
      sb.from('products').select('id,name').eq('business_id',S.biz.id).eq('active',true).order('name')]);
    if(!isCurrent())return;
    const loadError=servicesResult.error||bundlesResult.error||productsResultV488.error;
    if(loadError){
      $('blist3').innerHTML=`<div class="err">Bundles could not be loaded. <button class="btn ghost sm" id="servicesBRRetry">Retry</button></div>`;
      $('servicesBRRetry').onclick=loadBR;return;
    }
    const sv2=servicesResult.data,bu=bundlesResult.data;
    if(canWrite)$('bsv').innerHTML=(sv2||[]).map(s=>`<label data-merchant-content style="display:inline-flex;gap:6px;margin:4px 10px 0 0;cursor:pointer;color:var(--ink)">
      <input type="checkbox" style="width:auto" data-bs="${s.id}">${esc(s.name)}</label>`).join('')||'<span class="muted">No active services yet — add them in the Services tab.</span>';
    if(canWrite&&$('bpvV488'))$('bpvV488').innerHTML=(productsResultV488.data||[]).map(pr=>`<label data-merchant-content style="display:inline-flex;gap:6px;margin:4px 10px 0 0;cursor:pointer;color:var(--ink)">
      <input type="checkbox" style="width:auto" data-bp-v488="${pr.id}">${esc(pr.name)}</label>`).join('')||'<span class="muted">No active products yet — add them in Products.</span>';
    /* V285: a bundle could be created and then never corrected — no rename, no reprice, no way
       to change what is in it, no way to switch it off and no way to remove it. bundles and
       bundle_items carry READ-only RLS, so the three controls below go through the V285 writers
       rather than table DML. */
    bundleCacheV285=bu||[];
    $('blist3').innerHTML=(bu&&bu.length)?`<div class="cui-table-wrap" tabindex="0" role="region" aria-label="Bundles catalogue"><table data-responsive="true"><tr><th>Bundle</th><th>Included services</th><th class="num">Price</th><th>Status</th><th></th></tr>${bu.map(b=>`<tr>
      <td><b data-merchant-content>${esc(b.name)}</b></td><td data-merchant-content>${(b.bundle_items||[]).map(i=>esc(i.services?.name||i.products?.name||'')).filter(Boolean).join(' + ')||'—'}</td><td class="num">${money(b.price_cents)}</td><td><span class="pill ${b.active?'on':'off'}">${statusOnOff(b.active)}</span></td>
      <td>${canWrite?`<div class="row" style="gap:6px;justify-content:flex-end">
        <button class="btn ghost sm" type="button" data-bundle-edit="${b.id}">Edit</button>
        <button class="btn ghost sm" type="button" data-bundle-toggle="${b.id}">${b.active?'Turn off':'Turn on'}</button>
        <button class="btn danger sm" type="button" data-bundle-delete="${b.id}">Delete</button>
      </div>`:'<span class="muted small">View only</span>'}</td></tr>`).join('')}</table></div>`
      :CUI.emptyState({iconName:'services',title:'No bundles yet',body:'Create a bundle when you want to sell several services together at one combined price.'});
    if(!canWrite)return;
    $('blist3').querySelectorAll('[data-bundle-edit]').forEach(button=>button.onclick=()=>openBundleEditV285(button.dataset.bundleEdit));
    $('blist3').querySelectorAll('[data-bundle-toggle]').forEach(button=>button.onclick=async()=>{
      const bundle=bundleCacheV285.find(item=>item.id===button.dataset.bundleToggle);
      if(!bundle)return;
      CUI.setButtonBusy(button,{busy:true,label:bundle.active?'Disabling…':'Enabling…'});
      const {error}=await sb.rpc('update_service_bundle_v285',{p_business:S.biz.id,p_bundle:bundle.id,
        p_name:null,p_price_cents:null,p_service_ids:null,p_active:!bundle.active});
      if(!isCurrent())return;
      if(error){CUI.setButtonBusy(button,{busy:false});return fail(error)}
      toast(bundle.active?'Bundle switched off':'Bundle switched on');
      await loadBR();
    });
    $('blist3').querySelectorAll('[data-bundle-delete]').forEach(button=>button.onclick=async()=>{
      const bundle=bundleCacheV285.find(item=>item.id===button.dataset.bundleDelete);
      if(!bundle)return;
      if(!await confirmActionV386(`Delete "${bundle.name}"? It disappears from the catalogue for good. If you only want to stop selling it, use Turn off instead — that keeps it here.`))return;
      CUI.setButtonBusy(button,{busy:true,label:'Deleting…'});
      const {error}=await sb.rpc('delete_service_bundle_v285',{p_business:S.biz.id,p_bundle:bundle.id});
      if(!isCurrent())return;
      if(error){CUI.setButtonBusy(button,{busy:false});return fail(error)}
      if(editingBundleIdV285===bundle.id)closeBundleFormV285();
      toast('Bundle deleted');
      await loadBR();
    });
  }
  /* Editing reuses the create form: same three inputs, same validation, one extra id in state.
     A second form would be a second place for the two to drift apart. */
  function closeBundleFormV285(){
    editingBundleIdV285=null;
    if($('bundleFormCard'))$('bundleFormCard').style.display='none';
    if($('bundleFormTitleV285'))$('bundleFormTitleV285').textContent='Add bundle';
    if($('badd3'))$('badd3').textContent='Save bundle';
    if($('bnm'))$('bnm').value='';
    if($('bpr'))$('bpr').value='';
    document.querySelectorAll('[data-bs],[data-bp-v488]').forEach(box=>{box.checked=false});
  }
  async function openBundleEditV285(bundleId){
    const bundle=bundleCacheV285.find(item=>item.id===bundleId);
    if(!bundle||!$('bundleFormCard'))return;
    editingBundleIdV285=bundleId;
    $('bundleFormCard').style.display='block';
    $('bundleFormTitleV285').textContent='Edit bundle';
    $('badd3').textContent='Save changes';
    $('bnm').value=bundle.name||'';
    $('bpr').value=(Number(bundle.price_cents||0)/100).toFixed(2);
    const included=new Set((bundle.bundle_items||[]).map(item=>item.service_id).filter(Boolean));
    const includedProductsV488=new Set((bundle.bundle_items||[]).map(item=>item.product_id).filter(Boolean));
    document.querySelectorAll('[data-bs]').forEach(box=>{box.checked=included.has(box.dataset.bs)});
    document.querySelectorAll('[data-bp-v488]').forEach(box=>{box.checked=includedProductsV488.has(box.dataset.bpV488)});
    $('bnm').focus();
  }
  if(canWrite)$('badd3').onclick=async()=>{
    const badd3=$('badd3');
    const name=$('bnm').value.trim();
    const picked=[...document.querySelectorAll('[data-bs]')].filter(x=>x.checked).map(x=>x.dataset.bs);
    const pickedProductsV488=[...document.querySelectorAll('[data-bp-v488]')].filter(x=>x.checked).map(x=>x.dataset.bpV488);
    if(name.length<2) return toast('Name the bundle');
    /* nestly_v488: the floor of 2 counts ITEMS, not services — one service plus one product is
       a real bundle, and a products-only bundle is one too. */
    if(picked.length+pickedProductsV488.length<2) return toast('Pick at least 2 items');
    const priceCents=Math.round(parseFloat($('bpr').value||'0')*100);
    /* nestly_v488: with products in the membership the save goes through the v488 writers. A
       services-only bundle keeps the v123/v285 writers it has always used — those are proven,
       and the CDN window means this bundle can be served before the migration is applied; the
       one case that NEEDS the new server (a mixed bundle) fails with an honest sentence rather
       than silently dropping the products. */
    const usesProductsV488=pickedProductsV488.length>0;
    const missingV488=error=>error?.code==='PGRST202'||error?.code==='42883';
    if(editingBundleIdV285){
      CUI.setButtonBusy(badd3,{busy:true,label:'Saving…'});
      const {error}=usesProductsV488
        ?await sb.rpc('update_bundle_v488',{p_business:S.biz.id,
          p_bundle:editingBundleIdV285,p_name:name,p_price_cents:priceCents,
          p_service_ids:picked,p_product_ids:pickedProductsV488,p_active:null})
        :await sb.rpc('update_service_bundle_v285',{p_business:S.biz.id,
          p_bundle:editingBundleIdV285,p_name:name,p_price_cents:priceCents,
          p_service_ids:picked,p_active:null});
      if(badd3.isConnected)CUI.setButtonBusy(badd3,{busy:false});
      if(error)return missingV488(error)
        ?toast('Product bundles need the latest Peekaa service update.')
        :fail(error);
      closeBundleFormV285();
      toast('Bundle updated');
      await loadBR();
      return;
    }
    const bundleSlot='nestly.services.createBundle.v123';
    const fingerprint=JSON.stringify([S.biz.id,name,priceCents,[...picked].sort(),[...pickedProductsV488].sort()]);
    CUI.setButtonBusy(badd3,{busy:true,label:'Saving…'});
    try{
      const {data,error}=usesProductsV488
        ?await sb.rpc('create_bundle_v488',{
          p_business:S.biz.id,p_name:name,p_price_cents:priceCents,
          p_service_ids:picked,p_product_ids:pickedProductsV488,
          p_idempotency_key:writeAttemptKey(bundleSlot,fingerprint)})
        :await sb.rpc('create_service_bundle_v123',{
          p_business:S.biz.id,p_name:name,p_price_cents:priceCents,
          p_service_ids:picked,p_idempotency_key:writeAttemptKey(bundleSlot,fingerprint)});
      if(error)return missingV488(error)
        ?toast('Product bundles need the latest Peekaa service update.')
        :fail(error);
      clearWriteAttempt(bundleSlot);
      toast(isReplayResult(data)?'Bundle already created — no duplicate':'Bundle created');
      $('bnm').value='';document.querySelectorAll('[data-bs],[data-bp-v488]').forEach(box=>{box.checked=false});
      if($('bundleFormCard'))$('bundleFormCard').style.display='none';
      await loadBR();
    }finally{
      if(badd3.isConnected)CUI.setButtonBusy(badd3,{busy:false});
    }
  };
  /* V183 (owner: "bundle does not work"). loadBR() ran once when the page mounted, so the
     "Included services" checkbox list was whatever existed at that moment. Add two services and
     open Bundles in the same visit and it still said "add services first" — with no way to pick
     anything, Save bundle could only ever answer "Pick at least 2 services". Re-read the list
     every time the Bundles view is opened. */
  if(canWrite&&$('openBundleForm'))$('openBundleForm').onclick=()=>{$('serviceSegmentBody').style.display='none';$('bundleSegmentBody').style.display='block';$('servicesSeg').setAttribute('aria-pressed','false');$('bundlesSeg').setAttribute('aria-pressed','true');closeBundleFormV285();$('bundleFormCard').style.display='block';loadBR();$('bnm')?.focus()};
  if(canWrite&&$('cancelBundleForm'))$('cancelBundleForm').onclick=()=>closeBundleFormV285();
  $('servicesSeg').onclick=()=>{$('serviceSegmentBody').style.display='block';$('bundleSegmentBody').style.display='none';$('servicesSeg').setAttribute('aria-pressed','true');$('bundlesSeg').setAttribute('aria-pressed','false')};
  $('bundlesSeg').onclick=()=>{$('serviceSegmentBody').style.display='none';$('bundleSegmentBody').style.display='block';$('servicesSeg').setAttribute('aria-pressed','false');$('bundlesSeg').setAttribute('aria-pressed','true');loadBR()};
  loadBR();
  const showServiceProductDeductionV157=false;
  if(showServiceProductDeductionV157){
    /* products used per service */
    M().insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:16px"><b>Products used per service</b>
      <p class="muted small" style="margin:6px 0 10px">Completing an appointment with this service auto-deducts these products (FEFO).</p>
      ${canWrite?`<div class="row"><select id="lsvc"></select><select id="lprod"></select>
      <input id="lqty" type="number" min="1" value="1" style="max-width:90px"><button class="btn sm" id="ladd">Add</button></div>`:''}
      <div id="llist" style="margin-top:12px"></div></div>`);
    async function loadSP(){
      const [serviceResult,productResult]=await Promise.all([
        sb.from('services').select('id,name').eq('business_id',S.biz.id).order('name'),
        sb.from('products').select('id,name').eq('business_id',S.biz.id).order('name')]);
      if(!isCurrent())return;
      if(serviceResult.error||productResult.error){
        $('llist').innerHTML=`<div class="err">Service product links could not be loaded. <button class="btn ghost sm" id="serviceProductsRetry">Retry</button></div>`;
        $('serviceProductsRetry').onclick=loadSP;return;
      }
      const sv3=serviceResult.data,pr3=productResult.data;
      if(canWrite){
        $('lsvc').innerHTML=(sv3&&sv3.length)?sv3.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join(''):'<option value="">— add a service first —</option>';
        $('lprod').innerHTML=(pr3&&pr3.length)?pr3.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join(''):'<option value="">— add a product first —</option>';
      }
      const ids=(sv3||[]).map(s=>s.id);
      let links=[];
      if(ids.length){
        const {data:sp,error}=await sb.from('service_products').select('service_id, product_id, qty, services(name), products(name)').in('service_id',ids);
        if(!isCurrent())return;
        if(error){$('llist').innerHTML=`<div class="err">Service product links could not be loaded. <button class="btn ghost sm" id="serviceProductsRetry">Retry</button></div>`;$('serviceProductsRetry').onclick=loadSP;return}
        links=sp||[];
      }
      $('llist').innerHTML=links.length?links.map(l=>`<div class="row small" style="padding:6px 0;border-bottom:1px solid var(--line)">
        <span><b>${esc(l.services?.name||'—')}</b> ← ${l.qty} × ${esc(l.products?.name||'—')}</span>
        <span class="spacer"></span>${canWrite?`<button class="btn ghost sm" onclick="rmSP('${l.service_id}','${l.product_id}')">Remove</button>`:'<span class="muted small">View only</span>'}</div>`).join('')
        :'<p class="muted small">No product links yet.</p>';
    }
    if(canWrite)$('ladd').onclick=async()=>{
      if(!$('lsvc').value||!$('lprod').value) return toast('Pick a service and a product');
      const {error}=await sb.from('service_products').upsert({service_id:$('lsvc').value,product_id:$('lprod').value,qty:parseInt($('lqty').value||'1')});
      if(error) return fail(error);
      toast('Linked');loadSP();
    };
    window.rmSP=async(sid,pid)=>{
      if(!canWrite)return;
      const {error}=await sb.from('service_products').delete().eq('service_id',sid).eq('product_id',pid);
      if(error) return fail(error);
      toast('Removed');loadSP();
    };
    loadSP();
  }
}

