    $('ac').innerHTML=`<option value="">${clients.length?'Choose a customer':'Add a customer first'}</option>${matches.map(client=>`<option value="${client.id}">${esc(customerLabel(client))}</option>`).join('')}`;
    $('ac').value=matches.some(client=>client.id===selectedId)?selectedId:'';
    const help=$('appointmentCustomerHelp');
