async function loadBranchContactCardV325(){
  const host=$('ciBranchContactV325');
  if(!host)return;
  const {data:branches,error}=await sb.from('branches').select('id,name,address,phone,is_default,active')
    .eq('business_id',S.biz.id).eq('active',true).order('is_default',{ascending:false}).order('name');
  if(!host.isConnected)return;
  if(error){host.innerHTML=`<p class="err small">${esc(error.message||'Branches could not be loaded.')}</p>`;return}
  const list=branches||[];
  if(!list.length){host.innerHTML='<p class="muted small">No branches yet. <a href="#/branches">Add one in Branches</a>.</p>';return}
  host.innerHTML=list.map((b,i)=>`<div class="ci-branch-row-v325" style="${i?'margin-top:14px;padding-top:14px;border-top:1px solid var(--line)':''}">
      <b data-merchant-content>${esc(b.name)}</b>${b.is_default?' <span class="pill new">Default</span>':''}
      <div class="split" style="margin-top:8px">
        <div><label for="ciBrPhoneV325-${esc(b.id)}">Phone</label><input id="ciBrPhoneV325-${esc(b.id)}" value="${esc(b.phone||'')}"></div>
        <div><label for="ciBrAddrV325-${esc(b.id)}">Address</label><input id="ciBrAddrV325-${esc(b.id)}" value="${esc(b.address||'')}"></div>
      </div>
      <div style="margin-top:10px"><button class="btn ghost sm" data-branch-save-v325="${esc(b.id)}">Save</button></div>
    </div>`).join('');
  host.querySelectorAll('[data-branch-save-v325]').forEach(button=>button.onclick=async()=>{
    const id=button.dataset.branchSaveV325;
    const phone=($('ciBrPhoneV325-'+id)?.value||'').trim()||null;
    const address=($('ciBrAddrV325-'+id)?.value||'').trim()||null;
    CUI.setButtonBusy(button,{busy:true,label:'Saving…'});
    const {error:saveError}=await saveBranchFieldsV325(id,{phone,address});
    if(button.isConnected)CUI.setButtonBusy(button,{busy:false});
    if(saveError)return fail(saveError);
    toast('Branch details saved');
  });
}
/* V325 (owner-authorized exception #3). Buffer times are per-service, so a whole services list
   does not belong on a business-profile-style settings screen — a pointer card, matching how
   this same page already points at Branches, is enough. */
/* ===================== nestly_v418 — GALLERY AND LINKS ON THE BUSINESS PROFILE ================
   Owner, photo 10, drawn beside Save Profile:
     "1. i want to add another segment in customer app, which is editable here — i want to be able
         to upload menu or other gallery photos to business profile
      2. add biz social media links"
   The one item in that batch that is a FEATURE rather than a correction. Built on what already
   exists rather than beside it: the same storage bucket and path grammar as every other business
   image, the same owner gate as the logo, and the customer sees it through the read that already
   carries the name, logo, industry and bio.
   Both editors are REPLACE-SET — the list on screen becomes the list in the database — so there is
   no add/remove protocol to keep in step and pressing Save twice is harmless. */
const GROW_GALLERY_MAX_V418=12;
/* Only the platforms the customer app can actually draw an icon for. A free-text platform is a row
   that renders as nothing, and the server refuses one anyway (business_social_links_v418_platform_check),
   so offering it here would be inviting an error. */
const BUSINESS_SOCIAL_PLATFORMS_V418=Object.freeze([
  ['website','Website'],['instagram','Instagram'],['facebook','Facebook'],['tiktok','TikTok'],
  ['whatsapp','WhatsApp'],['youtube','YouTube'],['telegram','Telegram'],['xiaohongshu','Xiaohongshu']
]);
/* nestly_v471 (owner, photo 2: the whole Links block ringed, the toast "The instagram link must
   start with https://" ringed under it, and "all link don't need to start with https:// "
   written beside both). The owner typed "Instagram.com" and the form refused to save ANY of the
   eight fields until they went back and prefixed it by hand.
   The https rule itself is not negotiable — it is a CHECK on business_social_links_v418 and the
   customer render filters on it too — so this NORMALISES instead of loosening. A bare host gets
   the scheme it obviously meant; http:// is upgraded rather than rejected, since the stored value
   has to be https either way and downgrading a customer to plaintext was never the alternative.
   Anything carrying a DIFFERENT scheme is still refused: `javascript:` and `data:` must never
   reach an anchor on a customer's phone, and silently rewriting one into an https URL would
   invent a destination the owner did not type.
   The host must contain a dot, which is what separates "Instagram.com" (meant a URL) from
   "our shop" or "@cubbly" (did not). Those still get told, and the message now says what to do.
   Returns '' for blank (the field is being cleared, which is how a link is removed) and null for
   "this cannot be made into a link". */
function businessLinkNormaliseV471(raw){
  const value=String(raw??'').trim();
  if(!value)return '';
  const scheme=value.match(/^([a-z][a-z0-9+.-]*):/i)?.[1]?.toLowerCase();
  if(scheme&&scheme!=='http'&&scheme!=='https')return null;
  const candidate=scheme?value.replace(/^http:/i,'https:'):`https://${value}`;
  let parsed;
  try{parsed=new URL(candidate)}catch{return null}
  if(parsed.protocol!=='https:')return null;
  /* A hostname with no dot is a word, not a domain. 'localhost' is deliberately not special-cased
     — a customer's phone cannot reach the owner's localhost. */
  if(!/^[^.\s]+(\.[^.\s]+)+$/.test(parsed.hostname))return null;
  return parsed.href;
}
let businessProfileExtrasV418=null;   /* {gallery:[...], social_links:[...]} once read */
let businessProfileExtrasBusyV418=false;
let businessProfileExtrasErrorV418='';
async function uploadGalleryPhotoV418(file){
  if(!S.biz?.id)throw new Error('Business context is required.');
  if(!file)throw new Error('Choose a photo first.');
  const ext=({'image/png':'png','image/jpeg':'jpg','image/webp':'webp'})[file.type];
  if(!ext)throw new Error('Use a PNG, JPG or WebP image.');
  if(file.size>10*1024*1024)throw new Error('Use an image under 10 MB.');
  /* Same grammar app.v95_storage_path_owned enforces — the folder name is what makes the storage
     policy allow the write, so it is not a naming preference. */
  const objectPath=`${S.biz.id}/gallery/${crypto.randomUUID()}.${ext}`;
  const {error}=await sb.storage.from('business-public')
    .upload(objectPath,file,{contentType:file.type,upsert:false});
  if(error)throw new Error(error.message||'The photo could not be uploaded.');
  return `${SB_URL.replace(/\/+$/,'')}/storage/v1/object/public/business-public/${objectPath}`;
}
